  /// Belonged list's {@link todo_app_lists.id}.
  todo_app_list_id String @db.Uuid

  /// Whether platform-level indexing is enabled for this list (controls
  /// discovery pipeline).
  indexing_enabled Boolean

  /// Whether to allow external search engines to index the public list
  /// content. Only applicable if the list is public.
  allow_search_engine Boolean

  /// Whether the list may be surfaced in internal discovery (search/explore).
  allow_discovery Boolean

  /// Optional administrative scope tag for indexing (e.g., "global",
