  // RELATIONS
  //----
  todoAppList todo_app_lists @relation(fields: [todo_app_list_id], references: [id], onDelete: Cascade)

  @@unique([todo_app_list_id])
  // spellchecker: ignore-next-line
  @@index([indexing_enabled, allow_discovery], map: "todo_app_public_index_preferences_indexing_enabled_all_cc43f5b0")
}

