import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";

/**
 * Validate guest join flow (temporary guest identity issuance).
 *
 * This test calls the public guest-join endpoint via the generated SDK function
 * `api.functional.auth.guest.join(connection)`. Note: the original scenario
 * mentioned an optional request body field (anonymousLabel). The provided SDK
 * function does not accept a request body, so this test exercises the actual
 * available API surface and validates the returned authorization payload
 * (IAuthorized).
 *
 * Steps:
 *
 * 1. Call guest join endpoint (no request body supported by SDK)
 * 2. Typia.assert the returned IAuthorized payload (full schema validation)
 * 3. Business assertions using TestValidator for non-empty tokens and basic
 *    consistency checks
 * 4. Persist accessToken, refreshToken, and guestId into local constants for
 *    potential downstream usage
 */
export async function test_api_guest_join_create_temporary_guest(
  connection: api.IConnection,
) {
  // 1) Call the guest join endpoint (public, no request body in SDK)
  const output: ITodoAppGuest.IAuthorized =
    await api.functional.auth.guest.join(connection);

  // 2) Full type validation (validates uuid and date-time formats too)
  typia.assert(output);

  // 3) Business assertions: tokens are present and non-empty strings
  TestValidator.predicate(
    "access token should be a non-empty string",
    typeof output.token.access === "string" && output.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be a non-empty string",
    typeof output.token.refresh === "string" && output.token.refresh.length > 0,
  );

  // 4) Token timestamps presence (typia.assert guarantees types; these are business-level presence checks)
  TestValidator.predicate(
    "token.expired_at present",
    typeof output.token.expired_at === "string" &&
      output.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "token.refreshable_until present",
    typeof output.token.refreshable_until === "string" &&
      output.token.refreshable_until.length > 0,
  );

  // 5) Guest metadata consistency
  if (output.guest !== undefined && output.guest !== null) {
    // Nested guest must also match its DTO
    typia.assert(output.guest);
    TestValidator.equals(
      "top-level id matches nested guest.id",
      output.id,
      output.guest.id,
    );
  }

  // 6) Persist returned tokens and id for dependent scenarios
  const accessToken: string = output.token.access;
  const refreshToken: string = output.token.refresh;
  const guestId: string = output.id;

  // 7) Simple non-empty sanity checks (business assertions)
  TestValidator.predicate("accessToken non-empty", accessToken.length > 0);
  TestValidator.predicate("refreshToken non-empty", refreshToken.length > 0);
  TestValidator.predicate("guestId non-empty", guestId.length > 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";

/**
 * Validate guest refresh workflow (happy path).
 *
 * This E2E test performs the complete guest refresh sequence:
 *
 * 1. Obtain an initial guest authorization via POST /auth/guest/join
 * 2. Use the returned refresh token to call POST /auth/guest/refresh
 * 3. Assert that refreshed authorization payload is well-formed and that business
 *    expectations hold (access token present, refresh token present, guest id
 *    consistent, and detection of refresh-token rotation when applicable).
 *
 * Business rationale: Guests use short-lived credentials; refresh semantics
 * ensure session continuity. This test validates the server-side refresh
 * behavior without touching low-level header management (the SDK handles
 * Authorization header updates automatically).
 */
export async function test_api_guest_refresh_existing_session(
  connection: api.IConnection,
) {
  // 1) Create a fresh guest identity and obtain initial tokens
  const joined: ITodoAppGuest.IAuthorized =
    await api.functional.auth.guest.join(connection);
  typia.assert(joined);

  // Basic sanity checks on returned token fields
  TestValidator.predicate(
    "joined: access token present",
    typeof joined.token.access === "string" && joined.token.access.length > 0,
  );
  TestValidator.predicate(
    "joined: refresh token present",
    typeof joined.token.refresh === "string" && joined.token.refresh.length > 0,
  );

  // 2) Prepare refresh request body (use satisfies pattern)
  const refreshBody = {
    refresh_token: joined.token.refresh,
  } satisfies ITodoAppGuest.IRefresh;

  // 3) Call refresh endpoint to renew authorization
  const refreshed: ITodoAppGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshed);

  // 4) Business-level assertions about the refreshed payload
  TestValidator.predicate(
    "refreshed: access token present",
    typeof refreshed.token.access === "string" &&
      refreshed.token.access.length > 0,
  );
  TestValidator.predicate(
    "refreshed: refresh token present",
    typeof refreshed.token.refresh === "string" &&
      refreshed.token.refresh.length > 0,
  );

  // Guest identity should remain consistent between initial and refreshed payloads
  TestValidator.equals(
    "guest id unchanged after refresh",
    refreshed.id,
    joined.id,
  );

  // If the server rotates refresh tokens, they must differ. Otherwise, it's
  // acceptable for the implementation to reuse the same refresh token.
  if (refreshed.token.refresh !== joined.token.refresh) {
    TestValidator.notEquals(
      "refresh token rotated",
      refreshed.token.refresh,
      joined.token.refresh,
    );
  } else {
    TestValidator.equals(
      "refresh token unchanged (rotation not applied)",
      refreshed.token.refresh,
      joined.token.refresh,
    );
  }

  // Note: Optionally we could call a public-read endpoint to verify the new
  // access token's usability, but no additional public endpoints were provided
  // in the available SDK materials. The token values themselves are validated
  // and typia.assert ensures structural correctness.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_todo_user_revoke_refresh_tokens(
  connection: api.IConnection,
) {
  // 1. Create a new todoUser via POST /auth/todoUser/join
  const email = typia.random<string & tags.Format<"email">>();
  const createBody = {
    email,
    password: "Password123!",
    displayName: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUser.ICreate;

  const authorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, { body: createBody });
  typia.assert(authorized);

  // Capture tokens for later verification
  const accessToken: string = authorized.token.access;
  const refreshToken: string = authorized.token.refresh;
  TestValidator.predicate("join returned access token", !!accessToken);
  TestValidator.predicate("join returned refresh token", !!refreshToken);

  // 2. Call revoke to revoke previously issued refresh tokens
  const summary: ITodoAppTodoUser.ISummary =
    await api.functional.auth.todoUser.revoke.revokeRefreshTokens(connection);
  typia.assert(summary);

  // Business-level validation: the revoke response should refer to the same user
  TestValidator.equals(
    "revoked user id matches joined user",
    summary.id,
    authorized.id,
  );

  // 3. Verify revocation by attempting to refresh using the old refresh token
  // Expect failure (business logic: refresh token revoked). We do not assert
  // specific HTTP status codes; just that the operation throws/rejects.
  await TestValidator.error(
    "refresh with revoked token should be rejected",
    async () => {
      await api.functional.auth.todoUser.refresh(connection, {
        body: {
          refresh_token: refreshToken,
        } satisfies ITodoAppTodoUser.IRefresh,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";

export async function test_api_admin_join_registration(
  connection: api.IConnection,
) {
  // 1) Prepare valid admin creation payload
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(12);
  const displayName: string = RandomGenerator.name();
  const href: string = typia.random<string & tags.Format<"uri">>();
  const referrer: string = typia.random<string & tags.Format<"uri">>();

  const createBody = {
    email: adminEmail,
    password,
    display_name: displayName,
    role: "support",
    href,
    referrer,
  } satisfies ITodoAppAdmin.ICreate;

  // 2) Call the join endpoint (happy path)
  const authorized: ITodoAppAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: createBody,
    });

  // 3) Type-level and runtime validations
  typia.assert(authorized);

  // Business assertions
  TestValidator.equals(
    "returned email matches input",
    authorized.email,
    adminEmail,
  );
  TestValidator.equals(
    "returned display_name matches input",
    authorized.display_name,
    displayName,
  );
  TestValidator.predicate(
    "token.access is present",
    typeof authorized.token.access === "string" &&
      authorized.token.access.length > 0,
  );
  TestValidator.predicate(
    "token.refresh is present",
    typeof authorized.token.refresh === "string" &&
      authorized.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "is_active is boolean",
    typeof authorized.is_active === "boolean",
  );

  // 4) Duplicate email must fail (uniqueness constraint)
  await TestValidator.error(
    "duplicate admin registration with same email should fail",
    async () => {
      await api.functional.auth.admin.join(connection, {
        body: createBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppListShare } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppListShare";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppListShare } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppListShare";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

/**
 * Validate that a list owner can retrieve paginated share records for their
 * list and that filtering (isPublic, expiresBefore/After) and access controls
 * work as expected.
 *
 * Steps:
 *
 * 1. Register owner (todoUser) via POST /auth/todoUser/join
 * 2. Create a todo list as the owner via POST /todoApp/todoUser/lists
 * 3. Create a share for the created list via POST
 *    /todoApp/todoUser/lists/{listId}/shares
 * 4. Call PATCH /todoApp/todoUser/lists/{listId}/shares as the owner and validate
 *    pagination container and contents
 * 5. Validate filtering by isPublic and expiry windows
 * 6. Negative checks: unauthenticated and non-owner requests must fail
 */
export async function test_api_list_shares_index_by_owner(
  connection: api.IConnection,
) {
  // 1) Owner signup
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const owner: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: {
        email: ownerEmail,
        password: "Password123",
        displayName: RandomGenerator.name(),
        ip: null,
        href: "https://example.com/signup",
        referrer: "https://referrer.example.com/",
      } satisfies ITodoAppTodoUser.ICreate,
    });
  typia.assert(owner);

  // 2) Create a todo list as owner
  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        visibility: "private",
      } satisfies ITodoAppList.ICreate,
    },
  );
  typia.assert(list);

  // 3) Create a share for that list
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(); // 24 hours from now
  const publicUrl = `https://public.example.com/share/${RandomGenerator.alphaNumeric(8)}`;
  const createdShare: ITodoAppListShare =
    await api.functional.todoApp.todoUser.lists.shares.create(connection, {
      listId: list.id,
      body: {
        publicUrl, // optional, server may normalize
        isPublic: true,
        visibility: "public",
        expiresAt,
      } satisfies ITodoAppListShare.ICreate,
    });
  typia.assert(createdShare);

  // 4) Index shares as owner (no filters) - expect the created share to appear
  const page: IPageITodoAppListShare.ISummary =
    await api.functional.todoApp.todoUser.lists.shares.index(connection, {
      listId: list.id,
      body: {} satisfies ITodoAppListShare.IRequest,
    });
  typia.assert(page);

  // The page should contain our created share summary
  const found = page.data.find((s) => s.id === createdShare.id);
  typia.assert(found!);

  TestValidator.equals(
    "share.list.id should match created list",
    found!.list.id,
    list.id,
  );
  TestValidator.equals(
    "share.list.owner.id should equal owner id",
    found!.list.owner.id,
    owner.id,
  );
  TestValidator.equals("share.isPublic should be true", found!.isPublic, true);
  TestValidator.equals(
    "share.publicUrl should match provided value",
    found!.publicUrl,
    publicUrl,
  );
  TestValidator.equals(
    "share.expiresAt should match provided value",
    found!.expiresAt,
    expiresAt,
  );

  // 5) Filtering checks
  // 5.1 isPublic = true should return the share
  const pagePublic: IPageITodoAppListShare.ISummary =
    await api.functional.todoApp.todoUser.lists.shares.index(connection, {
      listId: list.id,
      body: {
        isPublic: true,
      } satisfies ITodoAppListShare.IRequest,
    });
  typia.assert(pagePublic);
  TestValidator.predicate(
    "filter isPublic=true returns at least one item",
    pagePublic.data.some((s) => s.id === createdShare.id),
  );

  // 5.2 isPublic = false should NOT return the created public share
  const pageNotPublic: IPageITodoAppListShare.ISummary =
    await api.functional.todoApp.todoUser.lists.shares.index(connection, {
      listId: list.id,
      body: {
        isPublic: false,
      } satisfies ITodoAppListShare.IRequest,
    });
  typia.assert(pageNotPublic);
  TestValidator.predicate(
    "filter isPublic=false excludes the public share",
    !pageNotPublic.data.some((s) => s.id === createdShare.id),
  );

  // 5.3 expiresAfter: a time before now should include the share (since expiresAt is in future)
  const pageExpiresAfter: IPageITodoAppListShare.ISummary =
    await api.functional.todoApp.todoUser.lists.shares.index(connection, {
      listId: list.id,
      body: {
        expiresAfter: new Date(Date.now() - 1000).toISOString(),
      } satisfies ITodoAppListShare.IRequest,
    });
  typia.assert(pageExpiresAfter);
  TestValidator.predicate(
    "filter expiresAfter in past includes share",
    pageExpiresAfter.data.some((s) => s.id === createdShare.id),
  );

  // 5.4 expiresBefore: a time before now should exclude the future-expiring share
  const pageExpiresBefore: IPageITodoAppListShare.ISummary =
    await api.functional.todoApp.todoUser.lists.shares.index(connection, {
      listId: list.id,
      body: {
        expiresBefore: new Date(Date.now() - 1000).toISOString(),
      } satisfies ITodoAppListShare.IRequest,
    });
  typia.assert(pageExpiresBefore);
  TestValidator.predicate(
    "filter expiresBefore in past excludes future-expiring share",
    !pageExpiresBefore.data.some((s) => s.id === createdShare.id),
  );

  // 6) Negative checks
  // 6.1 Unauthenticated request should fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated user cannot index shares",
    async () => {
      await api.functional.todoApp.todoUser.lists.shares.index(unauthConn, {
        listId: list.id,
        body: {} satisfies ITodoAppListShare.IRequest,
      });
    },
  );

  // 6.2 Non-owner should receive an error (403 or 401 depending on implementation)
  const otherConn: api.IConnection = { ...connection, headers: {} };
  const otherEmail = typia.random<string & tags.Format<"email">>();
