import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_task_creation_by_todouser(
  connection: api.IConnection,
) {
  // 1) Sign up a new todoUser (self-join) and obtain authorization token
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const joinBody = {
    email: userEmail,
    password: "Password123", // >= 8 chars
    href: "https://example.com/signup",
    referrer: "https://example.com/",
    displayName: RandomGenerator.name(),
  } satisfies ITodoAppTodoUser.ICreate;

  const auth: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: joinBody,
    });
  typia.assert(auth);

  // 2) Create a new todo list owned by the joined user
  const listCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    visibility: "private",
  } satisfies ITodoAppList.ICreate;

  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    connection,
    {
      body: listCreateBody,
    },
  );
  typia.assert(list);

  // Helper for task creation
  const createTask = async (props: ITodoAppTask.ICreate) => {
    return await api.functional.todoApp.todoUser.lists.tasks.create(
      connection,
      {
        listId: list.id,
        body: props,
      },
    );
  };

  // 3) Create the primary task (happy path)
  const taskRequest = {
    title: "Buy groceries",
    description: "Milk, eggs",
    dueDate: "2025-11-15T12:00:00Z",
  } satisfies ITodoAppTask.ICreate;

  const task: ITodoAppTask = await createTask(taskRequest);
  typia.assert(task);

  // 4) Validate persisted fields and business rules
  TestValidator.equals("task title matches", task.title, taskRequest.title);
  TestValidator.equals(
    "task description matches",
    task.description,
    taskRequest.description,
  );
  TestValidator.equals(
    "task dueDate matches",
    task.dueDate,
    taskRequest.dueDate,
  );
  TestValidator.equals("task is linked to its list", task.list.id, list.id);

  // Business rule: isCompleted defaults to false
  TestValidator.equals(
    "isCompleted defaults to false",
    task.isCompleted,
    false,
  );

  // When not completed, completedAt should be null or undefined
  TestValidator.predicate(
    "completedAt is null or undefined when not completed",
    task.completedAt === null || task.completedAt === undefined,
  );

  // 5) Create a task with isCompleted=true and assert completedAt is set
  const completedTaskRequest = {
    title: "Already done",
    isCompleted: true,
  } satisfies ITodoAppTask.ICreate;

  const completedTask: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: list.id,
      body: completedTaskRequest,
    });
  typia.assert(completedTask);
  TestValidator.equals(
    "completed task isCompleted is true",
    completedTask.isCompleted,
    true,
  );
  TestValidator.predicate(
    "completedAt is present when isCompleted true",
    completedTask.completedAt !== null &&
      completedTask.completedAt !== undefined,
  );

  // 6) Negative cases
  // 6.a Unauthenticated request should fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated cannot create task", async () => {
    await api.functional.todoApp.todoUser.lists.tasks.create(unauthConn, {
      listId: list.id,
      body: taskRequest,
    });
  });

  // 6.b Malformed listId should produce a validation/error response
  await TestValidator.error("malformed listId returns error", async () => {
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: "invalid-uuid",
      body: taskRequest,
    });
  });

  // 6.c Another authenticated user should NOT be able to create task on this list
  const otherConn: api.IConnection = { ...connection, headers: {} };
  const otherJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123",
    href: "https://example.com/signup",
    referrer: "https://example.com/",
    displayName: RandomGenerator.name(),
  } satisfies ITodoAppTodoUser.ICreate;

  const otherAuth: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(otherConn, { body: otherJoinBody });
  typia.assert(otherAuth);

  await TestValidator.error(
    "other user cannot create task on someone else's list",
    async () => {
      await api.functional.todoApp.todoUser.lists.tasks.create(otherConn, {
        listId: list.id,
        body: {
          title: "Not allowed",
          description: "Attempt to write to another's list",
        } satisfies ITodoAppTask.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";

export async function test_api_admin_account_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1) Prepare two isolated connection clones so SDK's join will set tokens on
  //    their respective connection objects without manual header manipulation.
  const deleterConn: api.IConnection = { ...connection, headers: {} };
  const targetConn: api.IConnection = { ...connection, headers: {} };

  // 2) Create the deleter admin account (will set deleterConn.headers via SDK)
  const deleterEmail = `deleter+${RandomGenerator.alphaNumeric(6)}@example.com`;
  const deleterBody = {
    email: deleterEmail,
    password: "P@ssword123",
    display_name: RandomGenerator.name(),
    href: "http://localhost/test",
    referrer: "http://localhost/ref",
  } satisfies ITodoAppAdmin.ICreate;

  const deleter: ITodoAppAdmin.IAuthorized =
    await api.functional.auth.admin.join(deleterConn, {
      body: deleterBody,
    });
  typia.assert(deleter);
  TestValidator.predicate("deleter is active", deleter.is_active === true);

  // 3) Create the target admin account (targetConn will receive its token)
  const targetEmail = `target+${RandomGenerator.alphaNumeric(6)}@example.com`;
  const targetBody = {
    email: targetEmail,
    password: "P@ssword123",
    display_name: RandomGenerator.name(),
    href: "http://localhost/test",
    referrer: "http://localhost/ref",
  } satisfies ITodoAppAdmin.ICreate;

  const target: ITodoAppAdmin.IAuthorized =
    await api.functional.auth.admin.join(targetConn, {
      body: targetBody,
    });
  typia.assert(target);
  TestValidator.predicate(
    "target is active before deletion",
    target.is_active === true,
  );

  // 4) Perform soft-delete using the deleter's connection (deleterConn carries
  //    the deleter's access token because join set it on deleterConn).
  await api.functional.todoApp.admin.admins.erase(deleterConn, {
    adminId: target.id,
  });

  // 5) Attempt to delete again - expect an HTTP error (404 Not Found or 410 Gone
  //    depending on implementation). Use TestValidator.httpError to validate.
  await TestValidator.httpError(
    "deleting an already-deleted admin should fail",
    [404, 410],
    async () => {
      await api.functional.todoApp.admin.admins.erase(deleterConn, {
        adminId: target.id,
      });
    },
  );

  // 6) Final sanity checks: ensure ids are present and are UUIDs
  // typia.assert on previously-asserted objects already validated structure
  TestValidator.predicate(
    "deleter id is present",
    typeof deleter.id === "string" && deleter.id.length > 0,
  );
  TestValidator.predicate(
    "target id is present",
    typeof target.id === "string" && target.id.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminSession";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";

/**
 * Validate admin session search and filtering for a specific administrator.
 *
 * Workflow:
 *
 * 1. Create a fresh admin via POST /auth/admin/join (creates authorization token
 *    and an initial session record in typical implementations).
 * 2. Use the authorized connection (SDK automatically sets Authorization header on
 *    join) to call PATCH /todoApp/admin/admins/{adminId}/sessions with various
 *    filters and pagination parameters.
 * 3. Assert type-safety (typia.assert) and business rules (ownership, filtering
 *    behavior) using TestValidator.
 * 4. Verify unauthorized callers cannot access the session listing.
 */
export async function test_api_admin_sessions_search_by_admin(
  connection: api.IConnection,
) {
  // 1) Create a fresh admin (join) - this establishes an authenticated actor
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const createBody = {
    email: adminEmail,
    password: "P@ssw0rd123",
    display_name: RandomGenerator.name(),
    role: "support",
    href: "https://example.com/signup",
    referrer: "https://referrer.example.com/",
  } satisfies ITodoAppAdmin.ICreate;

  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    {
      body: createBody,
    },
  );
  typia.assert(admin);

  // 2) Retrieve sessions for the created admin with default pagination (status=all)
  const allSessions: IPageITodoAppAdminSession.ISummary =
    await api.functional.todoApp.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        status: "all",
        page: 1,
        pageSize: 25,
      } satisfies ITodoAppAdminSession.IRequest,
    });
  typia.assert(allSessions);

  // Basic structural and ownership checks
  TestValidator.predicate(
    "response contains pagination object",
    typeof allSessions.pagination === "object" &&
      allSessions.pagination !== null,
  );
  TestValidator.predicate("data is an array", Array.isArray(allSessions.data));
  TestValidator.predicate(
    "all returned sessions belong to the created admin",
    allSessions.data.every((s) => s.admin.id === admin.id),
  );

  // 3) Status filter: active only
  const activeSessions: IPageITodoAppAdminSession.ISummary =
    await api.functional.todoApp.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        status: "active",
        page: 1,
        pageSize: 25,
      } satisfies ITodoAppAdminSession.IRequest,
    });
  typia.assert(activeSessions);

  // Business rule: active sessions must not be expired. Accept null/undefined
  // expiredAt as active, or a future timestamp as active.
  TestValidator.predicate(
    "active filter returns only non-expired sessions",
    activeSessions.data.every((s) => {
      if (s.expiredAt === null || s.expiredAt === undefined) return true;
      const expired = new Date(s.expiredAt).getTime();
      return expired > Date.now();
    }),
  );

  // 4) createdAtFrom filter using a future timestamp -> expect zero results
  const futureISO = new Date(Date.now() + 1000 * 60 * 60).toISOString();
  const futureFiltered: IPageITodoAppAdminSession.ISummary =
    await api.functional.todoApp.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        createdAtFrom: futureISO,
        page: 1,
        pageSize: 25,
      } satisfies ITodoAppAdminSession.IRequest,
    });
  typia.assert(futureFiltered);
  TestValidator.equals(
    "future createdAtFrom yields no sessions",
    futureFiltered.data.length,
    0,
  );

  // 5) Unauthorized caller should not be able to retrieve sessions
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthorized callers cannot access admin sessions",
    async () => {
      await api.functional.todoApp.admin.admins.sessions.index(unauthConn, {
        adminId: admin.id,
        body: {
          status: "all",
          page: 1,
          pageSize: 25,
        } satisfies ITodoAppAdminSession.IRequest,
      });
    },
  );
}

