import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTaskCompletionByDay } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTaskCompletionByDay";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskCompletionByDay } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletionByDay";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_admin_statistics_task_completion_by_day(
  connection: api.IConnection,
) {
  /**
   * Test overview:
   *
   * 1. Create a todoUser account (connUser) and a todo list owned by that user
   * 2. Create multiple tasks under the list; create some with isCompleted: true so
   *    the server will set completedAt (now)
   * 3. Create an admin account (connAdmin)
   * 4. As admin, call the statistics endpoint and assert today's aggregated
   *    completedCount equals the number of tasks created as completed above
   * 5. Validate access control: unauthenticated and non-admin callers are rejected
   */

  // --- 1) Prepare isolated connection objects for each actor ---
  const connUser: api.IConnection = { ...connection, headers: {} };
  const connAdmin: api.IConnection = { ...connection, headers: {} };
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // 1.1 Create todoUser account and obtain token (connUser will be updated by SDK)
  const todoUser = await api.functional.auth.todoUser.join(connUser, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "password123",
      displayName: RandomGenerator.name(),
      href: "http://example.com/signup",
      referrer: "http://example.com",
    } satisfies ITodoAppTodoUser.ICreate,
  });
  typia.assert(todoUser);

  // 2) Create a todo list owned by the todoUser
  const list = await api.functional.todoApp.todoUser.lists.create(connUser, {
    body: {
      title: RandomGenerator.name(2),
      description: RandomGenerator.paragraph({ sentences: 3 }),
      visibility: "private",
    } satisfies ITodoAppList.ICreate,
  });
  typia.assert(list);

  // 3) Create multiple tasks with varied completion state
  const createdTasks: ITodoAppTask[] = [];

  const taskBodies = [
    {
      title: "Task - completed on create",
      description: "completed",
      isCompleted: true,
    },
    {
      title: "Task - not completed",
      description: "pending",
      isCompleted: false,
    },
    {
      title: "Task - completed on create 2",
      description: "completed2",
      isCompleted: true,
    },
  ] as const;

  for (const body of taskBodies) {
    const created = await api.functional.todoApp.todoUser.lists.tasks.create(
      connUser,
      {
        listId: list.id,
        body: {
          title: body.title,
          description: body.description,
          isCompleted: body.isCompleted,
        } satisfies ITodoAppTask.ICreate,
      },
    );
    typia.assert(created);
    createdTasks.push(created);
  }

  // Count how many tasks were created as completed (server will set completedAt)
  const expectedCompletedCount = createdTasks.filter(
    (t) => t.isCompleted === true,
  ).length;

  // 4) Create admin actor (connAdmin)
  const admin = await api.functional.auth.admin.join(connAdmin, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "admin-password-1",
      display_name: RandomGenerator.name(),
      role: "superadmin",
      href: "http://example.com/admin/signup",
      referrer: "http://example.com",
    } satisfies ITodoAppAdmin.ICreate,
  });
  typia.assert(admin);

  // 5) As admin, call statistics endpoint
  const page: IPageITodoAppTaskCompletionByDay.ISummary =
    await api.functional.todoApp.admin.statistics.task_completion_by_day.taskCompletionByDay(
      connAdmin,
    );
  typia.assert(page);

  // 5.1 Validate that today's bucket exists and completedCount matches
  const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD (UTC)
  const todays = page.data.find((d) => d.date === today);

  TestValidator.predicate(
    "statistics contains today bucket",
    todays !== undefined,
  );

  if (todays !== undefined) {
    TestValidator.equals(
      "completedCount matches created completed tasks",
      todays.completedCount,
      expectedCompletedCount,
    );
  }

  // 6) Access control checks
  // 6.1 Unauthenticated should be rejected
  await TestValidator.httpError(
    "unauthenticated caller should be rejected",
    [401, 403],
    async () =>
      await api.functional.todoApp.admin.statistics.task_completion_by_day.taskCompletionByDay(
        unauthConn,
      ),
  );

  // 6.2 Non-admin authenticated (todoUser) should be rejected
  await TestValidator.httpError(
    "non-admin caller should be rejected",
    [401, 403],
    async () =>
      await api.functional.todoApp.admin.statistics.task_completion_by_day.taskCompletionByDay(
        connUser,
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSearchResult";
import type { ITodoAppGlobalSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGlobalSearch";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSearchResult";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_search_global_returns_relevant_results(
  connection: api.IConnection,
) {
  // 1) Create a new todoUser account and obtain its token via join
  const userEmail = typia.random<string & tags.Format<"email">>();
  const joinBody = {
    email: userEmail,
    password: "P@ssw0rd!",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    displayName: RandomGenerator.name(),
    ip: undefined,
  } satisfies ITodoAppTodoUser.ICreate;

  const authorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, { body: joinBody });
  typia.assert(authorized);

  // At this point, SDK attaches Authorization header to connection automatically

  // 2) Create canonical tags: "groceries" and "workflows"
  const groceriesTag: ITodoAppTaskTag =
    await api.functional.todoApp.todoUser.taskTags.create(connection, {
      body: { name: "groceries" } satisfies ITodoAppTaskTag.ICreate,
    });
  typia.assert(groceriesTag);

  const workflowsTag: ITodoAppTaskTag =
    await api.functional.todoApp.todoUser.taskTags.create(connection, {
      body: { name: "workflows" } satisfies ITodoAppTaskTag.ICreate,
    });
  typia.assert(workflowsTag);

  // 3) Create two lists: public and private
  const publicList: ITodoAppList =
    await api.functional.todoApp.todoUser.lists.create(connection, {
      body: {
        title: `Public - ${RandomGenerator.paragraph({ sentences: 3 })}`,
        description: RandomGenerator.paragraph({ sentences: 6 }),
        visibility: "public",
      } satisfies ITodoAppList.ICreate,
    });
  typia.assert(publicList);

  const privateList: ITodoAppList =
    await api.functional.todoApp.todoUser.lists.create(connection, {
      body: {
        title: `Private - ${RandomGenerator.paragraph({ sentences: 3 })}`,
        description: RandomGenerator.paragraph({ sentences: 4 }),
        visibility: "private",
      } satisfies ITodoAppList.ICreate,
    });
  typia.assert(privateList);

  // 4) Create several tasks under each list with tags and varied fields
  const createdTaskIds: string[] = [];

  // Tasks for public list
  const publicTask1: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: publicList.id,
      body: {
        title: "Buy groceries",
        description: "Milk, eggs, bread",
        isCompleted: false,
        dueDate: new Date(Date.now() + 24 * 3600 * 1000).toISOString(),
        tagNames: ["groceries"],
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(publicTask1);
  createdTaskIds.push(publicTask1.id);

  const publicTask2: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: publicList.id,
      body: {
        title: "Project workflows review",
        description: RandomGenerator.content({ paragraphs: 1 }),
        isCompleted: true,
        dueDate: new Date(Date.now() - 2 * 24 * 3600 * 1000).toISOString(),
        tagNames: ["workflows"],
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(publicTask2);
  createdTaskIds.push(publicTask2.id);

  // Tasks for private list
  const privateTask1: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: privateList.id,
      body: {
        title: "Grocery budget planning",
        description: "Plan weekly groceries",
        isCompleted: false,
        dueDate: new Date(Date.now() + 3 * 24 * 3600 * 1000).toISOString(),
        tagNames: ["groceries", "workflows"],
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(privateTask1);
  createdTaskIds.push(privateTask1.id);

  // 5) Call global search with query 'groceries' and validate results
  const searchRequest = {
    query: "groceries",
    page: 1,
    pageSize: 10,
    entityFilters: ["task", "list", "tag", "user"],
    includeSnippets: true,
    restrictToAccessible: true,
    sortBy: "relevance",
    order: "desc",
  } satisfies ITodoAppGlobalSearch.IRequest;

  const searchResult: IPageITodoAppSearchResult.ISummary =
    await api.functional.todoApp.todoUser.search.global.index(connection, {
      body: searchRequest,
    });
  typia.assert(searchResult);

  // Basic pagination shape checks
  TestValidator.predicate(
    "pagination.current is number",
    typeof searchResult.pagination.current === "number",
  );
  TestValidator.predicate(
    "pagination.limit is number",
    typeof searchResult.pagination.limit === "number",
  );
  TestValidator.predicate(
    "pagination.records is number",
    typeof searchResult.pagination.records === "number",
  );
  TestValidator.predicate(
    "pagination.pages is number",
    typeof searchResult.pagination.pages === "number",
  );

  // Ensure returned items have discriminator and essential fields
  TestValidator.predicate(
    "every result has targetType and targetId",
    searchResult.data.every(
      (d) => typeof d.targetType === "string" && typeof d.targetId === "string",
    ),
  );

  // Ensure at least one returned result corresponds to created resources (tasks/lists/tags)
  const returnedIds = searchResult.data.map((d) => d.targetId);
  const intersectsCreated = returnedIds.some(
    (id) =>
      createdTaskIds.includes(id) ||
      id === groceriesTag.id ||
      id === publicList.id ||
      id === privateList.id,
  );
  TestValidator.predicate(
    "search hits include created resources",
    intersectsCreated,
  );

  // 6) Pagination & sorting stability: request a small page size and ensure consistent pagination structure
  const pagedRequest = {
    ...searchRequest,
    page: 1,
    pageSize: 2,
    sortBy: "createdAt",
    order: "desc",
  } satisfies ITodoAppGlobalSearch.IRequest;
  const paged: IPageITodoAppSearchResult.ISummary =
    await api.functional.todoApp.todoUser.search.global.index(connection, {
      body: pagedRequest,
    });
  typia.assert(paged);
  TestValidator.predicate("paged returns array", Array.isArray(paged.data));
  TestValidator.predicate(
    "paged limit equals requested pageSize",
    paged.pagination.limit === 2,
  );

  // 7) Error cases
  // 7a) Unauthenticated caller should be rejected
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated search should fail", async () => {
    await api.functional.todoApp.todoUser.search.global.index(unauthConn, {
      body: {
        query: "groceries",
        page: 1,
        pageSize: 10,
      } satisfies ITodoAppGlobalSearch.IRequest,
    });
  });

  // 7b) Malformed pagination (page = 0) should be rejected with 400
  await TestValidator.error("invalid pagination page should fail", async () => {
    await api.functional.todoApp.todoUser.search.global.index(connection, {
      body: { page: 0, pageSize: 10 } satisfies ITodoAppGlobalSearch.IRequest,
    });
  });

  // All done
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppCollaborationPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppCollaborationPermission";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppCollaborationPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCollaborationPermission";

/**
 * Validate admin search and pagination for collaboration permission
 * definitions.
 *
 * Business context:
 *
 * - Administrative users may create permission codes (e.g. 'list.read',
 *   'list.write') that control collaborator capabilities. Admin UIs rely on a
 *   paginated listing endpoint to search/filter/sort permission definitions.
 *
 * Test steps:
 *
 * 1. Register a new admin via POST /auth/admin/join and validate returned
 *    authorization payload.
 * 2. Create two collaboration permission records for 'list.read' and 'list.write'
 *    with isGrantable=true.
 * 3. Search with a partial code filter ('list.') + isGrantable=true + pagination
 *    and verify the created records appear and pagination metadata exists.
 * 4. Search with exact code 'list.read' and verify single-result behavior.
 * 5. Ensure server enforces maximum pageSize by requesting pageSize=500 and
 *    asserting a validation error is returned.
 */
export async function test_api_collaboration_permission_index_admin(
  connection: api.IConnection,
) {
  // 1. Admin signup (creates an authorized admin and SDK attaches token)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    {
      body: {
        email: adminEmail,
        password: "strong-password-2025", // >=8 chars
        display_name: RandomGenerator.name(),
        role: "superadmin",
        ip: null,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies ITodoAppAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 2. Create initial collaboration permissions: 'list.read' and 'list.write'
  const createdRead: ITodoAppCollaborationPermission =
    await api.functional.todoApp.admin.collaborationPermissions.create(
      connection,
      {
        body: {
          code: "list.read",
          description: "Allow reading lists",
          isGrantable: true,
        } satisfies ITodoAppCollaborationPermission.ICreate,
      },
    );
  typia.assert(createdRead);

  const createdWrite: ITodoAppCollaborationPermission =
    await api.functional.todoApp.admin.collaborationPermissions.create(
      connection,
      {
        body: {
          code: "list.write",
          description: "Allow modifying lists",
          isGrantable: true,
        } satisfies ITodoAppCollaborationPermission.ICreate,
      },
    );
  typia.assert(createdWrite);

  // 3. Search (partial code filter) with pagination and sorting
  const pageResult: IPageITodoAppCollaborationPermission.ISummary =
    await api.functional.todoApp.admin.collaborationPermissions.index(
      connection,
      {
        body: {
          page: 1,
          pageSize: 10,
          code: "list.", // partial match
          isGrantable: true,
          sortBy: "code",
          order: "asc",
        } satisfies ITodoAppCollaborationPermission.IRequest,
      },
    );
  typia.assert(pageResult);

  // Validate pagination metadata existence and sanity
  TestValidator.predicate(
    "pagination present and current page >= 1",
    pageResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    pageResult.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    pageResult.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    pageResult.pagination.pages >= 0,
  );

  // Validate that created items are present in the result set by code
  TestValidator.predicate(
    "result contains list.read",
    pageResult.data.some((d) => d.code === "list.read"),
  );
  TestValidator.predicate(
    "result contains list.write",
    pageResult.data.some((d) => d.code === "list.write"),
  );

  // For each returned item, typia.assert the shape (ensures id, timestamps, etc.)
  pageResult.data.forEach((item) => typia.assert(item));

  // 4. Perform exact-filter search for 'list.read'
  const exactPage: IPageITodoAppCollaborationPermission.ISummary =
    await api.functional.todoApp.admin.collaborationPermissions.index(
      connection,
      {
        body: {
          page: 1,
          pageSize: 10,
          code: "list.read",
          isGrantable: true,
          sortBy: "code",
          order: "asc",
        } satisfies ITodoAppCollaborationPermission.IRequest,
      },
    );
  typia.assert(exactPage);

  // Expect a single item for the exact code
  TestValidator.equals(
    "exact filter returns single item",
    exactPage.data.length,
    1,
  );
  TestValidator.equals(
    "exact item code matches expected",
    exactPage.data[0].code,
    "list.read",
  );
  TestValidator.equals(
    "exact item id matches created read id",
    exactPage.data[0].id,
    createdRead.id,
  );

  // 5. Excessive pageSize should produce validation error (pageSize > 200)
  await TestValidator.error(
    "excessive pageSize should fail validation",
    async () => {
      await api.functional.todoApp.admin.collaborationPermissions.index(
        connection,
        {
          body: {
            page: 1,
            pageSize: 500, // exceed documented maximum 200
          } satisfies ITodoAppCollaborationPermission.IRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppCollaborationPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCollaborationPermission";

export async function test_api_collaboration_permission_create_admin(
  connection: api.IConnection,
) {
  /**
   * Test flow:
   *
   * 1. Register a new admin via POST /auth/admin/join
   * 2. Using the authenticated admin context, create a collaboration permission
   *    via POST /todoApp/admin/collaborationPermissions
   * 3. Validate response shape and values
   * 4. Attempt to create the same code again and expect an error (uniqueness)
   */
  // 1) Admin sign-up
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    {
      body: {
        email: adminEmail,
        password: "P@ssw0rd123", // satisfies min length 8
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies ITodoAppAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 2) Create collaboration permission payload
  const createBody = {
    code: "list.manage",
    description: "Manage lists and permissions",
    isGrantable: true,
  } satisfies ITodoAppCollaborationPermission.ICreate;

  // 3) Create permission using authenticated connection (join set Authorization)
  const permission: ITodoAppCollaborationPermission =
    await api.functional.todoApp.admin.collaborationPermissions.create(
      connection,
      {
        body: createBody,
      },
    );
  typia.assert(permission);

  // 4) Business validations
  TestValidator.equals(
    "created permission code matches input",
    permission.code,
    createBody.code,
  );
  TestValidator.equals(
    "created permission description matches input",
    permission.description,
    createBody.description,
  );
  TestValidator.equals(
    "created permission isGrantable matches input",
    permission.isGrantable,
    createBody.isGrantable,
  );

  // ID and timestamps are guaranteed by typia.assert, but assert presence as business checks
  TestValidator.predicate(
    "created permission has id",
    permission.id !== null && permission.id !== undefined,
  );
  TestValidator.predicate(
    "created permission has createdAt",
    permission.createdAt !== null && permission.createdAt !== undefined,
  );
  TestValidator.predicate(
    "created permission has updatedAt",
    permission.updatedAt !== null && permission.updatedAt !== undefined,
  );

  // 5) Uniqueness: creating the same code again must fail (business error)
  await TestValidator.error(
    "duplicate permission code should fail",
    async () => {
      await api.functional.todoApp.admin.collaborationPermissions.create(
        connection,
        {
          body: createBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppListShare } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppListShare";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

/**
 * Validate that a list's public share metadata can be retrieved by
 * unauthenticated callers while keeping sensitive token data hidden. Also
 * verify that expired shares are not accessible publicly.
 *
 * Steps:
 *
 * 1. Register a new todoUser (join) and obtain authentication token (SDK auto-sets
 *    it).
 * 2. Create a new todo list as that user.
 * 3. Create a public share for the list (isPublic=true, expiresAt=null).
 * 4. As an unauthenticated client, GET the share summary and verify public-safe
 *    fields and absence of shareToken.
 * 5. Create another share with an expiry in the past and assert unauthenticated
 *    GET fails.
 */
export async function test_api_list_share_public_retrieval(
  connection: api.IConnection,
) {
  // 1) Register a fresh todoUser and obtain authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const auth = await api.functional.auth.todoUser.join(connection, {
    body: {
      email: userEmail,
      password: "Password123!",
      displayName: RandomGenerator.name(),
      href: "https://example.com/signup",
      referrer: "https://example.com/",
    } satisfies ITodoAppTodoUser.ICreate,
  });
  typia.assert(auth);

  // 2) Create a new todo list as the authenticated user
  const createListBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
    visibility: "public",
  } satisfies ITodoAppList.ICreate;

  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    connection,
    { body: createListBody },
  );
  typia.assert(list);

  // 3) Create a public share for the list (no expiry)
  const publicShareBody = {
    publicUrl: typia.random<string & tags.Format<"uri">>(),
    isPublic: true,
    visibility: "public",
    expiresAt: null,
  } satisfies ITodoAppListShare.ICreate;

  const share: ITodoAppListShare =
    await api.functional.todoApp.todoUser.lists.shares.create(connection, {
      listId: list.id,
      body: publicShareBody,
    });
  typia.assert(share);

  // Prepare an unauthenticated connection (do NOT mutate original connection.headers)
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // 4) As unauthenticated client, retrieve the public-safe share summary
  const summary: ITodoAppListShare.ISummary =
    await api.functional.todoApp.lists.shares.at(unauthConn, {
