import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";

export async function test_api_admin_refresh_success_and_invalid_token(
  connection: api.IConnection,
) {
  /**
   * E2E: Admin refresh happy path and invalid-token negative cases.
   *
   * Steps:
   *
   * 1. Register a fresh admin (POST /auth/admin/join) to obtain initial access +
   *    refresh tokens
   * 2. Call POST /auth/admin/refresh with the captured refresh token and validate
   *    returned IAuthorized
   * 3. Negative cases: malformed token and random well-formed token should produce
   *    errors
   */

  // 1) Register a fresh admin to obtain initial tokens
  const createBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password123",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdmin.ICreate;

  const joined: ITodoAppAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: createBody });
  typia.assert(joined);

  // Capture issued tokens
  const initialAccess = joined.token.access;
  const initialRefresh = joined.token.refresh;

  // Sanity validations
  TestValidator.predicate(
    "join returned access token",
    typeof initialAccess === "string" && initialAccess.length > 0,
  );
  TestValidator.predicate(
    "join returned refresh token",
    typeof initialRefresh === "string" && initialRefresh.length > 0,
  );

  // 2) Happy path: refresh with the captured refresh token
  const refreshed: ITodoAppAdmin.IAuthorized =
    await api.functional.auth.admin.refresh(connection, {
      body: { refresh_token: initialRefresh } satisfies ITodoAppAdmin.IRefresh,
    });
  typia.assert(refreshed);

  // Validate refreshed tokens and identity
  TestValidator.predicate(
    "refresh returned access token",
    typeof refreshed.token.access === "string" &&
      refreshed.token.access.length > 0,
  );

  // Access token rotation is implementation-dependent. If rotation occurred, assert inequality;
  // otherwise ensure access token exists (already asserted above).
  if (refreshed.token.access !== initialAccess) {
    TestValidator.notEquals(
      "access token was rotated",
      refreshed.token.access,
      initialAccess,
    );
  } else {
    TestValidator.predicate(
      "access token present after refresh",
      refreshed.token.access.length > 0,
    );
  }

  // Refresh token rotation check (optional): if rotated, ensure differs from initial; otherwise assert presence
  TestValidator.predicate(
    "refresh token present after refresh",
    typeof refreshed.token.refresh === "string" &&
      refreshed.token.refresh.length > 0,
  );
  if (refreshed.token.refresh !== initialRefresh) {
    TestValidator.notEquals(
      "refresh token was rotated",
      refreshed.token.refresh,
      initialRefresh,
    );
  }

  // Admin identity checks
  TestValidator.predicate("admin is active", refreshed.is_active === true);

  // 3) Negative case A: malformed / tampered refresh token
  await TestValidator.error("malformed refresh token should fail", async () => {
    await api.functional.auth.admin.refresh(connection, {
      body: {
        refresh_token: "not-a-valid-refresh-token",
      } satisfies ITodoAppAdmin.IRefresh,
    });
  });

  // 4) Negative case B: well-formed but unknown refresh token (random)
  const randomToken = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "random unknown refresh token should fail",
    async () => {
      await api.functional.auth.admin.refresh(connection, {
        body: { refresh_token: randomToken } satisfies ITodoAppAdmin.IRefresh,
      });
    },
  );

  // 5) Missing-token case: intentionally omitted (framework-level validation); document and skip
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppListShare } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppListShare";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_list_share_revoke_by_owner(
  connection: api.IConnection,
) {
  // 1) Prepare separate connection objects so join() populates per-connection tokens
  const ownerConn: api.IConnection = { ...connection, headers: {} };
  const otherConn: api.IConnection = { ...connection, headers: {} };

  // 1. Owner signs up
  const ownerEmail = `${RandomGenerator.alphaNumeric(8)}@example.com`;
  const ownerAuth: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(ownerConn, {
      body: {
        email: ownerEmail,
        password: "StrongPass1!",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        displayName: RandomGenerator.name(),
      } satisfies ITodoAppTodoUser.ICreate,
    });
  typia.assert(ownerAuth);

  // 2. Owner creates a todo list
  const listCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    visibility: "public",
  } satisfies ITodoAppList.ICreate;

  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    ownerConn,
    { body: listCreateBody },
  );
  typia.assert(list);
  TestValidator.predicate("created list has id", typeof list.id === "string");

  // 3. Owner creates a share for the list
  const shareCreateBody = {
    publicUrl: null,
    isPublic: true,
    visibility: "public",
    expiresAt: null,
  } satisfies ITodoAppListShare.ICreate;

  const share: ITodoAppListShare =
    await api.functional.todoApp.todoUser.lists.shares.create(ownerConn, {
      listId: list.id,
      body: shareCreateBody,
    });
  typia.assert(share);
  TestValidator.predicate("created share has id", typeof share.id === "string");

  // 4. Owner revokes the share
  await api.functional.todoApp.todoUser.lists.shares.erase(ownerConn, {
    listId: list.id,
    shareId: share.id,
  });

  // 5. Verify a new share can be created for the same list after revocation
  const newShare: ITodoAppListShare =
    await api.functional.todoApp.todoUser.lists.shares.create(ownerConn, {
      listId: list.id,
      body: {
        publicUrl: null,
        isPublic: true,
        visibility: "public",
        expiresAt: null,
      } satisfies ITodoAppListShare.ICreate,
    });
  typia.assert(newShare);
  TestValidator.notEquals(
    "new share id differs from old share id",
    share.id,
    newShare.id,
  );

  // 6. Unauthorized actor: create a second user and attempt to revoke newShare
  const otherEmail = `${RandomGenerator.alphaNumeric(8)}@example.com`;
  const otherAuth: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(otherConn, {
      body: {
        email: otherEmail,
        password: "AnotherPass1!",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        displayName: RandomGenerator.name(),
      } satisfies ITodoAppTodoUser.ICreate,
    });
  typia.assert(otherAuth);

  await TestValidator.error(
    "unauthorized user cannot revoke other's share",
    async () => {
      await api.functional.todoApp.todoUser.lists.shares.erase(otherConn, {
        listId: list.id,
        shareId: newShare.id,
      });
    },
  );

  // 7. Not-found: well-formed but non-existent UUIDs
  const missingListId = typia.random<string & tags.Format<"uuid">>();
  const missingShareId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error("not found for non-existent listId", async () => {
    await api.functional.todoApp.todoUser.lists.shares.erase(ownerConn, {
      listId: missingListId,
      shareId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  await TestValidator.error("not found for non-existent shareId", async () => {
    await api.functional.todoApp.todoUser.lists.shares.erase(ownerConn, {
      listId: list.id,
      shareId: missingShareId,
    });
  });

  // 8. Idempotency: calling erase again for the same newShare id should either succeed or return an error; ensure the system remains stable.
  try {
    await api.functional.todoApp.todoUser.lists.shares.erase(ownerConn, {
      listId: list.id,
      shareId: newShare.id,
    });
    // If succeeded again, it's acceptable (idempotent 204)
    TestValidator.predicate("second erase either succeeds (idempotent)", true);
  } catch (err) {
    // If server responded with not-found or similar, it's also acceptable
    TestValidator.predicate(
      "second erase may return not-found; operation tolerated",
      true,
    );
  }
}

