export async function test_api_collaboration_permission_update_by_admin(
  connection: api.IConnection,
) {
  /**
   * E2E test for admin updating collaboration permissions.
   *
   * Workflow:
   *
   * 1. Create an admin via POST /auth/admin/join (join creates auth token on
   *    connection)
   * 2. Create two collaboration permissions (Permission A and Permission B)
   * 3. Update Permission A with new code/description/isGrantable and assert
   *    success
   * 4. Attempt uniqueness-conflict update (set A.code to B.code) and expect 409
   * 5. Validate malformed-UUID (400), not-found (404), and unauthorized (401/403)
   */

  // 1) Register a new admin (join). join() will set connection.headers.Authorization
  const adminPayload = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassw0rd",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdmin.ICreate;

  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    { body: adminPayload },
  );
  typia.assert(admin);

  // Helper to create permission
  const createPermission = async (
    body: ITodoAppCollaborationPermission.ICreate,
  ): Promise<ITodoAppCollaborationPermission> => {
    const res =
      await api.functional.todoApp.admin.collaborationPermissions.create(
        connection,
        { body },
      );
    typia.assert(res);
    return res;
  };

  // 2) Create Permission A and Permission B
  const permissionABody = {
    code: "list.read",
    description: "Read lists",
    isGrantable: true,
  } satisfies ITodoAppCollaborationPermission.ICreate;

  const permissionBBody = {
    code: "list.write",
    description: "Write lists",
    isGrantable: true,
  } satisfies ITodoAppCollaborationPermission.ICreate;

  const permissionA: ITodoAppCollaborationPermission =
    await createPermission(permissionABody);
  const permissionB: ITodoAppCollaborationPermission =
    await createPermission(permissionBBody);

  // Basic sanity checks
  typia.assert(permissionA);
  typia.assert(permissionB);
  TestValidator.equals(
    "permission A code matches",
    permissionA.code,
    "list.read",
  );
  TestValidator.equals(
    "permission B code matches",
    permissionB.code,
    "list.write",
  );

  // 3) Successful update of Permission A
  const prevUpdatedAt = permissionA.updatedAt;

  const updateBody = {
    code: "list.read.v2",
    description: "Read-only lists (v2)",
    isGrantable: false,
  } satisfies ITodoAppCollaborationPermission.IUpdate;

  const updated: ITodoAppCollaborationPermission =
    await api.functional.todoApp.admin.collaborationPermissions.update(
      connection,
      {
        permissionId: permissionA.id,
        body: updateBody,
      },
    );
  typia.assert(updated);

  // Validate fields changed as expected
  TestValidator.equals("id unchanged after update", updated.id, permissionA.id);
  TestValidator.equals("code updated", updated.code, updateBody.code);
  TestValidator.equals(
    "description updated",
    updated.description,
    updateBody.description,
  );
  TestValidator.equals(
    "isGrantable updated",
    updated.isGrantable,
    updateBody.isGrantable,
  );
  TestValidator.predicate(
    "updatedAt should be newer",
    new Date(updated.updatedAt).getTime() > new Date(prevUpdatedAt).getTime(),
  );

  // 4) Uniqueness conflict: attempt to set Permission A's code to Permission B's code
  await TestValidator.httpError(
    "updating to duplicate code should return conflict",
    409,
    async () => {
      await api.functional.todoApp.admin.collaborationPermissions.update(
        connection,
        {
          permissionId: permissionA.id,
          body: {
            code: permissionB.code,
          } satisfies ITodoAppCollaborationPermission.IUpdate,
        },
      );
    },
  );

  // 5) Error and edge cases
  // 5.1 Invalid UUID format -> 400
  await TestValidator.httpError(
    "malformed permissionId should return 400",
    400,
    async () => {
      await api.functional.todoApp.admin.collaborationPermissions.update(
        connection,
        {
          permissionId: "invalid-uuid",
          body: {
            description: "noop",
          } satisfies ITodoAppCollaborationPermission.IUpdate,
        },
      );
    },
  );

  // 5.2 Not found: valid UUID that does not exist -> 404
  const randomNonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError(
    "updating non-existent permission should return 404",
    404,
    async () => {
      await api.functional.todoApp.admin.collaborationPermissions.update(
        connection,
        {
          permissionId: randomNonExistentId,
          body: {
            description: "not found update",
          } satisfies ITodoAppCollaborationPermission.IUpdate,
        },
      );
    },
  );

  // 5.3 Authorization: attempt PUT without admin token -> 401 or 403
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.httpError(
    "unauthenticated update should return 401/403",
    [401, 403],
    async () => {
      await api.functional.todoApp.admin.collaborationPermissions.update(
        unauthConn,
        {
          permissionId: permissionA.id,
          body: {
            description: "attempt without auth",
          } satisfies ITodoAppCollaborationPermission.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppUserMetrics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserMetrics";

/*
 * Validate admin view of aggregated user metrics for a TodoApp user.
 *
 * Business flow executed in this test:
 * 1. Create an admin account (join) using a cloned connection (adminConn).
 * 2. Create a todoUser account (join) using a cloned connection (userConn).
 * 3. Create a todo list for the todoUser.
 * 4. Create three tasks: completed, overdue, and pending.
 * 5. Retrieve aggregated metrics as admin and validate counts and computed fields.
 * 6. Validate negative/edge cases: unauthorized access, invalid UUID format, and non-existent user.
 *
 * Implementation notes:
 * - Use separate connection clones to simulate different authenticated actors
 *   (adminConn and userConn). Do NOT mutate the original `connection.headers`.
 * - Use typia.assert() on all non-void API responses to perform schema validation.
 * - Use TestValidator for all business assertions. Titles are descriptive and
 *   provided as the first parameter per TestValidator contract.
 * - This test uses unique emails and timestamps to avoid cross-test pollution.
 */
export async function test_api_todo_user_metrics_admin_view(
  connection: api.IConnection,
) {
  // 0. Prepare isolated connection clones for admin and todoUser
  const adminConn: api.IConnection = { ...connection, headers: {} };
  const userConn: api.IConnection = { ...connection, headers: {} };

  // 1. Admin join (register)
  const adminEmail = `${RandomGenerator.alphaNumeric(8)}@example.com`;
  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    adminConn,
    {
      body: {
        email: adminEmail,
        password: "Password123!",
        display_name: RandomGenerator.name(),
        href: "https://example.com/app",
        referrer: "https://example.com/",
        role: "superadmin",
      } satisfies ITodoAppAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 2. TodoUser join (register)
  const userEmail = `${RandomGenerator.alphaNumeric(8)}@example.com`;
  const todoUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(userConn, {
      body: {
        email: userEmail,
        password: "Userpass123!",
        href: "https://example.com/app",
        referrer: "https://example.com/",
        displayName: RandomGenerator.name(),
      } satisfies ITodoAppTodoUser.ICreate,
    });
  typia.assert(todoUser);

  // 3. Create a list for the todoUser
  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    userConn,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 4,
          wordMax: 8,
        }),
        description: RandomGenerator.paragraph({
          sentences: 4,
          wordMin: 5,
          wordMax: 10,
        }),
        visibility: "private",
      } satisfies ITodoAppList.ICreate,
    },
  );
  typia.assert(list);

  // 4. Create three tasks: completed, overdue, pending
  const now = new Date();
  const pastIso = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
  const futureIso = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();

  // Task A: completed
  const taskA: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(userConn, {
      listId: list.id,
      body: {
        title: "Completed task",
        description: "This task is completed",
        isCompleted: true,
        dueDate: pastIso,
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(taskA);

  // Task B: overdue (not completed, dueDate in past)
  const taskB: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(userConn, {
      listId: list.id,
      body: {
        title: "Overdue task",
        description: "This task is overdue",
        isCompleted: false,
        dueDate: pastIso,
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(taskB);

  // Task C: pending (not completed, dueDate in future)
  const taskC: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(userConn, {
      listId: list.id,
      body: {
        title: "Pending task",
        description: "This task is pending",
        isCompleted: false,
        dueDate: futureIso,
        priority: "low",
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(taskC);

  // 5. Admin retrieves metrics for the todoUser
  const metrics: ITodoAppUserMetrics =
    await api.functional.todoApp.admin.todoUsers.metrics(adminConn, {
      todoUserId: todoUser.id,
    });
  typia.assert(metrics);

  // Business assertions
  TestValidator.equals(
    "total tasks equals created tasks",
    metrics.totalTasks,
    3,
  );
  TestValidator.equals(
    "completed tasks count equals number of completed tasks",
    metrics.completedTasksCount,
    1,
  );
  TestValidator.equals(
    "overdue tasks count equals number of overdue tasks",
    metrics.overdueTasksCount,
    1,
  );
  TestValidator.equals(
    "active lists count equals created lists",
    metrics.activeListsCount,
    1,
  );

  // completionRate should be between 0 and 1 (synchronous predicate)
  TestValidator.predicate(
    "completion rate is within [0,1]",
    metrics.completionRate >= 0 && metrics.completionRate <= 1,
  );

  // averageTimeToCompleteSeconds should be a number when at least one completed task exists
  TestValidator.predicate(
    "averageTimeToCompleteSeconds is number or null",
    metrics.averageTimeToCompleteSeconds === null ||
      typeof metrics.averageTimeToCompleteSeconds === "number",
  );

  // lastActiveAt may be null or ISO datetime string; typia.assert already validated format when present
  TestValidator.predicate(
    "lastActiveAt is present or null",
    metrics.lastActiveAt === null || typeof metrics.lastActiveAt === "string",
  );

  // 6. Negative / edge checks
  // 6.1 Unauthorized access: todoUser token should not be allowed to call admin endpoint
  await TestValidator.error(
    "todoUser token cannot access admin metrics",
    async () => {
      await api.functional.todoApp.admin.todoUsers.metrics(userConn, {
        todoUserId: todoUser.id,
      });
    },
  );

  // 6.2 Invalid UUID format → expect error (pass plain string literal)
  await TestValidator.error("invalid UUID format yields error", async () => {
    await api.functional.todoApp.admin.todoUsers.metrics(adminConn, {
      todoUserId: "invalid-uuid",
    });
  });

  // 6.3 Non-existent user → expect error
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent user yields error", async () => {
    await api.functional.todoApp.admin.todoUsers.metrics(adminConn, {
      todoUserId: randomId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdmin";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";

/**
 * Verify admin accounts listing, filtering, pagination, and authorization.
 *
 * Business context:
 *
 * - Only admin actors should be able to retrieve the paginated list of
 *   administrative accounts. The listing endpoint supports filtering by role
 *   and isActive, sorting, and pagination.
 *
 * Test steps:
 *
 * 1. Create a primary admin (superadmin) via POST /auth/admin/join. SDK will set
 *    connection.headers.Authorization automatically.
 * 2. Create two more admins with different roles (support, moderator) to ensure
 *    listing returns multiple items.
 * 3. Call PATCH /todoApp/admin/admins (index) with pagination and validate
 *    response shape and pagination metadata.
 * 4. Apply role and isActive filters and validate results.
 * 5. Verify unauthorized access is rejected (no token).
 * 6. Verify invalid pagination parameters produce validation errors.
 */
export async function test_api_admin_accounts_index_listing(
  connection: api.IConnection,
) {
  // Helper to create an admin account and assert the authorized response
  const createAdmin = async (
    body: ITodoAppAdmin.ICreate,
  ): Promise<ITodoAppAdmin.IAuthorized> => {
    const authorized: ITodoAppAdmin.IAuthorized =
      await api.functional.auth.admin.join(connection, {
        body,
      });
    typia.assert(authorized);
    return authorized;
  };

  // 1) Create primary admin (superadmin)
  const primaryEmail = typia.random<string & tags.Format<"email">>();
  const primaryAdmin = await createAdmin({
    email: primaryEmail,
    password: "P@ssw0rd123",
    display_name: RandomGenerator.name(),
    role: "superadmin",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdmin.ICreate);
  // Ensure authorized payload contains id and token
  TestValidator.predicate(
    "primary admin has id",
    typeof primaryAdmin.id === "string" && primaryAdmin.id.length > 0,
  );
  typia.assert(primaryAdmin.token);

  // 2) Create additional admins to populate listing
  const supportEmail = typia.random<string & tags.Format<"email">>();
  const supportAdmin = await createAdmin({
    email: supportEmail,
    password: "SupportPwd123",
    display_name: RandomGenerator.name(),
    role: "support",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdmin.ICreate);

  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorAdmin = await createAdmin({
    email: moderatorEmail,
    password: "ModPwd12345",
    display_name: RandomGenerator.name(),
    role: "moderator",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdmin.ICreate);

  // 3) Happy path: list admins with pagination
  const listing: IPageITodoAppAdmin.ISummary =
    await api.functional.todoApp.admin.admins.index(connection, {
      body: {
        page: 1,
        pageSize: 10,
        sortBy: "createdAt",
        order: "asc",
      } satisfies ITodoAppAdmin.IRequest,
    });
  typia.assert(listing);

  // Validate pagination metadata
  TestValidator.predicate(
    "pagination current is non-negative",
    listing.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit is non-negative",
    listing.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    listing.pagination.records >= 0,
  );
  TestValidator.predicate(
    "data contains at least one admin",
    Array.isArray(listing.data) && listing.data.length >= 1,
  );

  // Ensure created admins are present in returned data by matching emails
  const emails = listing.data.map((s) => s.email);
  TestValidator.predicate(
    "primary admin present in listing",
    emails.includes(primaryEmail),
  );
  TestValidator.predicate(
    "support admin present in listing",
    emails.includes(supportEmail),
  );
  TestValidator.predicate(
    "moderator admin present in listing",
    emails.includes(moderatorEmail),
  );

  // 4) Filtering: by role
  const supportOnly: IPageITodoAppAdmin.ISummary =
    await api.functional.todoApp.admin.admins.index(connection, {
      body: {
        role: "support",
        page: 1,
        pageSize: 10,
      } satisfies ITodoAppAdmin.IRequest,
    });
  typia.assert(supportOnly);
  TestValidator.predicate(
    "support filter returns only support role",
    supportOnly.data.every((d) => d.role === "support"),
  );

  // Filtering: by isActive=true (should return active accounts)
  const activeOnly: IPageITodoAppAdmin.ISummary =
    await api.functional.todoApp.admin.admins.index(connection, {
      body: {
        isActive: true,
        page: 1,
        pageSize: 10,
      } satisfies ITodoAppAdmin.IRequest,
    });
  typia.assert(activeOnly);
  TestValidator.predicate(
    "isActive filter returns only active accounts",
    activeOnly.data.every((d) => d.isActive === true),
  );

  // 5) Negative: unauthorized access (no token)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized without token", async () => {
    await api.functional.todoApp.admin.admins.index(unauthConn, {
      body: {} satisfies ITodoAppAdmin.IRequest,
    });
  });

  // 6) Negative: invalid pagination parameters (page=0 or negative pageSize)
  await TestValidator.error("invalid page param should fail", async () => {
    await api.functional.todoApp.admin.admins.index(connection, {
      body: {
        page: 0,
      } satisfies ITodoAppAdmin.IRequest,
    });
  });

  await TestValidator.error("invalid pageSize should fail", async () => {
    await api.functional.todoApp.admin.admins.index(connection, {
      body: {
        page: 1,
        pageSize: -5,
      } satisfies ITodoAppAdmin.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAuditLog";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAuditLog";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_audit_log_index_admin_search(
  connection: api.IConnection,
) {
  /**
   * Test: Admin can search audit logs and discover events produced by todoUser
   * actions.
   *
   * Steps:
   *
   * 1. Create a todoUser (self-signup) -> ITodoAppTodoUser.IAuthorized
   * 2. As that user, create a list -> ITodoAppList
   * 3. As that user, create a task under the list -> ITodoAppTask
   * 4. Create an admin (self-signup) -> ITodoAppAdmin.IAuthorized
   * 5. As admin, search audit logs with a recent time-window and filters to locate
   *    events related to the created list/task
   * 6. Assert pagination metadata and that at least one returned item references
   *    the created listId or taskId
   * 7. Negative checks: unauthenticated and non-admin access must be rejected
   */

  // 1) Create todo user
  const todoUserBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd1",
    href: "https://example.com/signup",
    referrer: "https://example.com/",
    displayName: RandomGenerator.name(),
  } satisfies ITodoAppTodoUser.ICreate;

  const todoUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: todoUserBody,
    });
  typia.assert(todoUser);

  // 2) Create a todo list as the todoUser (SDK sets Authorization on connection)
  const listBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    description: RandomGenerator.paragraph({
      sentences: 6,
      wordMin: 4,
      wordMax: 8,
    }),
    visibility: "private",
  } satisfies ITodoAppList.ICreate;

  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    connection,
    {
      body: listBody,
    },
  );
  typia.assert(list);

  // 3) Create a task under the list as the todoUser
  const taskBody = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 6 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    isCompleted: false,
  } satisfies ITodoAppTask.ICreate;

  const task: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: list.id,
      body: taskBody,
    });
  typia.assert(task);

  // 4) Create an admin account and capture its authorization (SDK will set token on connection)
  const adminBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminP@ss1",
    href: "https://example.com/admin-signup",
    referrer: "https://example.com/",
    display_name: RandomGenerator.name(),
    role: "superadmin",
  } satisfies ITodoAppAdmin.ICreate;

  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    {
      body: adminBody,
    },
  );
  typia.assert(admin);

  // 5) As admin, query audit logs for recent events related to created list/task
  const now = Date.now();
  const createdAfter = new Date(now - 5 * 60 * 1000).toISOString(); // 5 minutes ago
  const createdBefore = new Date(now + 5 * 60 * 1000).toISOString(); // 5 minutes in future

  const auditRequest = {
    createdAfter,
    createdBefore,
    listId: list.id,
    taskId: task.id,
    page: 1,
    limit: 20,
    order: "desc",
    sortBy: "createdAt",
  } satisfies ITodoAppAuditLog.IRequest;

  const page: IPageITodoAppAuditLog.ISummary =
    await api.functional.todoApp.admin.auditLogs.index(connection, {
      body: auditRequest,
    });
  typia.assert(page);

  // Validate pagination info
  TestValidator.predicate("pagination exists and has fields", () => {
    return (
      page.pagination !== null &&
      typeof page.pagination.current === "number" &&
      typeof page.pagination.limit === "number" &&
      typeof page.pagination.records === "number"
    );
  });

  // Validate that at least one item references our listId or taskId
  const found = page.data.some(
    (item) =>
      item.targetId === list.id ||
      item.targetId === task.id ||
      (item.list && item.list.id === list.id) ||
      (item.task && item.task.id === task.id),
  );
  TestValidator.predicate(
    "audit results include events for created resources",
    found,
  );

  // 6) Negative tests: unauthenticated and non-admin should be rejected
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated request to admin audit logs should fail",
    async () => {
      await api.functional.todoApp.admin.auditLogs.index(unauthConn, {
        body: auditRequest,
      });
    },
  );

  // Also test that a non-admin user cannot access admin endpoint
  const nonAdminConn: api.IConnection = { ...connection, headers: {} };
  const nonAdminBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd2",
    href: "https://example.com/signup",
    referrer: "https://example.com/",
    displayName: RandomGenerator.name(),
  } satisfies ITodoAppTodoUser.ICreate;

  const nonAdmin = await api.functional.auth.todoUser.join(nonAdminConn, {
    body: nonAdminBody,
  });
  typia.assert(nonAdmin);

  await TestValidator.error(
    "non-admin user cannot access admin audit logs",
    async () => {
      await api.functional.todoApp.admin.auditLogs.index(nonAdminConn, {
        body: auditRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";
import type { ITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAuditLog";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";

export async function test_api_audit_log_get_detail_by_id(
  connection: api.IConnection,
) {
  // Purpose: Validate admin retrieval of a single audit log entry and verify
  // authorization enforcement. Because no audit-log search API is available in
  // the given SDK, this test performs domain actions to produce audit events
  // and then exercises the GET /todoApp/admin/auditLogs/:auditLogId endpoint
  // using a generated UUID to retrieve details. It validates response shape
  // and ensures unauthenticated access is rejected.

  // 1) Create a todo user (self-signup) to generate domain activity
  const todoUserEmail: string = typia.random<string & tags.Format<"email">>();
  const todoUser = await api.functional.auth.todoUser.join(connection, {
    body: {
      email: todoUserEmail,
      password: "Password123!",
      href: "https://example.com/signup",
      referrer: "https://example.com",
      displayName: RandomGenerator.name(),
    } satisfies ITodoAppTodoUser.ICreate,
  });
  typia.assert(todoUser);

  // 2) As the todo user (SDK sets Authorization header automatically), create a list
  const list = await api.functional.todoApp.todoUser.lists.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 3,
        wordMin: 3,
        wordMax: 8,
      }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
      visibility: "private",
    } satisfies ITodoAppList.ICreate,
  });
  typia.assert(list);

  // 3) Create a task under the created list to emit an additional audit event
  const task = await api.functional.todoApp.todoUser.lists.tasks.create(
    connection,
    {
      listId: list.id,
      body: {
        title: RandomGenerator.paragraph({
          sentences: 4,
          wordMin: 2,
          wordMax: 7,
        }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        isCompleted: false,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(task);

  // 4) Create an admin account (this will set Authorization header to admin token)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    {
      body: {
        email: adminEmail,
        password: "AdminPass123!",
        href: "https://example.com/admin/join",
        referrer: "https://example.com",
        role: "moderator",
        display_name: RandomGenerator.name(),
      } satisfies ITodoAppAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 5) Attempt to retrieve a single audit log by id as admin.
  // NOTE: The SDK does not provide a discovery/search endpoint in the provided
  // materials. Therefore we will exercise the GET endpoint by generating a
  // UUID and validating the returned ITodoAppAuditLog shape and that the
  // returned id matches the requested id. This verifies endpoint wiring and
  // authorization behaviour.
  const requestedAuditLogId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  const auditLog: ITodoAppAuditLog =
    await api.functional.todoApp.admin.auditLogs.at(connection, {
      auditLogId: requestedAuditLogId,
    });
  // Validate shape
  typia.assert(auditLog);

  // Business-level validations
  TestValidator.equals(
    "retrieved audit log id matches requested id",
    auditLog.id,
    requestedAuditLogId,
  );
  TestValidator.predicate(
    "audit log has eventType",
    typeof auditLog.eventType === "string" && auditLog.eventType.length > 0,
  );
  TestValidator.predicate(
    "audit log has createdAt timestamp",
    typeof auditLog.createdAt === "string" && auditLog.createdAt.length > 0,
  );

  // If targetId is present, it should be a UUID (typia.assert already enforces this)
  if (auditLog.targetId !== null && auditLog.targetId !== undefined) {
    // Ensure it's a string and non-empty (typia.assert validated the format)
    TestValidator.predicate(
      "audit log targetId present and non-empty",
      typeof auditLog.targetId === "string" && auditLog.targetId.length > 0,
    );
  }

  // 6) Authorization negative test: calling without admin authorization must fail
  // Create an unauthenticated connection (SDK pattern: copy and clear headers)
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated caller cannot retrieve admin audit log",
    async () => {
      await api.functional.todoApp.admin.auditLogs.at(unauthConn, {
        auditLogId: requestedAuditLogId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_list_public_retrieval(
  connection: api.IConnection,
) {
  // NOTE: This E2E test performs the following sequence:
  // 1) Create a todoUser via POST /auth/todoUser/join -> obtains token (SDK injects token into connection.headers)
  // 2) Create two lists (public and private) via POST /todoApp/todoUser/lists
  // 3) Without authentication (unauthConn), GET the public list -> expect 200 and ITodoAppList shape
  // 4) Without authentication, GET the private list -> expect authorization denial (403 or 404)
  // 5) With owner token (original connection), GET the private list -> expect 200 and owner-visible fields
  // IMPORTANT: typia.assert() is used to validate response types; TestValidator.* used for business assertions

  // 1) Register a new todoUser (join) to act as owner
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const owner: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: {
        email: userEmail,
        password: "Password123!",
        href: "https://example.com/signup",
        referrer: "https://example.com",
        displayName: RandomGenerator.name(),
      } satisfies ITodoAppTodoUser.ICreate,
    });
  typia.assert(owner);

  // 2) Create a public list
  const publicListTitle = "Public Shopping List";
  const publicList: ITodoAppList =
    await api.functional.todoApp.todoUser.lists.create(connection, {
      body: {
        title: publicListTitle,
        visibility: "public",
      } satisfies ITodoAppList.ICreate,
    });
  typia.assert(publicList);

  // 2b) Create a private list
  const privateListTitle = "Private Work List";
  const privateList: ITodoAppList =
    await api.functional.todoApp.todoUser.lists.create(connection, {
      body: {
        title: privateListTitle,
        visibility: "private",
      } satisfies ITodoAppList.ICreate,
    });
  typia.assert(privateList);

  // Save ids for downstream verification
  const publicListId: string = publicList.id;
  const privateListId: string = privateList.id;

  // 3) Unauthenticated retrieval of public list
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const publicRead: ITodoAppList = await api.functional.todoApp.lists.at(
    unauthConn,
    { listId: publicListId },
  );
  typia.assert(publicRead);

  // Business assertions for public list
  TestValidator.equals("public list id matches", publicRead.id, publicListId);
  TestValidator.equals(
    "public list title matches",
    publicRead.title,
    publicListTitle,
  );
  TestValidator.equals(
    "public list visibility is public",
    publicRead.visibility,
    "public",
  );
  // Owner summary must be present but not necessarily identical object reference
  TestValidator.predicate(
    "public list has owner summary",
    publicRead.owner !== null &&
      publicRead.owner !== undefined &&
      typeof publicRead.owner.id === "string",
  );

  // 4) Unauthenticated retrieval of private list should be denied (403 or 404)
  await TestValidator.httpError(
    "unauthenticated access to private list should be denied",
    [403, 404],
    async () => {
      await api.functional.todoApp.lists.at(unauthConn, {
        listId: privateListId,
      });
    },
  );

  // 5) Owner (authenticated) retrieval of private list should succeed
  const privateReadByOwner: ITodoAppList =
    await api.functional.todoApp.lists.at(connection, {
      listId: privateListId,
    });
  typia.assert(privateReadByOwner);
  TestValidator.equals(
    "private list id matches for owner",
    privateReadByOwner.id,
    privateListId,
  );
  TestValidator.equals(
    "private list title matches for owner",
    privateReadByOwner.title,
    privateListTitle,
  );
  TestValidator.equals(
    "private list visibility is private for owner",
    privateReadByOwner.visibility,
    "private",
  );

  // Owner summary must reference the owner created earlier
  TestValidator.equals(
    "owner id equals created user id",
    privateReadByOwner.owner.id,
    owner.id,
  );

  // Note: typia.assert already validated createdAt/updatedAt formats per DTO tags.
  // End of test
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodouserSession";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";

export async function test_api_todo_user_session_revoke_by_owner(
  connection: api.IConnection,
) {
  // 1) Create a new todoUser via join (self-signup)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123",
    href: "https://example.com/welcome",
    referrer: "https://example.com/",
  } satisfies ITodoAppTodoUser.ICreate;

  const auth: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, { body: joinBody });
  typia.assert(auth);
  // Ensure token container exists and has an access token
  typia.assert<IAuthorizationToken>(auth.token);
  TestValidator.predicate(
    "join returned a non-empty access token",
    !!auth.token.access,
  );

  const todoUserId: string = auth.id;

  // 2) List sessions for the newly created user to capture an active sessionId
  const pageResult: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoUser.todoUsers.sessions.index(connection, {
      todoUserId,
      body: {
        page: 1,
        pageSize: 10,
        status: "all",
      } satisfies ITodoAppTodouserSession.IRequest,
    });
  typia.assert(pageResult);

  TestValidator.predicate(
    "at least one session exists after join",
    pageResult.data.length > 0,
  );

  const sessionId: string = pageResult.data[0].id;

  // 3) Revoke (hard-delete) the captured session by owner
  await api.functional.todoApp.todoUser.todoUsers.sessions.erase(connection, {
    todoUserId,
    sessionId,
  });

  // 4) Verify deletion: GET should now fail (session not found)
  await TestValidator.error(
    `deleted session (${sessionId}) should not be retrievable`,
    async () => {
      await api.functional.todoApp.todoUser.todoUsers.sessions.at(connection, {
        todoUserId,
        sessionId,
      });
    },
  );

  // 5) Additional check: listing sessions should not include revoked session id
  const pageAfter: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoUser.todoUsers.sessions.index(connection, {
      todoUserId,
      body: {
        page: 1,
        pageSize: 20,
        status: "all",
      } satisfies ITodoAppTodouserSession.IRequest,
    });
  typia.assert(pageAfter);

  TestValidator.predicate(
    `revoked session id (${sessionId}) should not appear in session listing`,
    !pageAfter.data.some((s) => s.id === sessionId),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppUserMetrics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserMetrics";

export async function test_api_user_metrics_aggregation(
  connection: api.IConnection,
) {
  // 1) Register a fresh todo user and capture authorization
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    displayName: RandomGenerator.name(),
    href: "http://localhost/",
    referrer: "http://localhost/",
  } satisfies ITodoAppTodoUser.ICreate;

  const authorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // Save todoUserId for metrics
  const todoUserId: string & tags.Format<"uuid"> = authorized.id;

  // 2) Create a todo list for the user
  const listBody = {
    title: "Metrics Test List",
    visibility: "private",
  } satisfies ITodoAppList.ICreate;

  const list: ITodoAppList = await api.functional.todoApp.todoUser.lists.create(
    connection,
    {
      body: listBody,
    },
  );
  typia.assert(list);

  // 3) Create three tasks under the list: completed, overdue, upcoming
  const pastISO = new Date(Date.now() - 2 * 24 * 60 * 60 * 1000).toISOString();
  const futureISO = new Date(
    Date.now() + 7 * 24 * 60 * 60 * 1000,
  ).toISOString();

  // Task A: completed
  const taskAReq = {
    title: "Task A - completed",
    isCompleted: true,
  } satisfies ITodoAppTask.ICreate;
  const taskA: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: list.id,
      body: taskAReq,
    });
  typia.assert(taskA);

  // Task B: overdue (dueDate in the past)
  const taskBReq = {
    title: "Task B - overdue",
    dueDate: pastISO,
    isCompleted: false,
  } satisfies ITodoAppTask.ICreate;
  const taskB: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: list.id,
      body: taskBReq,
    });
  typia.assert(taskB);

  // Task C: upcoming (dueDate in the future)
  const taskCReq = {
    title: "Task C - upcoming",
    dueDate: futureISO,
  } satisfies ITodoAppTask.ICreate;
  const taskC: ITodoAppTask =
    await api.functional.todoApp.todoUser.lists.tasks.create(connection, {
      listId: list.id,
      body: taskCReq,
    });
  typia.assert(taskC);

  // 4) Call metrics endpoint and validate ITodoAppUserMetrics
  const metrics: ITodoAppUserMetrics =
    await api.functional.todoApp.todoUser.todoUsers.metrics(connection, {
      todoUserId,
    });
  typia.assert(metrics);

  // Business assertions
  TestValidator.equals("totalTasks should be 3", metrics.totalTasks, 3);
  TestValidator.equals(
    "completedTasksCount should be 1",
    metrics.completedTasksCount,
    1,
  );
  TestValidator.equals(
    "overdueTasksCount should be 1",
    metrics.overdueTasksCount,
    1,
  );
  TestValidator.equals(
    "activeListsCount should be 1",
    metrics.activeListsCount,
    1,
  );

  // completionRate consistency: completed / total (guard against totalTasks===0)
  TestValidator.predicate(
    "completionRate equals completed/total",
    Math.abs(
      metrics.completionRate -
        (metrics.totalTasks === 0
          ? 0
          : metrics.completedTasksCount / metrics.totalTasks),
    ) < 1e-6,
  );

  // averageTimeToCompleteSeconds is either number or null
  TestValidator.predicate(
    "averageTimeToCompleteSeconds is number or null",
    metrics.averageTimeToCompleteSeconds === null ||
      typeof metrics.averageTimeToCompleteSeconds === "number",
  );

  // lastActiveAt presence is validated by typia.assert (format checked); ensure property exists
  TestValidator.predicate(
    "lastActiveAt present (may be null)",
    metrics.lastActiveAt !== undefined,
  );

  // 5) Negative checks
  // 5a) Non-existent user (valid UUID but not present) should cause an error
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "non-existent user metrics request should fail",
    async () => {
      await api.functional.todoApp.todoUser.todoUsers.metrics(connection, {
        todoUserId: nonExistentId,
      });
    },
  );

  // 5b) Unauthorized access: use an unauthenticated connection clone
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated request should fail", async () => {
    await api.functional.todoApp.todoUser.todoUsers.metrics(unauthConn, {
      todoUserId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppCollaborationPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCollaborationPermission";

/**
 * Validate admin soft-delete of a collaboration permission by id.
 *
 * Business context:
 *
 * - An administrator can register a new collaboration permission (code,
 *   description, isGrantable) that controls collaboration-related
 *   authorization.
 * - Administrators may later soft-delete (retire) a permission by id. The API
 *   implements soft-delete semantics (sets deleted_at) and the delete operation
 *   is idempotent.
 *
 * Test steps:
 *
 * 1. Admin signs up via POST /auth/admin/join (ITodoAppAdmin.ICreate) and receives
 *    ITodoAppAdmin.IAuthorized with tokens. The SDK populates connection
 *    headers.
 * 2. Using the admin context, create a collaboration permission via POST
 *    /todoApp/admin/collaborationPermissions
 *    (ITodoAppCollaborationPermission.ICreate).
 * 3. Soft-delete the permission using DELETE
 *    /todoApp/admin/collaborationPermissions/{permissionId}.
 * 4. Call DELETE again for the same id to validate idempotency (operation should
 *    not throw).
 *
 * Notes:
 *
 * - No GET-by-id endpoint is available in the provided SDK; therefore we validate
 *   deletion via idempotency and successful creation assertions.
 */
export async function test_api_collaboration_permission_soft_delete_by_id_admin(
  connection: api.IConnection,
) {
  // 1. Admin sign-up (join) to obtain admin credentials and auth token
  const adminBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd-1234",
    display_name: RandomGenerator.name(),
    role: "superadmin",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdmin.ICreate;

  const admin: ITodoAppAdmin.IAuthorized = await api.functional.auth.admin.join(
    connection,
    {
      body: adminBody,
    },
  );
  // Validate admin response shape and token presence
  typia.assert(admin);
  TestValidator.predicate(
    "admin join returned token",
    typeof admin.token?.access === "string" && admin.token.access.length > 0,
  );

  // 2. Create a collaboration permission with a unique code
  const code = `test.permission.delete.byId-${RandomGenerator.alphaNumeric(8)}`;
  const permissionBody = {
    code,
    description: RandomGenerator.paragraph({ sentences: 3 }),
    isGrantable: true,
  } satisfies ITodoAppCollaborationPermission.ICreate;

  const permission: ITodoAppCollaborationPermission =
    await api.functional.todoApp.admin.collaborationPermissions.create(
      connection,
      {
        body: permissionBody,
      },
    );
  // Validate response shape
  typia.assert(permission);

  // Business assertions
  TestValidator.equals(
    "created permission code matches",
    permission.code,
    code,
  );
  TestValidator.equals(
    "created permission isGrantable",
    permission.isGrantable,
    true,
  );
  // Ensure returned id looks like a UUID (typia.assert already validates formats)
  TestValidator.predicate(
    "permission id present",
    typeof permission.id === "string" && permission.id.length > 0,
  );

  // 3. Soft-delete the permission by id
  await api.functional.todoApp.admin.collaborationPermissions.eraseByPermissionid(
    connection,
    {
      permissionId: permission.id,
    },
  );

  // 4. Call delete again to validate idempotency (should not throw)
  let secondDeleteSucceeded = false;
  await api.functional.todoApp.admin.collaborationPermissions.eraseByPermissionid(
    connection,
    {
      permissionId: permission.id,
    },
  );
  secondDeleteSucceeded = true;
  TestValidator.predicate(
    "delete is idempotent (second call succeeds)",
    secondDeleteSucceeded === true,
  );
}

