        state: "revoked",
      } satisfies ITodoAppInvitation.IUpdate,
    });
  typia.assert(updatedByOwner);
  TestValidator.equals(
    "owner can revoke the invitation",
    updatedByOwner.state,
    "revoked",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppPublicIndexPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppPublicIndexPreference";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function test_api_public_index_preferences_retrieval_by_owner(
  connection: api.IConnection,
) {
  /**
   * Purpose:
   *
   * - Verify that a todoUser who creates a public list can retrieve its
   *   associated public index preferences.
   * - Validate access control (unauthorized request), invalid UUID handling, and
   *   not-found behavior.
   *
   * Steps:
   *
   * 1. Join a new todoUser (POST /auth/todoUser/join)
   * 2. Create a public list (POST /todoApp/todoUser/lists)
   * 3. Retrieve publicIndexPreferences as owner (GET
   *    /todoApp/.../publicIndexPreferences)
   * 4. Unauthorized access: same endpoint without auth → expect 401 or 403
   * 5. Invalid UUID format → expect 400
   * 6. Non-existent UUID → expect 404
   */

  // 1) Create a new todoUser via join
  const userInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd-1234",
    displayName: RandomGenerator.name(),
    href: "https://example.com/signup",
    referrer: "https://example.com",
  } satisfies ITodoAppTodoUser.ICreate;

  const authorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userInput,
    });
  typia.assert(authorized);

  // 2) Create a public list as the joined user
  const listBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    visibility: "public",
  } satisfies ITodoAppList.ICreate;

  const createdList: ITodoAppList =
    await api.functional.todoApp.todoUser.lists.create(connection, {
      body: listBody,
    });
  typia.assert(createdList);
  TestValidator.equals(
    "created list visibility is public",
    createdList.visibility,
    "public",
  );

  // 3) Happy path: Retrieve publicIndexPreferences as the owner
  const pref: ITodoAppPublicIndexPreference =
    await api.functional.todoApp.todoUser.lists.publicIndexPreferences.at(
      connection,
      {
        listId: createdList.id,
      },
    );
  typia.assert(pref);

  // Business validations
  TestValidator.equals(
    "preference references created list",
    pref.todoAppListId,
    createdList.id,
  );
  // Typia already enforces types and date formats; assert deletedAt is null
  TestValidator.equals("deleted_at is null", pref.deletedAt, null);
  TestValidator.predicate(
    "indexingEnabled is boolean",
    typeof pref.indexingEnabled === "boolean",
  );

  // 4) Unauthorized access: create an unauthenticated connection copy
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.httpError(
    "unauthorized access should be denied",
    [401, 403],
    async () => {
      await api.functional.todoApp.todoUser.lists.publicIndexPreferences.at(
        unauthConn,
        { listId: createdList.id },
      );
    },
  );

  // 5) Invalid UUID format → expect 400
  // The SDK types the path param as a tagged UUID type. To intentionally send
  // an invalid format while keeping TypeScript satisfied, coerce the string
  // into the tagged type using a safe pattern (satisfies/as). This is only to
  // test server-side validation of path parameter format.
  const invalidListId =
    "not-a-valid-uuid" satisfies string as unknown as string &
      tags.Format<"uuid">;
  await TestValidator.httpError(
    "invalid uuid format should return 400",
    400,
    async () => {
      await api.functional.todoApp.todoUser.lists.publicIndexPreferences.at(
        connection,
        { listId: invalidListId },
      );
    },
  );

  // 6) Not found: use a random UUID that is unlikely to exist
  const nonExistentUuid = typia.random<string & tags.Format<"uuid">>();
  // Ensure we do not accidentally use the created list id
  if (nonExistentUuid === createdList.id) {
    // Regenerate (extremely unlikely) - typia.random is used again
    // Use typia.assert to ensure the value is of correct tagged type
    const again = typia.random<string & tags.Format<"uuid">>();
    typia.assert(again);
  }

  await TestValidator.httpError(
    "non-existent list should return 404",
    404,
    async () => {
      await api.functional.todoApp.todoUser.lists.publicIndexPreferences.at(
        connection,
        { listId: nonExistentUuid },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import type { ITodoAppPublicIndexPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppPublicIndexPreference";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

/**
 * Validate admin retrieval of a list's public index preferences.
 *
 * Business context:
 *
 * - A normal todoUser creates a public list. Administrative operators must be
 *   able to review the list's public-indexing preferences (indexingEnabled,
 *   allowSearchEngine, allowDiscovery, indexScope) via an admin-scoped
 *   endpoint.
 *
 * Test steps:
 *
 * 1. Register a todoUser (join) and capture auth token (SDK will set it on
 *    connection.headers).
 * 2. Create a public todo list as the todoUser and capture list.id.
 * 3. Register a new admin (join) using a fresh unauthenticated connection.
 * 4. As admin, GET the public index preferences for the created list and validate
 *    the response shape and business fields.
 * 5. Unauthorized access: attempt the same admin GET using the todoUser token and
 *    assert an error is thrown (authorization enforcement).
 * 6. Not-found: call the admin GET with a valid, random UUID that does not map to
 *    an existing list and assert an error is thrown.
 */
export async function test_api_public_index_preferences_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1) todoUser join (self-signup)
  const todoUser = await api.functional.auth.todoUser.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd123",
      displayName: RandomGenerator.name(),
      href: "http://example.com/signup",
      referrer: "http://referrer.example/",
    } satisfies ITodoAppTodoUser.ICreate,
  });
  typia.assert(todoUser);

  // 2) Create a public list as the todoUser
  const list = await api.functional.todoApp.todoUser.lists.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 3,
        wordMin: 3,
        wordMax: 8,
      }),
      description: RandomGenerator.paragraph({ sentences: 5 }),
      visibility: "public",
    } satisfies ITodoAppList.ICreate,
  });
  typia.assert(list);

  // 3) Admin join using a fresh unauthenticated connection object
  const adminConn: api.IConnection = { ...connection, headers: {} };
  const admin = await api.functional.auth.admin.join(adminConn, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Adm1nPass!",
      display_name: RandomGenerator.name(),
      role: "superadmin",
      href: "http://example.com/admin-join",
      referrer: "http://referrer.example/",
    } satisfies ITodoAppAdmin.ICreate,
  });
  typia.assert(admin);

  // 4) Happy-path: admin retrieves public index preferences for the created list
  const pref: ITodoAppPublicIndexPreference =
    await api.functional.todoApp.admin.lists.publicIndexPreferences.at(
      adminConn,
      {
        listId: list.id,
      },
    );
  typia.assert(pref);

  // Business-level validations
  TestValidator.equals(
    "preference belongs to created list",
    pref.todoAppListId,
    list.id,
  );
  TestValidator.predicate(
    "indexScope is string or null",
    pref.indexScope === null || typeof pref.indexScope === "string",
  );
  TestValidator.predicate(
    "indexingEnabled is boolean",
    typeof pref.indexingEnabled === "boolean",
  );
  TestValidator.predicate(
    "allowSearchEngine is boolean",
    typeof pref.allowSearchEngine === "boolean",
  );
  TestValidator.predicate(
    "allowDiscovery is boolean",
    typeof pref.allowDiscovery === "boolean",
  );

  // 5) Unauthorized access: using todoUser token (connection currently holds todoUser token)
  await TestValidator.error(
    "non-admin cannot access admin publicIndexPreferences",
    async () => {
      await api.functional.todoApp.admin.lists.publicIndexPreferences.at(
        connection,
        {
          listId: list.id,
        },
      );
    },
  );

  // 6) Not-found: admin requests preferences for a non-existent list id
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "admin requesting preferences for non-existent list should fail",
    async () => {
      await api.functional.todoApp.admin.lists.publicIndexPreferences.at(
        adminConn,
        {
          listId: nonExistentId,
        },
      );
    },
  );
}

