import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminAction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminAction";
import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdminAdminActionsAdminActionId(props: {
  admin: AdminPayload;
  adminActionId: string & tags.Format<"uuid">;
}): Promise<ITodoAppAdminAction> {
  const { admin, adminActionId } = props;

  // Fetch the admin action with related entities
  const action = await MyGlobal.prisma.todo_app_admin_actions.findUnique({
    where: { id: adminActionId },
    include: {
      admin: true,
      adminSession: { include: { admin: true } },
      affectedUser: true,
    },
  });

  if (!action) {
    throw new HttpException("Not Found", 404);
  }

  // Load requesting admin to perform authorization checks
  const requester = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
  });

  if (!requester || !requester.is_active || requester.deleted_at !== null) {
    throw new HttpException("Unauthorized", 403);
  }

  // Only the actor or a superadmin may view the record
  if (
    requester.role !== "superadmin" &&
    action.todo_app_admin_id !== admin.id
  ) {
    throw new HttpException("Forbidden: insufficient permissions", 403);
  }

  // Map admin summary
  const adminSummary = {
    id: action.admin.id,
    email: action.admin.email,
    displayName: action.admin.display_name ?? null,
    role: typia.assert<"moderator" | "support" | "superadmin">(
      action.admin.role,
    ),
    isActive: action.admin.is_active,
    createdAt: toISOStringSafe(action.admin.created_at),
    updatedAt: action.admin.updated_at
      ? toISOStringSafe(action.admin.updated_at)
      : null,
    deletedAt: action.admin.deleted_at
      ? toISOStringSafe(action.admin.deleted_at)
      : null,
  } satisfies ITodoAppAdmin.ISummary;

  // Map adminSession summary when present
  const adminSessionSummary = action.adminSession
    ? ({
        id: action.adminSession.id,
        admin: adminSummary,
        ip: action.adminSession.ip,
        href: action.adminSession.href,
        referrer: action.adminSession.referrer,
        createdAt: toISOStringSafe(action.adminSession.created_at),
        // Ensure expiredAt is always a date-time string (fallback to created_at)
        expiredAt: toISOStringSafe(
          action.adminSession.expired_at ?? action.adminSession.created_at,
        ),
      } satisfies ITodoAppAdminSession.ISummary)
    : undefined;

  // Map affectedUser when present
  const affectedUserSummary = action.affectedUser
    ? ({
        id: action.affectedUser.id,
        displayName: action.affectedUser.display_name ?? null,
        isVerified: action.affectedUser.is_verified,
        status: action.affectedUser.status ?? undefined,
        createdAt: toISOStringSafe(action.affectedUser.created_at),
        // Ensure updatedAt is always a date-time string (fallback to created_at)
        updatedAt: toISOStringSafe(
          action.affectedUser.updated_at ?? action.affectedUser.created_at,
        ),
      } satisfies ITodoAppTodoUser.ISummary)
    : undefined;

  // Build and return the DTO
  return {
    id: action.id,
    admin: adminSummary,
    adminSession: adminSessionSummary ?? null,
    affectedUser: affectedUserSummary ?? null,
    action: action.action,
    reason: action.reason ?? null,
    targetType: action.target_type ?? null,
    targetId: action.target_id ?? null,
    details: action.details ?? null,
    auditCaseId: action.audit_case_id ?? null,
    createdAt: toISOStringSafe(action.created_at),
    updatedAt: action.updated_at ? toISOStringSafe(action.updated_at) : null,
    deletedAt: action.deleted_at ? toISOStringSafe(action.deleted_at) : null,
  } as ITodoAppAdminAction;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminDashboard } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminDashboard";
import { ITodoAppAdminTotals } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminTotals";
import { ITodoAppTaskStats } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskStats";
import { ITodoAppAdminActionSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminActionSummary";
import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppListSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppListSummary";
import { ITodoAppInvitationSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppInvitationSummary";
import { ITodoAppUserSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSummary";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdminDashboardAdminOverview(props: {
  admin: AdminPayload;
}): Promise<ITodoAppAdminDashboard> {
  const { admin } = props;
  if (!admin || admin.type !== "admin") {
    throw new HttpException("Unauthorized", 401);
  }

  try {
    const now = toISOStringSafe(new Date());
    const window30Days = toISOStringSafe(
      new Date(Date.now() - 30 * 24 * 60 * 60 * 1000),
    );
    const dueSoonEnd = toISOStringSafe(
      new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
    );

    const [
      totalUsers,
      suspendedAccounts,
      totalLists,
      publicLists,
      privateLists,
      pendingInvitations,
      totalTasks,
      completedTasks,
      dueSoonCount,
      activityRows,
      recentAdminActionsRaw,
      topListsRaw,
      recentInvitationsRaw,
      usersSampleRaw,
    ] = await Promise.all([
      MyGlobal.prisma.todo_app_todouser.count({ where: { deleted_at: null } }),
      MyGlobal.prisma.todo_app_todouser.count({
        where: { status: "suspended", deleted_at: null },
      }),
      MyGlobal.prisma.todo_app_lists.count({ where: { deleted_at: null } }),
      MyGlobal.prisma.todo_app_lists.count({
        where: { deleted_at: null, visibility: "public" },
      }),
      MyGlobal.prisma.todo_app_lists.count({
        where: {
          deleted_at: null,
          visibility: { in: ["private", "shared-invite-only"] },
        },
      }),
      MyGlobal.prisma.todo_app_invitations.count({
        where: { state: "pending", deleted_at: null, expires_at: { gt: now } },
      }),
      MyGlobal.prisma.todo_app_tasks.count({ where: { deleted_at: null } }),
      MyGlobal.prisma.todo_app_tasks.count({
        where: { is_completed: true, deleted_at: null },
      }),
      MyGlobal.prisma.todo_app_tasks.count({
        where: {
          is_completed: false,
          deleted_at: null,
          due_date: { gte: now, lte: dueSoonEnd },
        },
      }),
      MyGlobal.prisma.todo_app_user_activity_logs.findMany({
        where: {
          created_at: { gte: window30Days },
          todo_app_todouser_id: { not: null },
        },
        select: { todo_app_todouser_id: true },
      }),
      MyGlobal.prisma.todo_app_admin_actions.findMany({
        orderBy: { created_at: "desc" },
        take: 10,
        include: {
          admin: {
            select: {
              id: true,
              email: true,
              display_name: true,
              role: true,
              is_active: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
          affectedUser: {
            select: {
              id: true,
              display_name: true,
              is_verified: true,
              status: true,
              created_at: true,
              updated_at: true,
            },
          },
        },
      }),
      MyGlobal.prisma.todo_app_lists.findMany({
        where: { deleted_at: null },
        orderBy: { created_at: "desc" },
        take: 10,
        include: {
          owner: {
            select: {
              id: true,
              display_name: true,
              is_verified: true,
              status: true,
              created_at: true,
              updated_at: true,
            },
          },
        },
      }),
      MyGlobal.prisma.todo_app_invitations.findMany({
        where: { deleted_at: null },
        orderBy: { created_at: "desc" },
        take: 10,
      }),
      MyGlobal.prisma.todo_app_todouser.findMany({
        where: { deleted_at: null },
        orderBy: { created_at: "desc" },
        take: 10,
      }),
    ]);

    const activeUserIds = new Set<string>();
    for (const r of activityRows)
      if (r.todo_app_todouser_id) activeUserIds.add(r.todo_app_todouser_id);
    const activeUsers = activeUserIds.size;

    const totals: ITodoAppAdminTotals = {
      total_users: Number(totalUsers),
      active_users: Number(activeUsers),
      suspended_accounts: Number(suspendedAccounts),
      total_lists: Number(totalLists),
      public_lists: Number(publicLists),
      private_lists: Number(privateLists),
      pending_invitations: Number(pendingInvitations),
    };

    const taskStats: ITodoAppTaskStats = {
      total_tasks: Number(totalTasks),
      completed_tasks: Number(completedTasks),
      completion_rate:
        totalTasks === 0
          ? 0
          : Number(Number(completedTasks) / Number(totalTasks)),
      due_soon_count: Number(dueSoonCount),
    };

    const recentAdminActions: ITodoAppAdminActionSummary[] =
      recentAdminActionsRaw.map((a) => ({
        id: a.id,
        action: a.action,
        admin: a.admin
          ? {
              id: a.admin.id,
              email: a.admin.email,
              displayName: a.admin.display_name ?? null,
              role: a.admin.role as "moderator" | "support" | "superadmin",
              isActive: a.admin.is_active,
              createdAt: toISOStringSafe(a.admin.created_at),
              updatedAt: a.admin.updated_at
                ? toISOStringSafe(a.admin.updated_at)
                : null,
              deletedAt: a.admin.deleted_at
                ? toISOStringSafe(a.admin.deleted_at)
                : null,
            }
          : undefined,
        affectedUser: a.affectedUser
          ? {
              id: a.affectedUser.id,
              displayName: a.affectedUser.display_name ?? null,
              isVerified: a.affectedUser.is_verified,
              status: a.affectedUser.status ?? undefined,
              createdAt: toISOStringSafe(a.affectedUser.created_at),
              updatedAt: toISOStringSafe(a.affectedUser.updated_at),
            }
          : undefined,
        targetType: a.target_type ?? null,
        targetId: a.target_id ?? null,
        reason: a.reason ?? null,
        auditCaseId: a.audit_case_id ?? null,
        detailsSnippet: a.details
          ? a.details.length > 200
            ? a.details.slice(0, 200)
            : a.details
          : null,
        createdAt: toISOStringSafe(a.created_at),
        updatedAt: a.updated_at ? toISOStringSafe(a.updated_at) : null,
      }));

    const topLists: ITodoAppListSummary[] = topListsRaw.map((l) => ({
      id: l.id,
      title: l.title,
      description: l.description ?? null,
      visibility: l.visibility,
      owner: {
        id: l.owner.id,
        displayName: l.owner.display_name ?? null,
        isVerified: l.owner.is_verified,
        status: l.owner.status ?? undefined,
        createdAt: toISOStringSafe(l.owner.created_at),
        updatedAt: toISOStringSafe(l.owner.updated_at),
      },
      createdAt: toISOStringSafe(l.created_at),
      updatedAt: toISOStringSafe(l.updated_at),
      deletedAt: l.deleted_at ? toISOStringSafe(l.deleted_at) : null,
    }));

    // Build recentInvitations mapping using list lookup for summary when possible
    const listById = new Map<string, ITodoAppListSummary>();
    for (const t of topLists) listById.set(t.id, t);

    const recentInvitations: ITodoAppInvitationSummary[] =
      recentInvitationsRaw.map((inv) => ({
        id: inv.id,
        list:
          listById.get(inv.todo_app_list_id) ??
          ({
            id: inv.todo_app_list_id,
            title: "(list)",
            description: null,
            visibility: "private",
            owner: {
              id: "",
              displayName: null,
              isVerified: false,
              status: undefined,
              createdAt: now,
              updatedAt: now,
            },
            createdAt: now,
            updatedAt: now,
            deletedAt: null,
          } as ITodoAppListSummary),
        inviter: {
          id: inv.inviter_todouser_id ?? ("" as string & tags.Format<"uuid">),
          email: "redacted@local" as string & tags.Format<"email">,
          displayName: null,
          status: "",
          isVerified: false,
          createdAt: now,
          updatedAt: now,
        },
        state: inv.state,
        inviteCode: null,
        invitee: undefined,
        inviteeEmail: inv.invitee_email ?? null,
        expiresAt: toISOStringSafe(inv.expires_at),
        acceptedAt: inv.accepted_at ? toISOStringSafe(inv.accepted_at) : null,
        createdAt: toISOStringSafe(inv.created_at),
        updatedAt: toISOStringSafe(inv.updated_at),
      }));

    const users: ITodoAppUserSummary[] = usersSampleRaw.map((u) => ({
      id: u.id,
      email: u.email,
      displayName: u.display_name ?? null,
      status: u.status,
      isVerified: u.is_verified ?? undefined,
      createdAt: toISOStringSafe(u.created_at),
      updatedAt: toISOStringSafe(u.updated_at),
    }));

    // Audit the access (non-blocking but awaited to ensure record)
    await MyGlobal.prisma.todo_app_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_admin_id: admin.id,
        todo_app_admin_session_id: admin.session_id,
        event_type: "admin_dashboard_view",
        details: "Admin dashboard overview viewed",
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });

    const dashboard: ITodoAppAdminDashboard = {
      totals,
      taskStats,
      recentAdminActions: recentAdminActions.length
        ? recentAdminActions
        : undefined,
      topLists: topLists.length ? topLists : undefined,
      recentInvitations: recentInvitations.length
        ? recentInvitations
        : undefined,
      users: users.length ? users : undefined,
      generatedAt: now,
    };

    return dashboard;
  } catch (err) {
    // Preserve debugging info while returning generic error code
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUserDashboard } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserDashboard";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IUserDashboardCounts } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserDashboardCounts";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTaskSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskSummary";
import { ITodoAppInvitationSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppInvitationSummary";
import { ITodoAppListSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppListSummary";
import { ITodoAppUserSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSummary";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function getTodoAppTodoUserDashboardUserOverview(props: {
  todoUser: TodouserPayload;
}): Promise<ITodoAppUserDashboard> {
  const { todoUser } = props;

  try {
    const user = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
      where: { id: todoUser.id },
      select: {
        id: true,
        email: true,
        display_name: true,
        is_verified: true,
        status: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });

    if (user.deleted_at !== null) {
      throw new HttpException("Unauthorized", 401);
    }

    const now = toISOStringSafe(new Date());
    const next7 = toISOStringSafe(
      new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
    );
    const sevenDaysAgo = toISOStringSafe(
      new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
    );

    const [
      totalLists,
      sharedListsCount,
      totalTasks,
      dueSoonCount,
      recentCompletedCount,
    ] = await Promise.all([
      MyGlobal.prisma.todo_app_lists.count({
        where: { todo_app_todouser_id: todoUser.id, deleted_at: null },
      }),
      MyGlobal.prisma.todo_app_list_collaborators.count({
        where: {
          todo_app_todouser_id: todoUser.id,
          deleted_at: null,
          list: { deleted_at: null },
        },
      }),
      MyGlobal.prisma.todo_app_tasks.count({
        where: {
          list: { todo_app_todouser_id: todoUser.id, deleted_at: null },
          deleted_at: null,
        },
      }),
      MyGlobal.prisma.todo_app_tasks.count({
        where: {
          list: { todo_app_todouser_id: todoUser.id, deleted_at: null },
          deleted_at: null,
          is_completed: false,
          due_date: { gte: now, lte: next7 },
        },
      }),
      MyGlobal.prisma.todo_app_tasks.count({
        where: {
          list: { todo_app_todouser_id: todoUser.id, deleted_at: null },
          deleted_at: null,
          is_completed: true,
          completed_at: { gte: sevenDaysAgo },
        },
      }),
    ]);

    const [
      ownedListsRows,
      collaboratorRows,
      upcomingTasksRows,
      recentCompletedRows,
      invitationsRows,
    ] = await Promise.all([
      MyGlobal.prisma.todo_app_lists.findMany({
        where: { todo_app_todouser_id: todoUser.id, deleted_at: null },
        orderBy: { created_at: "desc" },
        take: 20,
        include: { owner: true },
      }),
      MyGlobal.prisma.todo_app_list_collaborators.findMany({
        where: {
          todo_app_todouser_id: todoUser.id,
          deleted_at: null,
          list: { deleted_at: null },
        },
        orderBy: { created_at: "desc" },
        take: 40,
        include: { list: { include: { owner: true } } },
      }),
      MyGlobal.prisma.todo_app_tasks.findMany({
        where: {
          list: { todo_app_todouser_id: todoUser.id, deleted_at: null },
          deleted_at: null,
          is_completed: false,
          due_date: { gte: now, lte: next7 },
        },
        orderBy: { due_date: "asc" },
        take: 20,
        include: { list: { include: { owner: true } } },
      }),
      MyGlobal.prisma.todo_app_tasks.findMany({
        where: {
          list: { todo_app_todouser_id: todoUser.id, deleted_at: null },
          deleted_at: null,
          is_completed: true,
          completed_at: { gte: sevenDaysAgo },
        },
        orderBy: { completed_at: "desc" },
        take: 20,
        include: { list: { include: { owner: true } } },
      }),
      MyGlobal.prisma.todo_app_invitations.findMany({
        where: {
          deleted_at: null,
          state: "pending",
          OR: [
            { invitee_todouser_id: todoUser.id },
            { invitee_email: user.email },
          ],
        },
        orderBy: { created_at: "desc" },
        take: 20,
        include: { list: true, inviter: true, invitee: true },
      }),
    ]);

    const mapOwnerToSummary = (ownerRecord: any) => ({
      id: ownerRecord.id,
      email: ownerRecord.email ?? null,
      displayName: ownerRecord.display_name ?? null,
      isVerified: ownerRecord.is_verified,
      status: ownerRecord.status ?? undefined,
      createdAt: toISOStringSafe(ownerRecord.created_at),
      updatedAt: toISOStringSafe(ownerRecord.updated_at),
    });

    const mapListToSummary = (listRecord: any) => ({
      id: listRecord.id,
      title: listRecord.title,
      visibility: listRecord.visibility,
      owner: mapOwnerToSummary(listRecord.owner),
      description: listRecord.description ?? null,
      createdAt: toISOStringSafe(listRecord.created_at),
      updatedAt: toISOStringSafe(listRecord.updated_at),
      deletedAt: listRecord.deleted_at
        ? toISOStringSafe(listRecord.deleted_at)
        : undefined,
    });

    const ownedLists = ownedListsRows.map(mapListToSummary);

    const sharedMap = new Map<string, any>();
    for (const coll of collaboratorRows) {
      const listRec = coll.list;
      if (!listRec || listRec.deleted_at !== null) continue;
      if (!sharedMap.has(listRec.id))
        sharedMap.set(listRec.id, mapListToSummary(listRec));
    }
    const sharedLists = Array.from(sharedMap.values()).slice(0, 20);

    const mapTaskToSummary = (task: any) => ({
      id: task.id,
      title: task.title,
      isCompleted: task.is_completed,
      completedAt: task.completed_at
        ? toISOStringSafe(task.completed_at)
        : null,
      dueDate: task.due_date ? toISOStringSafe(task.due_date) : null,
      priority: task.priority ?? null,
      createdAt: toISOStringSafe(task.created_at),
      updatedAt: toISOStringSafe(task.updated_at),
      list: mapListToSummary(task.list),
    });

    const upcomingDueTasks = upcomingTasksRows.map(mapTaskToSummary);
    const recentCompletedTasks = recentCompletedRows.map(mapTaskToSummary);

    const pendingInvitations = invitationsRows.map((inv: any) => {
      const listSummary = inv.list ? mapListToSummary(inv.list) : (null as any);
      const inviterSummary = inv.inviter
        ? mapOwnerToSummary(inv.inviter)
        : (null as any);
      const isOwner = inv.list && inv.list.todo_app_todouser_id === todoUser.id;
      const isInvitee = inv.invitee_todouser_id === todoUser.id;

      return {
        id: inv.id,
        list: listSummary,
        inviter: inviterSummary,
        state: inv.state,
        inviteCode: isOwner || isInvitee ? inv.invite_code : null,
        invitee: inv.invitee
          ? inv.invitee.id
            ? mapOwnerToSummary(inv.invitee)
            : null
          : null,
        inviteeEmail: inv.invitee_email ?? null,
        expiresAt: toISOStringSafe(inv.expires_at),
        acceptedAt: inv.accepted_at ? toISOStringSafe(inv.accepted_at) : null,
        createdAt: toISOStringSafe(inv.created_at),
        updatedAt: toISOStringSafe(inv.updated_at),
      };
    });

    const result: ITodoAppUserDashboard = {
      user: {
        id: user.id,
        displayName: user.display_name ?? null,
        isVerified: user.is_verified,
        status: user.status ?? undefined,
        createdAt: toISOStringSafe(user.created_at),
        updatedAt: toISOStringSafe(user.updated_at),
      },
      counts: {
        totalLists: Number(totalLists),
        sharedListsCount: Number(sharedListsCount),
        totalTasks: Number(totalTasks),
        dueSoonCount: Number(dueSoonCount),
        recentCompletedCount: Number(recentCompletedCount),
      },
      ownedLists: ownedLists,
      sharedLists: sharedLists,
      upcomingDueTasks: upcomingDueTasks,
      recentCompletedTasks: recentCompletedTasks,
      pendingInvitations: pendingInvitations,
      generatedAt: toISOStringSafe(new Date()),
    };

    return result;
  } catch (error: any) {
    if (error && error.code === "P2025") {
      throw new HttpException("Unauthorized", 401);
    }
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppTaskTag } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskTag";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function getTodoAppTodoUserListsListIdTasksTaskId(props: {
  todoUser: TodouserPayload;
  listId: string & tags.Format<"uuid">;
  taskId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTask> {
  const { todoUser, listId, taskId } = props;

  const list = await MyGlobal.prisma.todo_app_lists.findUnique({
    where: { id: listId },
    include: {
      owner: {
        select: {
          id: true,
          display_name: true,
          is_verified: true,
          status: true,
          created_at: true,
          updated_at: true,
        },
      },
    },
  });

  if (!list || list.deleted_at) throw new HttpException("Not Found", 404);

  if (list.visibility !== "public") {
    const isOwner = list.owner && list.owner.id === todoUser.id;
    if (!isOwner) {
      const membership =
        await MyGlobal.prisma.todo_app_list_collaborators.findFirst({
          where: {
            todo_app_list_id: listId,
            todo_app_todouser_id: todoUser.id,
            deleted_at: null,
            accepted_at: { not: null },
          },
        });
      if (!membership)
        throw new HttpException(
          "Unauthorized: Only owner or accepted collaborators can access this list",
          403,
        );
    }
  }

  const task = await MyGlobal.prisma.todo_app_tasks.findUnique({
    where: { id: taskId },
  });
  if (!task) throw new HttpException("Not Found", 404);
  if (task.todo_app_list_id !== listId)
    throw new HttpException("Not Found", 404);
  if (task.deleted_at) throw new HttpException("Not Found", 404);

  const relations = await MyGlobal.prisma.todo_app_task_tag_relations.findMany({
    where: { todo_app_task_id: taskId },
    include: { tag: true },
  });

  const tagsArray = relations.map((r) => ({
    id: r.tag.id,
    name: r.tag.name,
    createdAt: toISOStringSafe(r.tag.created_at),
    updatedAt: toISOStringSafe(r.tag.updated_at),
    deletedAt: r.tag.deleted_at ? toISOStringSafe(r.tag.deleted_at) : null,
  }));

  const owner = list.owner;
  const ownerSummary = {
    id: owner.id,
    displayName: owner.display_name ?? undefined,
    isVerified: owner.is_verified,
    status: owner.status ?? undefined,
    createdAt: toISOStringSafe(owner.created_at),
    updatedAt: toISOStringSafe(owner.updated_at),
  };

  const listSummary = {
    id: list.id,
    title: list.title,
    visibility: list.visibility,
    owner: ownerSummary,
    description: list.description ?? undefined,
    createdAt: toISOStringSafe(list.created_at),
    updatedAt: toISOStringSafe(list.updated_at),
    deletedAt: list.deleted_at ? toISOStringSafe(list.deleted_at) : undefined,
  };

  const result = {
    id: task.id,
    title: task.title,
    description: task.description ?? null,
    isCompleted: task.is_completed,
    completedAt: task.completed_at ? toISOStringSafe(task.completed_at) : null,
    dueDate: task.due_date ? toISOStringSafe(task.due_date) : null,
    // Ensure priority is narrowed/validated to the literal union expected by ITodoAppTask
    priority: typia.assert<"low" | "medium" | "high" | "urgent" | null>(
      task.priority ?? null,
    ),
    createdAt: toISOStringSafe(task.created_at),
    updatedAt: toISOStringSafe(task.updated_at),
    list: listSummary,
    tags: tagsArray.length ? tagsArray : undefined,
    deletedAt: task.deleted_at ? toISOStringSafe(task.deleted_at) : null,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTaskSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskSnapshot";
import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function getTodoAppTodoUserTasksTaskIdSnapshotsSnapshotId(props: {
  todoUser: TodouserPayload;
  taskId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTaskSnapshot> {
  const { todoUser, taskId, snapshotId } = props;

  try {
    const snapshot = await MyGlobal.prisma.todo_app_task_snapshots.findUnique({
      where: { id: snapshotId },
      include: {
        task: {
          include: {
            list: {
              include: {
                owner: true,
              },
            },
          },
        },
        user: true,
        userSession: {
          include: {
            todouser: true,
          },
        },
      },
    });

    if (!snapshot) {
      throw new HttpException("Not Found", 404);
    }

    if (snapshot.todo_app_task_id !== taskId) {
      throw new HttpException("Not Found", 404);
    }

    if (!snapshot.task || !snapshot.task.list) {
      throw new HttpException("Not Found", 404);
    }

    const list = snapshot.task.list;

    const listOwnerId =
      (list as any).todo_app_todouser_id ??
      (list.owner && (list.owner as any).id);
    if (listOwnerId !== todoUser.id) {
      throw new HttpException(
        "Unauthorized: Only the owning user can access this snapshot",
        403,
      );
    }

    const ownerRecord = list.owner!;
    const ownerSummary = {
      id: ownerRecord.id,
      displayName: ownerRecord.display_name ?? null,
      isVerified: ownerRecord.is_verified,
      status: ownerRecord.status ?? undefined,
      createdAt: toISOStringSafe(ownerRecord.created_at),
      updatedAt: toISOStringSafe(ownerRecord.updated_at),
    };

    const listSummary = {
      id: list.id,
      title: list.title,
      visibility: list.visibility,
      owner: ownerSummary,
      description: list.description ?? null,
      createdAt: toISOStringSafe(list.created_at),
      updatedAt: toISOStringSafe(list.updated_at),
      deletedAt: list.deleted_at ? toISOStringSafe(list.deleted_at) : undefined,
    };

    const taskRecord = snapshot.task;
    const taskSummary = {
      id: taskRecord.id,
      title: taskRecord.title,
      isCompleted: taskRecord.is_completed,
      dueDate: taskRecord.due_date
        ? toISOStringSafe(taskRecord.due_date)
        : null,
      createdAt: toISOStringSafe(taskRecord.created_at),
      updatedAt: toISOStringSafe(taskRecord.updated_at),
      list: listSummary,
    };

    // Authorized access (owner) confirmed above
    const userSummary = snapshot.user
      ? {
          id: snapshot.user.id,
          displayName: snapshot.user.display_name ?? null,
          isVerified: snapshot.user.is_verified,
          status: snapshot.user.status ?? undefined,
          createdAt: toISOStringSafe(snapshot.user.created_at),
          updatedAt: toISOStringSafe(snapshot.user.updated_at),
        }
      : undefined;

    const sessionSummary = snapshot.userSession
      ? (() => {
          const sess = snapshot.userSession!;

          // Build a guaranteed non-undefined user summary for sessionSummary.user
          const sessionUserSummary = sess.todouser
            ? {
                id: sess.todouser.id,
                displayName: sess.todouser.display_name ?? null,
                isVerified: sess.todouser.is_verified,
                status: sess.todouser.status ?? undefined,
                createdAt: toISOStringSafe(sess.todouser.created_at),
                updatedAt: toISOStringSafe(sess.todouser.updated_at),
              }
            : snapshot.user
              ? {
                  id: snapshot.user.id,
                  displayName: snapshot.user.display_name ?? null,
                  isVerified: snapshot.user.is_verified,
                  status: snapshot.user.status ?? undefined,
                  createdAt: toISOStringSafe(snapshot.user.created_at),
                  updatedAt: toISOStringSafe(snapshot.user.updated_at),
                }
              : ownerSummary; // fallback to list owner summary to ensure a concrete object

          return {
            id: sess.id,
            user: sessionUserSummary,
            ip: sess.ip,
            href: sess.href ?? undefined,
            referrer: sess.referrer ?? null,
            createdAt: toISOStringSafe(sess.created_at),
            expiredAt: sess.expired_at
              ? toISOStringSafe(sess.expired_at)
              : null,
          };
        })()
      : undefined;

    const result: ITodoAppTaskSnapshot = {
      id: snapshot.id,
      todo: taskSummary,
      user: userSummary ?? undefined,
      userSession: sessionSummary ?? undefined,
      title: snapshot.title,
      description: snapshot.description ?? null,
      isCompleted: snapshot.is_completed,
      completedAt: snapshot.completed_at
        ? toISOStringSafe(snapshot.completed_at)
        : null,
      dueDate: snapshot.due_date ? toISOStringSafe(snapshot.due_date) : null,
      originalCreatedAt: snapshot.original_created_at
        ? toISOStringSafe(snapshot.original_created_at)
        : null,
      snapshotCreatedAt: toISOStringSafe(snapshot.snapshot_created_at),
      version: snapshot.version,
    };

    return result;
  } catch (err) {
    if (err instanceof HttpException) throw err;
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppCollaborationPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppCollaborationPermission";
import { IPageITodoAppCollaborationPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppCollaborationPermission";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminCollaborationPermissions(props: {
  admin: AdminPayload;
  body: ITodoAppCollaborationPermission.IRequest;
}): Promise<IPageITodoAppCollaborationPermission.ISummary> {
  const { admin, body } = props;

  // Authorization check: ensure admin is active and not deleted
  const adminRecord = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
    select: { is_active: true, deleted_at: true },
  });

  if (
    !adminRecord ||
    !adminRecord.is_active ||
    adminRecord.deleted_at !== null
  ) {
    throw new HttpException("Unauthorized: admin account inactive", 403);
  }

  // Pagination defaults and limits
  const page = Number(body.page ?? 1);
  const pageSize = Number(body.pageSize ?? 25);

  if (page <= 0) throw new HttpException("Bad Request: page must be >= 1", 400);
  if (pageSize <= 0)
    throw new HttpException("Bad Request: pageSize must be >= 1", 400);
  if (pageSize > 200)
    throw new HttpException("Bad Request: pageSize must be <= 200", 400);

  const skip = (page - 1) * pageSize;
  const take = pageSize;

  // Determine orderBy inline (Prisma-compatible, no mode)
  const orderBy: Prisma.todo_app_collaboration_permissionsOrderByWithRelationInput =
    body.sortBy === "code"
      ? { code: (body.order === "desc" ? "desc" : "asc") as Prisma.SortOrder }
      : body.sortBy === "updatedAt"
        ? {
            updated_at: (body.order === "desc"
              ? "desc"
              : "asc") as Prisma.SortOrder,
          }
        : {
            created_at: (body.order === "desc"
              ? "desc"
              : "asc") as Prisma.SortOrder,
          };

  // Run queries in parallel; build where inline for both operations
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_collaboration_permissions.findMany({
      where: {
        ...(body.code !== undefined &&
          body.code !== null && { code: { contains: body.code } }),
        ...(body.isGrantable !== undefined &&
          body.isGrantable !== null && { is_grantable: body.isGrantable }),
        ...(body.description !== undefined &&
          body.description !== null && {
            description: { contains: body.description },
          }),
      },
      select: {
        id: true,
        code: true,
        description: true,
        is_grantable: true,
        created_at: true,
        updated_at: true,
      },
      orderBy,
      skip,
      take,
    }),
    MyGlobal.prisma.todo_app_collaboration_permissions.count({
      where: {
        ...(body.code !== undefined &&
          body.code !== null && { code: { contains: body.code } }),
        ...(body.isGrantable !== undefined &&
          body.isGrantable !== null && { is_grantable: body.isGrantable }),
        ...(body.description !== undefined &&
          body.description !== null && {
            description: { contains: body.description },
          }),
      },
    }),
  ]);

  const data = rows.map((r) => ({
    id: r.id as string & tags.Format<"uuid">,
    code: r.code,
    description: r.description ?? null,
    isGrantable: r.is_grantable,
    createdAt: toISOStringSafe(r.created_at),
    updatedAt: toISOStringSafe(r.updated_at),
  }));

  const pages = Math.ceil(total / pageSize);

  return {
    pagination: {
      current: Number(page),
      limit: Number(pageSize),
      records: total,
      pages: Number(pages),
    },
    data,
  } as IPageITodoAppCollaborationPermission.ISummary;
}

