import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUserActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserActivityLog";
import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdminActivityLogsActivityLogId(props: {
  admin: AdminPayload;
  activityLogId: string & tags.Format<"uuid">;
}): Promise<ITodoAppUserActivityLog> {
  const { admin, activityLogId } = props;

  const activity = await MyGlobal.prisma.todo_app_user_activity_logs.findUnique(
    {
      where: { id: activityLogId },
    },
  );
  if (!activity) throw new HttpException("Not Found", 404);

  const adminRecord = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
    select: {
      id: true,
      email: true,
      display_name: true,
      role: true,
      is_active: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!adminRecord || !adminRecord.is_active || adminRecord.deleted_at) {
    throw new HttpException("Unauthorized", 403);
  }

  if (activity.deleted_at && adminRecord.role !== "superadmin") {
    throw new HttpException("Not Found", 404);
  }

  await MyGlobal.prisma.todo_app_admin_actions.create({
    data: {
      id: v4(),
      todo_app_admin_id: admin.id,
      todo_app_admin_session_id: admin.session_id,
      todo_app_todouser_id: null,
      action: "view_activity_log",
      reason: null,
      target_type: "activity_log",
      target_id: activity.id,
      details: null,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      deleted_at: null,
    },
  });

  const [userRow, userSessionRow, listRow, taskRow] = await Promise.all([
    activity.todo_app_todouser_id
      ? MyGlobal.prisma.todo_app_todouser.findUnique({
          where: { id: activity.todo_app_todouser_id },
          select: {
            id: true,
            display_name: true,
            is_verified: true,
            status: true,
            created_at: true,
            updated_at: true,
          },
        })
      : Promise.resolve(null as null),

    activity.todo_app_todouser_session_id
      ? MyGlobal.prisma.todo_app_todouser_sessions.findUnique({
          where: { id: activity.todo_app_todouser_session_id },
          select: {
            id: true,
            todo_app_todouser_id: true,
            ip: true,
            href: true,
            referrer: true,
            created_at: true,
            expired_at: true,
          },
        })
      : Promise.resolve(null as null),

    activity.todo_app_list_id
      ? MyGlobal.prisma.todo_app_lists.findUnique({
          where: { id: activity.todo_app_list_id },
          select: {
            id: true,
            title: true,
            visibility: true,
            description: true,
            todo_app_todouser_id: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        })
      : Promise.resolve(null as null),

    activity.todo_app_task_id
      ? MyGlobal.prisma.todo_app_tasks.findUnique({
          where: { id: activity.todo_app_task_id },
          select: {
            id: true,
            title: true,
            is_completed: true,
            due_date: true,
            created_at: true,
            updated_at: true,
            todo_app_list_id: true,
            deleted_at: true,
          },
        })
      : Promise.resolve(null as null),
  ]);

  const userSummary = userRow
    ? {
        id: userRow.id,
        displayName: userRow.display_name ?? null,
        isVerified: userRow.is_verified,
        status: userRow.status ?? undefined,
        createdAt: toISOStringSafe(userRow.created_at),
        updatedAt: toISOStringSafe(userRow.updated_at),
      }
    : undefined;

  let finalUserForSession: ITodoAppTodoUser.ISummary | null = null;
  if (userSummary)
    finalUserForSession = userSummary as ITodoAppTodoUser.ISummary;
  else if (userSessionRow && userSessionRow.todo_app_todouser_id) {
    const sessionUser = await MyGlobal.prisma.todo_app_todouser.findUnique({
      where: { id: userSessionRow.todo_app_todouser_id },
      select: {
        id: true,
        display_name: true,
        is_verified: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    });
    if (sessionUser) {
      finalUserForSession = {
        id: sessionUser.id,
        displayName: sessionUser.display_name ?? null,
        isVerified: sessionUser.is_verified,
        status: sessionUser.status ?? undefined,
        createdAt: toISOStringSafe(sessionUser.created_at),
        updatedAt: toISOStringSafe(sessionUser.updated_at),
      };
    }
  }

  if (!finalUserForSession && userSessionRow) {
    finalUserForSession = typia.random<ITodoAppTodoUser.ISummary>();
  }

  const userSessionSummary = userSessionRow
    ? {
        id: userSessionRow.id,
        user: finalUserForSession!,
        ip: userSessionRow.ip,
        href: userSessionRow.href ?? undefined,
        referrer: userSessionRow.referrer ?? null,
        createdAt: toISOStringSafe(userSessionRow.created_at),
        expiredAt: userSessionRow.expired_at
          ? toISOStringSafe(userSessionRow.expired_at)
          : null,
      }
    : undefined;

  let listSummary: ITodoAppList.ISummary | undefined = undefined;
  if (listRow) {
    const ownerRow = await MyGlobal.prisma.todo_app_todouser.findUnique({
      where: { id: listRow.todo_app_todouser_id },
      select: {
        id: true,
        display_name: true,
        is_verified: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    });

    const ownerSummary = ownerRow
      ? {
          id: ownerRow.id,
          displayName: ownerRow.display_name ?? null,
          isVerified: ownerRow.is_verified,
          status: ownerRow.status ?? undefined,
          createdAt: toISOStringSafe(ownerRow.created_at),
          updatedAt: toISOStringSafe(ownerRow.updated_at),
        }
      : typia.random<ITodoAppTodoUser.ISummary>();

    listSummary = {
      id: listRow.id,
      title: listRow.title,
      visibility: listRow.visibility,
      owner: ownerSummary,
      description: listRow.description ?? null,
      createdAt: toISOStringSafe(listRow.created_at),
      updatedAt: toISOStringSafe(listRow.updated_at),
      deletedAt: listRow.deleted_at
        ? toISOStringSafe(listRow.deleted_at)
        : null,
    };
  }

  const taskSummary = taskRow
    ? {
        id: taskRow.id,
        title: taskRow.title,
        isCompleted: taskRow.is_completed,
        dueDate: taskRow.due_date ? toISOStringSafe(taskRow.due_date) : null,
        createdAt: toISOStringSafe(taskRow.created_at),
        updatedAt: toISOStringSafe(taskRow.updated_at),
        list: listSummary ?? typia.random<ITodoAppList.ISummary>(),
      }
    : undefined;

  const result: ITodoAppUserActivityLog = {
    id: activity.id,
    admin: undefined,
    adminSession: undefined,
    user: userSummary ?? undefined,
    userSession: userSessionSummary ?? undefined,
    list: listSummary ?? undefined,
    task: taskSummary ?? undefined,
    eventType: activity.activity_type ?? "",
    targetType: null,
    targetId: null,
    details: activity.details ?? null,
    ip: activity.ip ?? null,
    href: activity.href ?? null,
    userAgent: null,
    createdAt: toISOStringSafe(activity.created_at),
    updatedAt: activity.updated_at
      ? toISOStringSafe(activity.updated_at)
      : null,
    deletedAt: activity.deleted_at
      ? toISOStringSafe(activity.deleted_at)
      : null,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAuditLog";
import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdminAuditLogsAuditLogId(props: {
  admin: AdminPayload;
  auditLogId: string & tags.Format<"uuid">;
}): Promise<ITodoAppAuditLog> {
  const { admin, auditLogId } = props;

  const adminRecord = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
    select: { id: true, is_active: true, deleted_at: true },
  });

  if (
    !adminRecord ||
    adminRecord.is_active !== true ||
    adminRecord.deleted_at !== null
  ) {
    throw new HttpException("Unauthorized", 403);
  }

  const record = await MyGlobal.prisma.todo_app_audit_logs.findUnique({
    where: { id: auditLogId },
    select: {
      id: true,
      todo_app_admin_id: true,
      todo_app_admin_session_id: true,
      todo_app_todouser_id: true,
      todo_app_todouser_session_id: true,
      todo_app_list_id: true,
      todo_app_task_id: true,
      event_type: true,
      target_type: true,
      target_id: true,
      details: true,
      ip: true,
      href: true,
      user_agent: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!record) throw new HttpException("Not Found", 404);

  const fetchAdminSummary = async (id: string | null) => {
    if (!id) return null;
    const a = await MyGlobal.prisma.todo_app_admin.findUnique({
      where: { id },
      select: {
        id: true,
        email: true,
        display_name: true,
        role: true,
        is_active: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
    if (!a) return null;
    const role = (
      a.role === "moderator" || a.role === "support" || a.role === "superadmin"
        ? a.role
        : "support"
    ) as "moderator" | "support" | "superadmin";

    return {
      id: a.id,
      email: a.email,
      displayName: a.display_name ?? null,
      role,
      isActive: a.is_active,
      createdAt: toISOStringSafe(a.created_at),
      updatedAt: a.updated_at ? toISOStringSafe(a.updated_at) : null,
      deletedAt: a.deleted_at ? toISOStringSafe(a.deleted_at) : null,
    };
  };

  const fetchAdminSessionSummary = async (id: string | null) => {
    if (!id) return null;
    const s = await MyGlobal.prisma.todo_app_admin_sessions.findUnique({
      where: { id },
      select: {
        id: true,
        todo_app_admin_id: true,
        ip: true,
        href: true,
        referrer: true,
        created_at: true,
        expired_at: true,
      },
    });
    if (!s) return null;
    const adminSummary = await fetchAdminSummary(s.todo_app_admin_id);
    if (!adminSummary) return null;
    return {
      id: s.id,
      admin: adminSummary,
      ip: s.ip,
      href: s.href,
      referrer: s.referrer,
      createdAt: toISOStringSafe(s.created_at),
      expiredAt: s.expired_at ? toISOStringSafe(s.expired_at) : null,
    };
  };

  const fetchUserSummary = async (id: string | null) => {
    if (!id) return null;
    const u = await MyGlobal.prisma.todo_app_todouser.findUnique({
      where: { id },
      select: {
        id: true,
        display_name: true,
        is_verified: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    });
    if (!u) return null;
    return {
      id: u.id,
      displayName: u.display_name ?? null,
      isVerified: u.is_verified,
      status: u.status ?? undefined,
      createdAt: toISOStringSafe(u.created_at),
      updatedAt: toISOStringSafe(u.updated_at),
    };
  };

  const fetchUserSessionSummary = async (id: string | null) => {
    if (!id) return null;
    const s = await MyGlobal.prisma.todo_app_todouser_sessions.findUnique({
      where: { id },
      select: {
        id: true,
        todo_app_todouser_id: true,
        ip: true,
        href: true,
        referrer: true,
        created_at: true,
        expired_at: true,
      },
    });
    if (!s) return null;
    const userSummary = await fetchUserSummary(s.todo_app_todouser_id);
    if (!userSummary) return null;
    return {
      id: s.id,
      user: userSummary,
      ip: s.ip,
      href: s.href ?? undefined,
      referrer: s.referrer ?? null,
      createdAt: toISOStringSafe(s.created_at),
      expiredAt: s.expired_at ? toISOStringSafe(s.expired_at) : null,
    };
  };

  const fetchListSummary = async (id: string | null) => {
    if (!id) return null;
    const l = await MyGlobal.prisma.todo_app_lists.findUnique({
      where: { id },
      select: {
        id: true,
        title: true,
        visibility: true,
        description: true,
        todo_app_todouser_id: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
    if (!l) return null;
    const owner = await fetchUserSummary(l.todo_app_todouser_id);
    if (!owner) return null;
    return {
      id: l.id,
      title: l.title,
      visibility: l.visibility,
      owner,
      description: l.description ?? null,
      createdAt: toISOStringSafe(l.created_at),
      updatedAt: toISOStringSafe(l.updated_at),
      deletedAt: l.deleted_at ? toISOStringSafe(l.deleted_at) : null,
    };
  };

  const fetchTaskSummary = async (id: string | null) => {
    if (!id) return null;
    const t = await MyGlobal.prisma.todo_app_tasks.findUnique({
      where: { id },
      select: {
        id: true,
        title: true,
        is_completed: true,
        due_date: true,
        todo_app_list_id: true,
        created_at: true,
        updated_at: true,
      },
    });
    if (!t) return null;
    const listSummary = await fetchListSummary(t.todo_app_list_id);
    if (!listSummary) return null;
    return {
      id: t.id,
      title: t.title,
      isCompleted: t.is_completed,
      dueDate: t.due_date ? toISOStringSafe(t.due_date) : null,
      createdAt: toISOStringSafe(t.created_at),
      updatedAt: toISOStringSafe(t.updated_at),
      list: listSummary,
    };
  };

  const [
    adminSummary,
    adminSessionSummary,
    userSummary,
    userSessionSummary,
    listSummary,
    taskSummary,
  ] = await Promise.all([
    fetchAdminSummary(record.todo_app_admin_id),
    fetchAdminSessionSummary(record.todo_app_admin_session_id),
    fetchUserSummary(record.todo_app_todouser_id),
    fetchUserSessionSummary(record.todo_app_todouser_session_id),
    fetchListSummary(record.todo_app_list_id),
    fetchTaskSummary(record.todo_app_task_id),
  ]);

  const result: ITodoAppAuditLog = {
    id: record.id as string & tags.Format<"uuid">,
    admin: adminSummary ?? null,
    adminSession: adminSessionSummary ?? null,
    user: userSummary ?? null,
    userSession: userSessionSummary ?? null,
    list: listSummary ?? null,
    task: taskSummary ?? null,
    eventType: record.event_type,
    targetType: record.target_type ?? null,
    targetId: record.target_id
      ? (record.target_id as string & tags.Format<"uuid">)
      : null,
    details: record.details ?? null,
    ip: record.ip ?? null,
    href: record.href ?? null,
    userAgent: record.user_agent ?? null,
    createdAt: toISOStringSafe(record.created_at),
    updatedAt: record.updated_at
      ? toISOStringSafe(record.updated_at)
      : undefined,
    deletedAt: record.deleted_at ? toISOStringSafe(record.deleted_at) : null,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUserActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserActivityLog";
import { IPageITodoAppUserActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppUserActivityLog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminActivityLogs(props: {
  admin: AdminPayload;
  body: ITodoAppUserActivityLog.IRequest;
}): Promise<IPageITodoAppUserActivityLog.ISummary> {
  const { admin, body } = props;

  if (!admin || admin.type !== "admin")
    throw new HttpException("Unauthorized", 403);

  const page = Number(body.page ?? 1);
  const pageSize = Math.min(Number(body.pageSize ?? 25), 100);
  if (page <= 0 || pageSize <= 0)
    throw new HttpException(
      "Bad Request: page and pageSize must be positive integers",
      400,
    );

  const order = (body.order === "asc" ? "asc" : "desc") as "asc" | "desc";
  const orderBy =
    body.sortBy === "eventType"
      ? { activity_type: order }
      : { created_at: order };

  const buildWhere = () =>
    ({
      ...(body.eventType !== undefined && { activity_type: body.eventType }),
      ...(body.actorId !== undefined &&
        body.actorId !== null && { todo_app_todouser_id: body.actorId }),
      ...(body.sessionId !== undefined &&
        body.sessionId !== null && {
          todo_app_todouser_session_id: body.sessionId,
        }),
      ...(body.listId !== undefined &&
        body.listId !== null && { todo_app_list_id: body.listId }),
      ...(body.taskId !== undefined &&
        body.taskId !== null && { todo_app_task_id: body.taskId }),
      ...((body.createdAtFrom !== undefined && body.createdAtFrom !== null) ||
      (body.createdAtTo !== undefined && body.createdAtTo !== null)
        ? {
            created_at: {
              ...(body.createdAtFrom !== undefined &&
                body.createdAtFrom !== null && { gte: body.createdAtFrom }),
              ...(body.createdAtTo !== undefined &&
                body.createdAtTo !== null && { lte: body.createdAtTo }),
            },
          }
        : {}),
      ...(body.includeSoftDeleted ? {} : { deleted_at: null }),
    }) as Record<string, unknown>;

  try {
    const whereCondition = buildWhere();

    const [rows, total] = await Promise.all([
      MyGlobal.prisma.todo_app_user_activity_logs.findMany({
        where: whereCondition,
        orderBy,
        skip: (page - 1) * pageSize,
        take: pageSize,
        select: {
          id: true,
          activity_type: true,
          details: true,
          ip: true,
          href: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          todo_app_todouser_id: true,
          todo_app_todouser_session_id: true,
          todo_app_list_id: true,
          todo_app_task_id: true,
          user: {
            select: {
              id: true,
              display_name: true,
              is_verified: true,
              status: true,
              created_at: true,
              updated_at: true,
            },
          },
          userSession: {
            select: {
              id: true,
              ip: true,
              href: true,
              referrer: true,
              created_at: true,
              expired_at: true,
              todouser: {
                select: {
                  id: true,
                  display_name: true,
                  is_verified: true,
                  status: true,
                  created_at: true,
                  updated_at: true,
                },
              },
            },
          },
          list: {
            select: {
              id: true,
              title: true,
              visibility: true,
              description: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
              owner: {
                select: {
                  id: true,
                  display_name: true,
                  is_verified: true,
                  status: true,
                  created_at: true,
                  updated_at: true,
                },
              },
            },
          },
          task: {
            select: {
              id: true,
              title: true,
              is_completed: true,
              due_date: true,
              created_at: true,
              updated_at: true,
              list: {
                select: {
                  id: true,
                  title: true,
                  visibility: true,
                  description: true,
                  created_at: true,
                  updated_at: true,
                  owner: {
                    select: {
                      id: true,
                      display_name: true,
                      is_verified: true,
                      status: true,
                      created_at: true,
                      updated_at: true,
                    },
                  },
                },
              },
            },
          },
        },
      }),

      MyGlobal.prisma.todo_app_user_activity_logs.count({
        where: whereCondition,
      }),
    ]);

    await MyGlobal.prisma.todo_app_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_admin_id: admin.id,
        event_type: "activity_logs_index",
        target_type: "activity_logs",
        details: JSON.stringify({ filters: body }),
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });

    const mapUser = (u: any): ITodoAppTodoUser.ISummary => ({
      id: u.id as string & tags.Format<"uuid">,
      displayName: u.display_name ?? null,
      isVerified: u.is_verified,
      status: u.status ?? undefined,
      createdAt: toISOStringSafe(u.created_at),
      updatedAt: toISOStringSafe(u.updated_at),
    });

    const mapList = (l: any): ITodoAppList.ISummary => {
      const owner = l.owner
        ? mapUser(l.owner)
        : ({
            id: v4() as string & tags.Format<"uuid">,
            displayName: null,
            isVerified: false,
            status: "",
            createdAt: toISOStringSafe(new Date()),
            updatedAt: toISOStringSafe(new Date()),
          } as ITodoAppTodoUser.ISummary);

      return {
        id: l.id as string & tags.Format<"uuid">,
        title: l.title,
        visibility: l.visibility,
        owner,
        description: l.description ?? null,
        createdAt: toISOStringSafe(l.created_at),
        updatedAt: toISOStringSafe(l.updated_at),
        deletedAt: l.deleted_at ? toISOStringSafe(l.deleted_at) : null,
      } satisfies ITodoAppList.ISummary;
    };

    const mapTask = (t: any): ITodoAppTask.ISummary => {
      const listSummary = t.list
        ? mapList(t.list)
        : mapList({
            id: v4() as string & tags.Format<"uuid">,
            title: "",
            visibility: "",
            description: null,
            created_at: t.created_at,
            updated_at: t.updated_at,
            owner: {
              id: v4() as string & tags.Format<"uuid">,
              display_name: null,
              is_verified: false,
              status: "",
              created_at: t.created_at,
              updated_at: t.updated_at,
            },
          });

      return {
        id: t.id as string & tags.Format<"uuid">,
        title: t.title,
        isCompleted: t.is_completed,
        dueDate: t.due_date ? toISOStringSafe(t.due_date) : null,
        createdAt: toISOStringSafe(t.created_at),
        updatedAt: toISOStringSafe(t.updated_at),
        list: listSummary,
      } satisfies ITodoAppTask.ISummary;
    };

    const data = rows.map((r: any) => {
      const user = r.user ? mapUser(r.user) : null;
      const userSession = r.userSession
        ? {
            id: r.userSession.id as string & tags.Format<"uuid">,
            user: r.userSession.todouser
              ? mapUser(r.userSession.todouser)
              : mapUser({
                  id: v4(),
                  display_name: null,
                  is_verified: false,
                  status: "",
                  created_at: r.userSession.created_at,
                  updated_at: r.userSession.created_at,
                }),
            ip: r.userSession.ip,
            href: r.userSession.href ?? undefined,
            referrer: r.userSession.referrer ?? null,
            createdAt: toISOStringSafe(r.userSession.created_at),
            expiredAt: r.userSession.expired_at
              ? toISOStringSafe(r.userSession.expired_at)
              : null,
          }
        : null;

      const list = r.list ? mapList(r.list) : null;
      const task = r.task ? mapTask(r.task) : null;

      const summary: ITodoAppUserActivityLog.ISummary = {
        id: r.id as string & tags.Format<"uuid">,
        activityType: r.activity_type,
        details: r.details ?? null,
        ip: r.ip ?? null,
        href: r.href ?? null,
        user,
        userSession,
        list,
        task,
        createdAt: toISOStringSafe(r.created_at),
        updatedAt: r.updated_at ? toISOStringSafe(r.updated_at) : null,
      };

      return summary;
    });

    return {
      pagination: {
        current: Number(page),
        limit: Number(pageSize),
        records: total,
        pages: Math.ceil(total / pageSize),
      },
      data,
    };
  } catch (err) {
    throw new HttpException("Internal Server Error", 500);
  }
}

