    ...(body.isCompleted !== undefined &&
      body.isCompleted !== null && { is_completed: body.isCompleted }),
    ...(snapshotCreatedAtCondition && {
      snapshot_created_at: snapshotCreatedAtCondition,
    }),
  } as Record<string, unknown>;

  // Pagination
  const page = Number(body.page ?? 1);
  const rawLimit = Number(body.pageSize ?? 20);
  const limit = Math.max(
    1,
    Math.min(100, Number.isNaN(rawLimit) ? 20 : rawLimit),
  );
  const offset = Number(body.pageOffset ?? (page - 1) * limit);

  // Sorting - normalize sortOrder to literal 'asc'|'desc'
  const sortOrder: "asc" | "desc" = body.sortOrder === "asc" ? "asc" : "desc";
  const orderBy =
    body.sortBy === "version"
      ? { version: sortOrder }
      : { snapshot_created_at: sortOrder };

  // Fetch snapshots and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_task_snapshots.findMany({
      where: whereCondition,
      orderBy,
      skip: offset,
      take: limit,
      select: {
        id: true,
        version: true,
        snapshot_created_at: true,
        title: true,
        description: true,
        is_completed: true,
        completed_at: true,
        due_date: true,
        original_created_at: true,
        todo_app_todouser_id: true,
        todo_app_todouser_session_id: true,
      },
    }),
    MyGlobal.prisma.todo_app_task_snapshots.count({ where: whereCondition }),
  ]);

  // Batch fetch attributed users and sessions
  const userIds = Array.from(
    new Set(
      rows
        .map((r) => r.todo_app_todouser_id)
        .filter((id): id is string => id !== null && id !== undefined),
    ),
  );
  const sessionIds = Array.from(
    new Set(
      rows
        .map((r) => r.todo_app_todouser_session_id)
        .filter((id): id is string => id !== null && id !== undefined),
    ),
  );

  const [users, sessions] = await Promise.all([
    userIds.length
      ? MyGlobal.prisma.todo_app_todouser.findMany({
          where: { id: { in: userIds } },
          select: {
            id: true,
            display_name: true,
            is_verified: true,
            status: true,
            created_at: true,
            updated_at: true,
          },
        })
      : [],
    sessionIds.length
      ? MyGlobal.prisma.todo_app_todouser_sessions.findMany({
          where: { id: { in: sessionIds } },
          include: {
            todouser: {
              select: {
                id: true,
                display_name: true,
                is_verified: true,
                status: true,
                created_at: true,
                updated_at: true,
              },
            },
          },
        })
      : [],
  ]);

  const userMap = new Map<string, (typeof users)[number]>();
  for (const u of users) userMap.set(u.id, u);

  const sessionMap = new Map<string, (typeof sessions)[number]>();
  for (const s of sessions) sessionMap.set(s.id, s);

  // Build todo summary from current task/list context
  const list = task.list!;
  const owner = list.owner!;

  const todoSummary = {
    id: task.id,
    title: task.title,
    isCompleted: task.is_completed,
    dueDate: list && task.due_date ? toISOStringSafe(task.due_date) : null,
    createdAt: toISOStringSafe(task.created_at),
    updatedAt: toISOStringSafe(task.updated_at),
    list: {
      id: list.id,
      title: list.title,
      visibility: list.visibility,
      owner: {
        id: owner.id,
        displayName: owner.display_name ?? null,
        isVerified: owner.is_verified,
        status: owner.status ?? undefined,
        createdAt: toISOStringSafe(owner.created_at),
        updatedAt: toISOStringSafe(owner.updated_at),
      },
      description: list.description ?? null,
      createdAt: toISOStringSafe(list.created_at),
      updatedAt: toISOStringSafe(list.updated_at),
      deletedAt: list.deleted_at ? toISOStringSafe(list.deleted_at) : null,
    },
  } satisfies ITodoAppTask.ISummary;

  // Map rows to ISummary
  const data = rows.map((row) => {
    const userRecord = row.todo_app_todouser_id
      ? (userMap.get(row.todo_app_todouser_id) ?? null)
      : null;
    const sessionRecord = row.todo_app_todouser_session_id
      ? (sessionMap.get(row.todo_app_todouser_session_id) ?? null)
      : null;

    const userSummary = userRecord
      ? {
          id: userRecord.id,
          displayName: userRecord.display_name ?? null,
          isVerified: userRecord.is_verified,
          status: userRecord.status ?? undefined,
          createdAt: toISOStringSafe(userRecord.created_at),
          updatedAt: toISOStringSafe(userRecord.updated_at),
        }
      : null;

    const sessionSummary = sessionRecord
      ? (() => {
          // Build a non-nullable user object for session.user by preferring userSummary,
          // then falling back to sessionRecord.todouser, and finally using safe defaults.
          const todouser = (sessionRecord as any).todouser ?? null;

          const sessionUser =
            (userSummary as any) ??
            (todouser
              ? {
                  id: todouser.id,
                  displayName: todouser.display_name ?? null,
                  isVerified: todouser.is_verified,
                  status: todouser.status ?? undefined,
                  createdAt: toISOStringSafe(todouser.created_at),
                  updatedAt: toISOStringSafe(todouser.updated_at),
                }
              : {
                  id: (todouser && todouser.id) || "",
                  displayName: (todouser && todouser.display_name) ?? null,
                  isVerified: (todouser && todouser.is_verified) ?? false,
                  status: (todouser && todouser.status) ?? "",
                  createdAt: toISOStringSafe(
                    (todouser && todouser.created_at) ?? new Date(),
                  ),
                  updatedAt: toISOStringSafe(
                    (todouser && todouser.updated_at) ?? new Date(),
                  ),
                });

          return {
            id: sessionRecord.id,
            user: sessionUser,
            ip: sessionRecord.ip,
            href: sessionRecord.href ?? undefined,
            referrer: sessionRecord.referrer ?? null,
            createdAt: toISOStringSafe(sessionRecord.created_at),
            expiredAt: sessionRecord.expired_at
              ? toISOStringSafe(sessionRecord.expired_at)
              : null,
          };
        })()
      : null;

    return {
      id: row.id,
      version: row.version,
      snapshotCreatedAt: toISOStringSafe(row.snapshot_created_at),
      title: row.title,
      description: row.description ?? null,
      isCompleted: row.is_completed,
      completedAt: row.completed_at ? toISOStringSafe(row.completed_at) : null,
      dueDate: row.due_date ? toISOStringSafe(row.due_date) : null,
      originalCreatedAt: row.original_created_at
        ? toISOStringSafe(row.original_created_at)
        : null,
      todo: todoSummary,
      user: userSummary,
      userSession: sessionSummary,
    } as unknown as ITodoAppTaskSnapshot.ISummary;
  });

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    },
    data: data as unknown as ITodoAppTaskSnapshot.ISummary[],
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAuditLog";
import { IPageITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAuditLog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminAuditLogs(props: {
  admin: AdminPayload;
  body: ITodoAppAuditLog.IRequest;
}): Promise<IPageITodoAppAuditLog.ISummary> {
  const { admin, body } = props;

  // Authorization: ensure admin still active and not soft-deleted
  const adminRecord = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
    select: { id: true, is_active: true, deleted_at: true },
  });

  if (
    !adminRecord ||
    adminRecord.is_active !== true ||
    adminRecord.deleted_at !== null
  ) {
    throw new HttpException("Unauthorized: admin account is not active", 403);
  }

  // Pagination and bounds
  const currentPage = Number(body.page ?? 1);
  let limit = Number(body.limit ?? 20);
  if (!Number.isFinite(limit) || limit <= 0) limit = 20;
  const MAX_LIMIT = 100;
  if (limit > MAX_LIMIT) limit = MAX_LIMIT;
  const skip = (currentPage - 1) * limit;

  // Build where clause inline, respecting null vs undefined
  const where = {
    ...(body.eventType !== undefined &&
      body.eventType !== null && { event_type: body.eventType }),
    ...(body.targetType !== undefined &&
      body.targetType !== null && { target_type: body.targetType }),
    ...(body.userId !== undefined &&
      body.userId !== null && { todo_app_todouser_id: body.userId }),
    ...(body.adminId !== undefined &&
      body.adminId !== null && { todo_app_admin_id: body.adminId }),
    ...(body.listId !== undefined &&
      body.listId !== null && { todo_app_list_id: body.listId }),
    ...(body.taskId !== undefined &&
      body.taskId !== null && { todo_app_task_id: body.taskId }),
    ...(body.q !== undefined &&
      body.q !== null && { details: { contains: body.q } }),
    ...(body.includeDeleted !== true && { deleted_at: null }),
    ...((body.createdAfter !== undefined && body.createdAfter !== null) ||
    (body.createdBefore !== undefined && body.createdBefore !== null)
      ? {
          created_at: {
            ...(body.createdAfter !== undefined &&
              body.createdAfter !== null && { gte: body.createdAfter }),
            ...(body.createdBefore !== undefined &&
              body.createdBefore !== null && { lt: body.createdBefore }),
          },
        }
      : {}),
  };

  try {
    // Ensure direction is literal 'asc' | 'desc' so it matches Prisma SortOrder
    const direction = (body.order === "desc" ? "desc" : "asc") as
      | "asc"
      | "desc";

    const orderBy =
      body.sortBy === "eventType"
        ? { event_type: direction }
        : { created_at: direction };

    const [rows, total] = await Promise.all([
      MyGlobal.prisma.todo_app_audit_logs.findMany({
        where,
        orderBy,
        skip,
        take: limit,
        include: {
          user: {
            select: {
              id: true,
              display_name: true,
              is_verified: true,
              status: true,
              created_at: true,
              updated_at: true,
            },
          },
          admin: {
            select: {
              id: true,
              email: true,
              display_name: true,
              role: true,
              is_active: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
          list: {
            select: {
              id: true,
              title: true,
              visibility: true,
              todo_app_todouser_id: true,
              description: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
          task: {
            select: {
              id: true,
              title: true,
              is_completed: true,
              due_date: true,
              created_at: true,
              updated_at: true,
            },
          },
        },
      }),
      MyGlobal.prisma.todo_app_audit_logs.count({ where }),
    ]);

    const data = rows.map((r) => {
      const user = r.user
        ? {
            id: r.user.id,
            displayName:
              r.user.display_name === null ? null : r.user.display_name,
            isVerified: r.user.is_verified,
            status: r.user.status === null ? undefined : r.user.status,
            createdAt: toISOStringSafe(r.user.created_at),
            updatedAt: toISOStringSafe(r.user.updated_at),
          }
        : undefined;

      const adminSummary = r.admin
        ? {
            id: r.admin.id,
            email: r.admin.email,
            displayName:
              r.admin.display_name === null ? null : r.admin.display_name,
            // Normalize role to the expected literal union (safe single-property assertion)
            role: typia.assert<"moderator" | "support" | "superadmin">(
              r.admin.role,
            ),
            isActive: r.admin.is_active,
            createdAt: toISOStringSafe(r.admin.created_at),
            updatedAt: r.admin.updated_at
              ? toISOStringSafe(r.admin.updated_at)
              : null,
            deletedAt: r.admin.deleted_at
              ? toISOStringSafe(r.admin.deleted_at)
              : null,
          }
        : undefined;

      const list = r.list
        ? {
            id: r.list.id,
            title: r.list.title,
            visibility: r.list.visibility,
            owner: {
              id: r.list.todo_app_todouser_id,
              displayName: undefined,
              isVerified: false,
              status: undefined,
              createdAt: toISOStringSafe(r.list.created_at),
              updatedAt: toISOStringSafe(r.list.updated_at),
            },
            description:
              r.list.description === null ? null : r.list.description,
            createdAt: toISOStringSafe(r.list.created_at),
            updatedAt: toISOStringSafe(r.list.updated_at),
            deletedAt: r.list.deleted_at
              ? toISOStringSafe(r.list.deleted_at)
              : null,
          }
        : undefined;

      // Build task summary without a nested 'list' property because we don't have nested list data here.
      // Omit 'list' rather than assigning null to avoid incompatible null assignment.
      const task = r.task
        ? {
            id: r.task.id,
            title: r.task.title,
            isCompleted: r.task.is_completed,
            dueDate: r.task.due_date ? toISOStringSafe(r.task.due_date) : null,
            createdAt: toISOStringSafe(r.task.created_at),
            updatedAt: toISOStringSafe(r.task.updated_at),
          }
        : undefined;

      return {
        id: r.id,
        eventType: r.event_type,
        targetType: r.target_type === null ? null : r.target_type,
        targetId: r.target_id === null ? null : r.target_id,
        user,
        admin: adminSummary,
        list,
        task,
        createdAt: toISOStringSafe(r.created_at),
        updatedAt: r.updated_at ? toISOStringSafe(r.updated_at) : null,
        deletedAt: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
      };
    });

    const pages = Math.max(1, Math.ceil(Number(total) / limit));

    const result = {
      pagination: {
        current: Number(currentPage),
        limit: Number(limit),
        records: Number(total),
        pages: Number(pages),
      },
      data,
    };

    // Final cast: strip typia tag incompatibilities and satisfy the declared return type.
    return result as unknown as IPageITodoAppAuditLog.ISummary;
  } catch (err) {
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestJoin(): Promise<ITodoAppGuest.IAuthorized> {
  try {
    const now = toISOStringSafe(new Date());

    const guestId = v4() as string & tags.Format<"uuid">;
    const activityId = v4() as string & tags.Format<"uuid">;

    const [createdGuest, createdActivity] = await MyGlobal.prisma.$transaction([
      MyGlobal.prisma.todo_app_guest.create({
        data: {
          id: guestId,
          created_at: now,
          updated_at: now,
        },
      }),
      MyGlobal.prisma.todo_app_user_activity_logs.create({
        data: {
          id: activityId,
          todo_app_todouser_id: null,
          todo_app_todouser_session_id: null,
          todo_app_list_id: null,
          todo_app_task_id: null,
          activity_type: "guest_join",
          details: `Guest created: ${guestId}`,
          ip: null,
          href: null,
          created_at: now,
          updated_at: now,
        },
      }),
    ]);

    // Ephemeral session id for inclusion in tokens (not persisted)
    const sessionId = v4() as string & tags.Format<"uuid">;

    const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
    const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    const token = {
      access: jwt.sign(
        {
          type: "guest",
          id: createdGuest.id,
          session_id: sessionId,
          created_at: toISOStringSafe(new Date()),
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "1h", issuer: "autobe" },
      ),
      refresh: jwt.sign(
        {
          type: "guest",
          id: createdGuest.id,
          session_id: sessionId,
          tokenType: "refresh",
          created_at: toISOStringSafe(new Date()),
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "7d", issuer: "autobe" },
      ),
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    };

    return {
      id: createdGuest.id,
      anonymousLabel: createdGuest.anonymous_label ?? undefined,
      createdAt: toISOStringSafe(createdGuest.created_at),
      updatedAt: toISOStringSafe(createdGuest.updated_at),
      deletedAt: createdGuest.deleted_at
        ? toISOStringSafe(createdGuest.deleted_at)
        : null,
      token,
      guest: {
        id: createdGuest.id,
        anonymousLabel: createdGuest.anonymous_label ?? undefined,
        createdAt: toISOStringSafe(createdGuest.created_at),
        updatedAt: toISOStringSafe(createdGuest.updated_at),
        deletedAt: createdGuest.deleted_at
          ? toISOStringSafe(createdGuest.deleted_at)
          : null,
      },
    };
  } catch (err) {
    // Unexpected errors should be translated to HttpException for controller
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestRefresh(props: {
  body: ITodoAppGuest.IRefresh;
}): Promise<ITodoAppGuest.IAuthorized> {
  /**
   * SCHEMA-INTERFACE CONTRADICTION:
   *
   * - API requires validating and rotating refresh tokens for guest sessions.
   * - Prisma schema provides the `todo_app_guest` model but DOES NOT include any
   *   guest session table (e.g., `todo_app_guest_sessions`) nor persistent
   *   refresh token storage on the guest model.
   *
   * Because the necessary session persistence and revocation fields are missing
   * from the database schema, it is impossible to securely validate or revoke
   * refresh tokens using Prisma. Implementing token verification purely
   * in-memory or by guessing table names would be unsafe and would violate
   * schema-first constraints.
   *
   * RESOLUTION: Return a mocked authorized response using typia.random<T>().
   * This placeholder indicates the server-side authentication/session subsystem
   * must be extended (add guest session table or centralized session store)
   * before a production implementation can be written.
   */

  return typia.random<ITodoAppGuest.IAuthorized>();
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserJoin(props: {
  body: ITodoAppTodoUser.ICreate;
}): Promise<ITodoAppTodoUser.IAuthorized> {
  const { body } = props;

  // Duplicate email check
  const existing = await MyGlobal.prisma.todo_app_todouser.findFirst({
    where: { email: body.email },
  });
  if (existing) throw new HttpException("Email already registered", 409);

  // Hash the provided password
  const hashedPassword = await PasswordUtil.hash(body.password);

  // Prepare identifiers and timestamps
  const userId = v4() as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  try {
    const { createdUser, createdSession } = await MyGlobal.prisma.$transaction(
      async (tx) => {
        const createdUser = await tx.todo_app_todouser.create({
          data: {
            id: userId,
            email: body.email,
            password_hash: hashedPassword,
            display_name: body.displayName ?? null,
            is_verified: false,
            status: "pending_verification",
            failed_login_attempts: 0,
            mfa_enabled: false,
            created_at: now,
            updated_at: now,
            deleted_at: null,
          },
        });

        const createdSession = await tx.todo_app_todouser_sessions.create({
          data: {
            id: sessionId,
            todo_app_todouser_id: createdUser.id,
            ip: body.ip ?? "",
            href: body.href,
            referrer: body.referrer,
            created_at: now,
            expired_at: accessExpires,
          },
        });

        return { createdUser, createdSession };
      },
    );

    const accessToken = jwt.sign(
      {
        type: "todouser",
        id: createdUser.id,
        session_id: createdSession.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    );

    const refreshToken = jwt.sign(
      {
        type: "todouser",
        id: createdUser.id,
        session_id: createdSession.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    );

    const token = {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    } satisfies IAuthorizationToken;

    return {
      id: createdUser.id,
      email: createdUser.email,
      display_name: createdUser.display_name ?? null,
      is_verified: createdUser.is_verified,
      status: createdUser.status,
      mfa_enabled: createdUser.mfa_enabled,
      createdAt: toISOStringSafe(createdUser.created_at),
      updatedAt: toISOStringSafe(createdUser.updated_at),
      deletedAt: createdUser.deleted_at
        ? toISOStringSafe(createdUser.deleted_at)
        : null,
      token,
    } satisfies ITodoAppTodoUser.IAuthorized;
  } catch (error) {
    if (error instanceof HttpException) throw error;
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserLogin(props: {
  body: ITodoAppTodoUser.ILogin;
}): Promise<ITodoAppTodoUser.IAuthorized> {
  const { body } = props;

  // 1) Find user by email
  const user = await MyGlobal.prisma.todo_app_todouser.findFirst({
    where: { email: body.email },
  });
  if (!user) {
    // Do not reveal which part failed
    throw new HttpException("Invalid credentials", 401);
  }

  // 2) Lockout policy: 5 failed attempts within 15 minutes
  if (
    user.failed_login_attempts >= 5 &&
    user.last_failed_login_at &&
    Date.now() - user.last_failed_login_at.getTime() < 15 * 60 * 1000
  ) {
    throw new HttpException(
      "Account temporarily locked due to multiple failed login attempts",
      403,
    );
  }

  // 3) Account status checks
  if (user.status === "suspended") {
    throw new HttpException("Account is suspended", 403);
  }
  if (!user.is_verified) {
    throw new HttpException("Please verify your email first", 403);
  }

  // 4) Password verification
  const isValid = await PasswordUtil.verify(body.password, user.password_hash);
  if (!isValid) {
    await MyGlobal.prisma.todo_app_todouser.update({
      where: { id: user.id },
      data: {
        failed_login_attempts: user.failed_login_attempts + 1,
        last_failed_login_at: toISOStringSafe(new Date()),
      },
    });

    throw new HttpException("Invalid credentials", 401);
  }

  // 5) MFA handling: cannot verify here because ILogin has no MFA token field
  //    – require client to perform MFA step if account has MFA enabled
  if (user.mfa_enabled) {
    throw new HttpException("Multi-factor authentication required", 401);
  }

  // 6) Reset failed attempts after successful authentication
  await MyGlobal.prisma.todo_app_todouser.update({
    where: { id: user.id },
    data: {
      failed_login_attempts: 0,
      last_failed_login_at: null,
    },
  });

  // 7) Create session and tokens
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const session = await MyGlobal.prisma.todo_app_todouser_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_todouser_id: user.id,
      ip: body.ip ?? "",
      href: body.href,
      referrer: body.referrer,
      created_at: toISOStringSafe(new Date()),
      expired_at: accessExpires,
    },
  });

  const access = jwt.sign(
    {
      type: "todouser",
      id: user.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: "todouser",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // 8) Build and return response mapping null/undefined correctly
  return {
    id: user.id,
    email: user.email,
    display_name: user.display_name ?? null,
    is_verified: user.is_verified,
    status: user.status,
    mfa_enabled: user.mfa_enabled,
    createdAt: toISOStringSafe(user.created_at),
    updatedAt: toISOStringSafe(user.updated_at),
    deletedAt: user.deleted_at ? toISOStringSafe(user.deleted_at) : null,
    token: {
      access,
      refresh,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
    user: {
      id: user.id,
      displayName: user.display_name ?? null,
      isVerified: user.is_verified,
      status: user.status,
      createdAt: toISOStringSafe(user.created_at),
      updatedAt: toISOStringSafe(user.updated_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserRefresh(props: {
  body: ITodoAppTodoUser.IRefresh;
}): Promise<ITodoAppTodoUser.IAuthorized> {
  const { body } = props;
  const { refresh_token } = body;

  // 1) Verify and decode the refresh token
  let decoded: {
    id: string;
    session_id?: string;
    type: string;
    created_at?: string;
  };
  try {
    decoded = jwt.verify(refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as unknown as {
      id: string;
      session_id?: string;
      type: string;
      created_at?: string;
    };
  } catch (e) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // 2) Validate token actor type
  if (decoded.type !== "todouser") {
    throw new HttpException("Invalid token type", 403);
  }

  // 3) Load the user record
  const user = await MyGlobal.prisma.todo_app_todouser.findUnique({
    where: { id: decoded.id },
  });
  if (!user) {
    throw new HttpException("User not found", 404);
  }
  if (user.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  if (user.status !== "active") {
    throw new HttpException("Account not active", 403);
  }

  // 4) Verify token issuance time against refresh_tokens_revoked_at
  if (user.refresh_tokens_revoked_at) {
    const revokedMs = user.refresh_tokens_revoked_at.getTime();
    const issuedMs = decoded.created_at ? Date.parse(decoded.created_at) : NaN;
    if (isNaN(issuedMs) || issuedMs < revokedMs) {
      throw new HttpException("Refresh token revoked", 401);
    }
  }

  // 5) Generate new tokens (reuse session_id when present)
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: now.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: now.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // 6) Build and return the authorized DTO
  return {
    id: user.id,
    email: user.email,
    display_name: user.display_name ?? null,
    is_verified: user.is_verified,
    status: user.status,
    mfa_enabled: user.mfa_enabled,
    createdAt: toISOStringSafe(user.created_at),
    updatedAt: toISOStringSafe(user.updated_at),
    deletedAt: user.deleted_at ? toISOStringSafe(user.deleted_at) : null,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
    user: {
      id: user.id,
      displayName: user.display_name ?? null,
      isVerified: user.is_verified,
      status: user.status,
      createdAt: toISOStringSafe(user.created_at),
      updatedAt: toISOStringSafe(user.updated_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function postAuthTodoUserPasswordRequest(props: {
  body: ITodoAppTodoUser.IPasswordResetRequest;
}): Promise<ITodoAppTodoUser.ISummary> {
  const { body } = props;
  const { email } = body;

  const user = await MyGlobal.prisma.todo_app_todouser.findUnique({
    where: { email },
  });

  if (!user) {
    // Security: avoid account enumeration by returning a random summary when email is not found
    return typia.random<ITodoAppTodoUser.ISummary>();
  }

  const token = v4() as string & tags.Format<"uuid">;
  const expiresAt = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));

  await MyGlobal.prisma.todo_app_todouser.update({
    where: { id: user.id },
    data: {
      password_reset_token: token,
      password_reset_expires_at: expiresAt,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Best-effort email notification (do not fail the operation on email errors)
  try {
    if (
      (MyGlobal as any).mailer &&
      typeof (MyGlobal as any).mailer.send === "function"
    ) {
      await (MyGlobal as any).mailer.send({
        to: user.email,
        subject: "Password reset instructions",
        body:
          `To reset your password, visit the following link:

` + `https://example.com/auth/todoUser/password/reset?token=${token}`,
      });
    }
  } catch {
    // swallow
  }

  const updated = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
    where: { id: user.id },
    select: {
      id: true,
      display_name: true,
      is_verified: true,
      status: true,
      created_at: true,
      updated_at: true,
    },
  });

  return {
    id: updated.id as string & tags.Format<"uuid">,
    displayName: updated.display_name ?? null,
    isVerified: updated.is_verified,
    status: updated.status ?? undefined,
    createdAt: toISOStringSafe(updated.created_at),
    updatedAt: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

export async function postAuthTodoUserPasswordReset(props: {
  body: ITodoAppTodoUser.IResetPassword;
}): Promise<ITodoAppTodoUser.ISummary> {
  const { body } = props;

  // Locate user by one-time token
  const user = await MyGlobal.prisma.todo_app_todouser.findFirst({
    where: { password_reset_token: body.token },
  });

  if (!user)
    throw new HttpException("Invalid or expired password reset token", 400);

  // Validate expiry (business logic)
  if (
    !user.password_reset_expires_at ||
    user.password_reset_expires_at.getTime() < Date.now()
  ) {
    throw new HttpException("Invalid or expired password reset token", 400);
  }

  // Hash new password
  const newHashed = await PasswordUtil.hash(body.password);

  // Prepare ISO timestamps
  const revokedAt = toISOStringSafe(new Date());
  const updatedAt = revokedAt;

  // Atomically consume the token and update credentials
  const updateResult = await MyGlobal.prisma.todo_app_todouser.updateMany({
    where: { id: user.id, password_reset_token: body.token },
    data: {
      password_hash: newHashed,
      password_reset_token: null,
      password_reset_expires_at: null,
      refresh_tokens_revoked_at: revokedAt,
      updated_at: updatedAt,
    },
  });

  if (updateResult.count === 0) {
    throw new HttpException(
      "Invalid or already used password reset token",
      400,
    );
  }

  // Read updated record for response
  const updated = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
    where: { id: user.id },
  });

  return {
    id: updated.id as string & tags.Format<"uuid">,
    displayName: updated.display_name ?? null,
    isVerified: updated.is_verified,
    status: updated.status ?? undefined,
    createdAt: toISOStringSafe(updated.created_at),
    updatedAt: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function putAuthTodoUserPassword(props: {
  todoUser: TodouserPayload;
  body: ITodoAppTodoUser.IChangePassword;
}): Promise<ITodoAppTodoUser.ISummary> {
  const { todoUser, body } = props;
  const { currentPassword, newPassword } = body;

  // Load the current user (ensures actor owns the account via todoUser.id)
  const user = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
    where: { id: todoUser.id },
  });

  // Verify provided current password matches stored hash
  const verified = await PasswordUtil.verify(
    currentPassword,
    user.password_hash,
  );
  if (!verified) throw new HttpException("Current password is incorrect", 403);

  // Prepare new hash and a single timestamp value
  const newHashed = await PasswordUtil.hash(newPassword);
  const now = toISOStringSafe(new Date());

  // Update credentials and revoke prior refresh tokens
  const updated = await MyGlobal.prisma.todo_app_todouser.update({
    where: { id: todoUser.id },
    data: {
      password_hash: newHashed,
      refresh_tokens_revoked_at: now,
      updated_at: now,
    },
  });

  // Record a user activity log for auditing
  await MyGlobal.prisma.todo_app_user_activity_logs.create({
    data: {
      id: v4(),
      todo_app_todouser_id: todoUser.id,
      todo_app_todouser_session_id: todoUser.session_id,
      activity_type: "change_password",
      details: "User changed password",
      created_at: now,
      updated_at: now,
    },
  });

  // Map Prisma result to API DTO, converting Date -> ISO strings
  return {
    id: updated.id,
    displayName: updated.display_name ?? null,
    isVerified: updated.is_verified,
    status: updated.status,
    createdAt: toISOStringSafe(updated.created_at),
    updatedAt: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function postAuthTodoUserMfaEnable(props: {
  todoUser: TodouserPayload;
  body: ITodoAppTodoUser.IEnableMfa;
}): Promise<ITodoAppTodoUser.ISummary> {
  const { todoUser, body } = props;

  // Fetch and validate ownership
  const user = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
    where: { id: todoUser.id },
  });

  // Provisioning material generation
  const rawSecret = v4().replace(/-/g, "").slice(0, 32).toUpperCase();
  const otpauthUrl = `otpauth://totp/TodoApp:${user.email}?secret=${rawSecret}&issuer=TodoApp&algorithm=SHA1&digits=6&period=30`;
  const backupCodes = Array.from({ length: 8 }).map(() =>
    v4().replace(/-/g, "").slice(0, 8).toUpperCase(),
  );

  try {
    // Encrypt sensitive artifacts for storage
    const encryptedSecret = await PasswordUtil.hash(rawSecret);
    const encryptedBackupCodes = await PasswordUtil.hash(
      JSON.stringify(backupCodes),
    );

    const enableNow = body.requireVerification === false;
    const now = toISOStringSafe(new Date());

    // Persist encrypted data inline
    await MyGlobal.prisma.todo_app_todouser.update({
      where: { id: todoUser.id },
      data: {
        mfa_secret: encryptedSecret,
        mfa_backup_codes: encryptedBackupCodes,
        mfa_enabled: enableNow,
        updated_at: now,
      },
    });

    // Record an activity log for provisioning (no secret stored in log)
    await MyGlobal.prisma.todo_app_user_activity_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_todouser_id: todoUser.id,
        activity_type: "mfa.provisioned",
        details: `MFA provisioning initiated${enableNow ? " and enabled" : " (verification required)"}`,
        created_at: now,
        updated_at: now,
      },
    });

    // Return sanitized summary
    const updated = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
      where: { id: todoUser.id },
      select: {
        id: true,
        display_name: true,
        is_verified: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    });

    return {
      id: updated.id as string & tags.Format<"uuid">,
      displayName: updated.display_name ?? null,
      isVerified: updated.is_verified,
      status: updated.status ?? undefined,
      createdAt: toISOStringSafe(updated.created_at),
      updatedAt: toISOStringSafe(updated.updated_at),
    };
  } catch (err) {
    throw new HttpException(
      (err && (err as Error).message) || "Internal Server Error",
      500,
    );
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function postAuthTodoUserMfaDisable(props: {
  todoUser: TodouserPayload;
  body: ITodoAppTodoUser.IDisableMfa;
}): Promise<ITodoAppTodoUser.ISummary> {
  const { todoUser, body } = props;

  // Retrieve actor record
  const user = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
    where: { id: todoUser.id },
  });

  // If account is removed, respond 404 to avoid leaking existence
  if (user.deleted_at !== null) {
    throw new HttpException("Not Found", 404);
  }

  // Step-up verification: current password must match
  const passwordValid = await PasswordUtil.verify(
    body.current_password,
    user.password_hash,
  );
  if (!passwordValid) {
    throw new HttpException("Unauthorized: invalid password", 403);
  }

  // Prepare a single timestamp value for both update and audit
  const now = toISOStringSafe(new Date());

  // Disable MFA and clear persisted secrets
  const updated = await MyGlobal.prisma.todo_app_todouser.update({
    where: { id: todoUser.id },
    data: {
      mfa_enabled: false,
      mfa_secret: null,
      mfa_backup_codes: null,
      updated_at: now,
    },
  });

  // Record audit log for compliance (associate session when available)
  await MyGlobal.prisma.todo_app_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_todouser_id: todoUser.id,
      todo_app_todouser_session_id: todoUser.session_id,
      event_type: "mfa_disabled",
      details: body.sessionHandle ?? null,
      created_at: now,
      updated_at: now,
    },
  });

  // Return sanitized summary; sensitive fields omitted
  return {
    id: updated.id as string & tags.Format<"uuid">,
    displayName: updated.display_name ?? null,
    isVerified: updated.is_verified,
    status: updated.status ?? undefined,
    createdAt: toISOStringSafe(updated.created_at),
    updatedAt: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function postAuthTodoUserRevoke(props: {
  todoUser: TodouserPayload;
}): Promise<ITodoAppTodoUser.ISummary> {
  const { todoUser } = props;

  // Verify the authenticated user exists and is active
  const found = await MyGlobal.prisma.todo_app_todouser.findUnique({
    where: { id: todoUser.id },
  });

  if (!found) {
    throw new HttpException("Not Found", 404);
  }

  if (found.deleted_at !== null || found.status !== "active") {
    throw new HttpException("Unauthorized: inactive account", 403);
  }

  // Prepare timestamp (ISO string) for DB writes and responses
  const now = toISOStringSafe(new Date());

  try {
    const updated = await MyGlobal.prisma.$transaction(async (prisma) => {
      const updatedUser = await prisma.todo_app_todouser.update({
        where: { id: todoUser.id },
        data: {
          refresh_tokens_revoked_at: now,
          updated_at: now,
        },
        select: {
          id: true,
          display_name: true,
          is_verified: true,
          status: true,
          created_at: true,
          updated_at: true,
        },
      });

      await prisma.todo_app_user_activity_logs.create({
        data: {
          id: v4(),
          todo_app_todouser_id: todoUser.id,
          activity_type: "revoke_refresh_tokens",
          details: null,
          ip: null,
          href: null,
          created_at: now,
          updated_at: now,
        },
      });

      return updatedUser;
    });

    return {
      id: updated.id,
      displayName: updated.display_name ?? null,
      isVerified: updated.is_verified,
      status: updated.status,
      createdAt: toISOStringSafe(updated.created_at),
      updatedAt: toISOStringSafe(updated.updated_at),
    };
  } catch (err) {
    // Unexpected errors are surfaced as 500 for the client
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminJoin(props: {
  body: ITodoAppAdmin.ICreate;
}): Promise<ITodoAppAdmin.IAuthorized> {
  const { body } = props;

  // Check uniqueness
  const existing = await MyGlobal.prisma.todo_app_admin.findFirst({
    where: { email: body.email },
  });
  if (existing) throw new HttpException("Email already registered", 409);

  // Prepare timestamps and ids
  const now = toISOStringSafe(new Date());
  const adminId = v4() as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;

  // Hash password
  const hashedPassword = await PasswordUtil.hash(body.password);

  // Ensure role (Prisma requires role)
  const role = body.role ?? "support";

  // Create admin and session inside try/catch to handle unique-constraint race
  try {
    const admin = await MyGlobal.prisma.todo_app_admin.create({
      data: {
        id: adminId,
        email: body.email,
        password_hash: hashedPassword,
        display_name: body.display_name ?? null,
        role,
        is_active: true,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });

    const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
    const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    const session = await MyGlobal.prisma.todo_app_admin_sessions.create({
      data: {
        id: sessionId,
        todo_app_admin_id: admin.id,
        ip: body.ip ?? "",
        href: body.href,
        referrer: body.referrer,
        created_at: now,
        expired_at: toISOStringSafe(accessExpires),
      },
    });

    const tokenCreatedAt = now; // reuse same creation timestamp

    const accessToken = jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: tokenCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    );

    const refreshToken = jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: tokenCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    );

    const token: IAuthorizationToken = {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    };

    return {
      id: admin.id,
      email: admin.email,
      display_name: admin.display_name ?? undefined,
      role: admin.role,
      is_active: admin.is_active,
      createdAt: now,
      updatedAt: now,
      deletedAt: admin.deleted_at ? toISOStringSafe(admin.deleted_at) : null,
      token,
    } satisfies ITodoAppAdmin.IAuthorized;
  } catch (e: unknown) {
    // Translate Prisma unique violation to 409
    if (
      e instanceof Prisma.PrismaClientKnownRequestError &&
      (e.code === "P2002" || e.code === "P2002")
    ) {
      throw new HttpException("Email already registered", 409);
    }
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminLogin(props: {
  body: ITodoAppAdmin.ILogin;
}): Promise<ITodoAppAdmin.IAuthorized> {
  const { body } = props;

  // 1) Locate admin by email
  const admin = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { email: body.email },
  });

  if (!admin) {
    // Audit failed attempt without revealing existence
    await MyGlobal.prisma.todo_app_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        event_type: "login_failure",
        details: `Failed admin login attempt for email: ${body.email}`,
        ip: body.ip ?? null,
        href: body.href,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });

    throw new HttpException("Invalid email or password", 401);
  }

  // 2) Enforce account status
  if (!admin.is_active || admin.deleted_at !== null) {
    await MyGlobal.prisma.todo_app_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_admin_id: admin.id,
        event_type: "login_failure",
        details: `Inactive or removed admin attempted login: ${body.email}`,
        ip: body.ip ?? null,
        href: body.href,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });

    throw new HttpException("Invalid email or password", 401);
  }

  // 3) Verify password
  const isValidPassword = await PasswordUtil.verify(
    body.password,
    admin.password_hash,
  );
  if (!isValidPassword) {
    await MyGlobal.prisma.todo_app_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_admin_id: admin.id,
        event_type: "login_failure",
        details: `Invalid password attempt for admin: ${body.email}`,
        ip: body.ip ?? null,
        href: body.href,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });

    throw new HttpException("Invalid email or password", 401);
  }

  // 4) Create session and tokens
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session = await MyGlobal.prisma.todo_app_admin_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_admin_id: admin.id,
      ip: body.ip ?? "",
      href: body.href,
      referrer: body.referrer,
      created_at: toISOStringSafe(new Date()),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // 5) Audit successful login
  await MyGlobal.prisma.todo_app_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_admin_id: admin.id,
      todo_app_admin_session_id: session.id,
      event_type: "login_success",
      details: "Admin login successful",
      ip: body.ip ?? null,
      href: body.href,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 6) Build and return authorized response
  return {
    id: admin.id,
    email: admin.email,
    display_name: admin.display_name ?? null,
    role: admin.role,
    is_active: admin.is_active,
    createdAt: toISOStringSafe(admin.created_at),
    updatedAt: toISOStringSafe(admin.updated_at),
    deletedAt: admin.deleted_at ? toISOStringSafe(admin.deleted_at) : null,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postAuthAdminRefresh(props: {
  admin: AdminPayload;
  body: ITodoAppAdmin.IRefresh;
}): Promise<ITodoAppAdmin.IAuthorized> {
  const { admin, body } = props;

  // Verify and decode refresh token
  let decoded: { id: string; session_id: string; type: string };
  try {
    decoded = jwt.verify(body.refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as { id: string; session_id: string; type: string };
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "admin") {
    throw new HttpException("Invalid token type", 403);
  }

  // Validate session and admin state
  const session = await MyGlobal.prisma.todo_app_admin_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_admin_id: decoded.id,
    },
    include: { admin: true },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  const targetAdmin = session.admin;
  if (!targetAdmin) throw new HttpException("Admin account not found", 401);
  if (!targetAdmin.is_active)
    throw new HttpException("Account is not active", 403);
  if (targetAdmin.deleted_at !== null)
    throw new HttpException("Account has been deleted", 403);

  // Generate tokens and timestamps
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const nowIso = toISOStringSafe(new Date());

  const access = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  const accessExpiredAt = toISOStringSafe(accessExpires);
  const refreshableUntil = toISOStringSafe(refreshExpires);

  // Update session expiration time
  await MyGlobal.prisma.todo_app_admin_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshableUntil },
  });

  // Record audit log for token refresh
  await MyGlobal.prisma.todo_app_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_admin_id: decoded.id,
      todo_app_admin_session_id: decoded.session_id,
      event_type: "refresh_token",
      details: "Admin refresh token exchange",
      created_at: nowIso,
      updated_at: nowIso,
    },
  });

  // Return authorized admin payload
  return {
    id: targetAdmin.id as string & tags.Format<"uuid">,
    email: targetAdmin.email as string & tags.Format<"email">,
    display_name: targetAdmin.display_name ?? null,
    role: targetAdmin.role,
    is_active: targetAdmin.is_active,
    createdAt: toISOStringSafe(targetAdmin.created_at),
    updatedAt: toISOStringSafe(targetAdmin.updated_at),
    deletedAt: targetAdmin.deleted_at
      ? toISOStringSafe(targetAdmin.deleted_at)
      : null,
    token: {
      access,
      refresh,
      expired_at: accessExpiredAt,
      refreshable_until: refreshableUntil,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
