import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function putTodoAppTodoUserTodoUsersTodoUserId(props: {
  todoUser: TodouserPayload;
  todoUserId: string & tags.Format<"uuid">;
  body: ITodoAppTodoUser.IUpdate;
}): Promise<ITodoAppTodoUser> {
  const { todoUser, todoUserId, body } = props;

  // Authorization: only the owner may update their profile
  if (todoUser.id !== todoUserId) {
    throw new HttpException(
      "Unauthorized: You can only update your own profile",
      403,
    );
  }

  // Ensure the target exists and is not soft-deleted
  const existing = await MyGlobal.prisma.todo_app_todouser.findUniqueOrThrow({
    where: { id: todoUserId },
    select: {
      id: true,
      email: true,
      display_name: true,
      is_verified: true,
      status: true,
      mfa_enabled: true,
      failed_login_attempts: true,
      last_failed_login_at: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (existing.deleted_at) {
    throw new HttpException("Not Found", 404);
  }

  // Prepare ISO timestamp once and reuse
  const now = toISOStringSafe(new Date());

  try {
    const updated = await MyGlobal.prisma.todo_app_todouser.update({
      where: { id: todoUserId },
      data: {
        // Only include properties present in the DTO
        ...(body.email !== undefined && { email: body.email }),
        // displayName is optional and nullable: if undefined => skip; otherwise set (can be null to clear)
        ...(body.displayName === undefined
          ? {}
          : { display_name: body.displayName }),
        updated_at: now,
      },
    });

    return {
      id: updated.id as string & tags.Format<"uuid">,
      email: updated.email as string & tags.Format<"email">,
      displayName:
        updated.display_name === null
          ? null
          : (updated.display_name ?? undefined),
      isVerified: updated.is_verified,
      status: updated.status,
      mfaEnabled: updated.mfa_enabled,
      failedLoginAttempts: updated.failed_login_attempts ?? undefined,
      lastFailedLoginAt: updated.last_failed_login_at
        ? toISOStringSafe(updated.last_failed_login_at)
        : null,
      createdAt: toISOStringSafe(updated.created_at),
      updatedAt: now,
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new HttpException("Conflict: Email already in use", 400);
    }

    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteTodoAppAdminTodoUsersTodoUserId(props: {
  admin: AdminPayload;
  todoUserId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, todoUserId } = props;

  // Validate UUID format (business-level validation)
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (!uuidRegex.test(todoUserId)) {
    throw new HttpException("Invalid todoUserId format", 400);
  }

  // Check existence and soft-delete state
  const user = await MyGlobal.prisma.todo_app_todouser.findUnique({
    where: { id: todoUserId },
    select: { id: true, email: true, deleted_at: true, status: true },
  });

  if (user === null) {
    throw new HttpException("Not Found", 404);
  }

  // Idempotent: if already soft-deleted, return successfully
  if (user.deleted_at !== null) return;

  // Single timestamp for all operations
  const now = toISOStringSafe(new Date());

  try {
    await MyGlobal.prisma.$transaction([
      MyGlobal.prisma.todo_app_todouser.update({
        where: { id: todoUserId },
        data: {
          deleted_at: now,
          status: "pending_deletion",
          refresh_tokens_revoked_at: now,
          updated_at: now,
        },
      }),

      MyGlobal.prisma.todo_app_todouser_sessions.updateMany({
        where: {
          todo_app_todouser_id: todoUserId,
          expired_at: null,
        },
        data: { expired_at: now },
      }),

      MyGlobal.prisma.todo_app_admin_actions.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          todo_app_admin_id: admin.id,
          todo_app_admin_session_id: admin.session_id,
          todo_app_todouser_id: todoUserId,
          action: "soft_delete",
          reason: "Admin initiated soft-delete via admin API",
          target_type: "todo_user",
          target_id: todoUserId,
          created_at: now,
          updated_at: now,
        },
      }),

      MyGlobal.prisma.todo_app_audit_logs.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          todo_app_admin_id: admin.id,
          todo_app_admin_session_id: admin.session_id,
          todo_app_todouser_id: todoUserId,
          event_type: "delete",
          target_type: "todo_user",
          target_id: todoUserId,
          details: `Admin ${admin.id} performed soft-delete on todo user ${todoUserId} (${user.email})`,
          created_at: now,
          updated_at: now,
        },
      }),
    ]);

    return;
  } catch (error) {
    // Unexpected error
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { IPageITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodouserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function patchTodoAppTodoUserTodoUsersTodoUserIdSessions(props: {
  todoUser: TodouserPayload;
  todoUserId: string & tags.Format<"uuid">;
  body: ITodoAppTodouserSession.IRequest;
}): Promise<IPageITodoAppTodouserSession.ISummary> {
  const { todoUser, todoUserId, body } = props;

  // Ownership enforcement
  if (todoUser.id !== todoUserId) {
    throw new HttpException(
      "Unauthorized: You can only list your own sessions",
      403,
    );
  }

  // Verify that the target todo user exists and is active
  const targetUser = await MyGlobal.prisma.todo_app_todouser.findUnique({
    where: { id: todoUserId },
    select: {
      id: true,
      display_name: true,
      is_verified: true,
      status: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!targetUser || targetUser.deleted_at !== null) {
    throw new HttpException("Not Found", 404);
  }

  // Pagination and sorting defaults
  const page = (body.page ?? 1) as number &
    tags.Type<"int32"> &
    tags.Minimum<1> as number;
  const limit = (body.pageSize ?? 20) as number &
    tags.Type<"int32"> &
    tags.Minimum<1> as number;
  const skip = (page - 1) * limit;

  const sortField = (
    body.sortBy === "expiredAt" ? "expired_at" : "created_at"
  ) as "created_at" | "expired_at";
  const sortOrder = body.order === "asc" ? "asc" : "desc";

  // Prepare 'now' for active/expired filters
  const now = toISOStringSafe(new Date());

  // Build where condition using only DTO fields and schema-verified names
  const buildWhereCondition = () => {
    const where: Record<string, unknown> = {
      todo_app_todouser_id: todoUserId,
    };

    if (body.ip !== undefined && body.ip !== null) {
      where.ip = { contains: body.ip };
    }

    if (body.referrer !== undefined && body.referrer !== null) {
      where.referrer = { contains: body.referrer };
    }

    if (body.href !== undefined && body.href !== null) {
      where.href = { contains: body.href };
    }

    if (body.createdBefore !== undefined && body.createdBefore !== null) {
      where.created_at = {
        ...((where.created_at as Record<string, unknown>) ?? {}),
        lt: body.createdBefore,
      } as Record<string, unknown>;
    }

    if (body.createdAfter !== undefined && body.createdAfter !== null) {
      where.created_at = {
        ...((where.created_at as Record<string, unknown>) ?? {}),
        gt: body.createdAfter,
      } as Record<string, unknown>;
    }

    if (body.status === "active") {
      // active = not expired (expired_at is null OR expired_at > now)
      where.OR = [{ expired_at: null }, { expired_at: { gt: now } }];
    } else if (body.status === "expired") {
      // expired = expired_at is set and < now
      where.expired_at = { lt: now };
    }

    return where;
  };

  const whereCondition = buildWhereCondition();

  // Execute queries in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todouser_sessions.findMany({
      where: whereCondition,
      include: {
        todouser: {
          select: {
            id: true,
            display_name: true,
            is_verified: true,
            status: true,
            created_at: true,
            updated_at: true,
          },
        },
      },
      orderBy: {
        [sortField]: sortOrder,
      },
      skip,
