  const updated = await MyGlobal.prisma.todo_app_admin.update({
    where: { id: adminId },
    data: {
      display_name:
        body.displayName === undefined
          ? undefined
          : body.displayName === null
            ? null
            : body.displayName,
      role: body.role ?? undefined,
      is_active: body.isActive ?? undefined,
      updated_at: now,
    },
  });

  // Create admin action audit record
  await MyGlobal.prisma.todo_app_admin_actions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_admin_id: admin.id,
      todo_app_admin_session_id: admin.session_id,
      action: "update_admin",
      reason: null,
      target_type: "admin",
      target_id: adminId,
      details: JSON.stringify({
        before: {
          role: target.role,
          display_name: target.display_name,
          is_active: target.is_active,
        },
        after: {
          role: updated.role,
          display_name: updated.display_name,
          is_active: updated.is_active,
        },
      }),
      created_at: now,
      updated_at: now,
    },
  });

  // Create general audit log for system-wide traceability
  await MyGlobal.prisma.todo_app_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_admin_id: admin.id,
      todo_app_admin_session_id: admin.session_id,
      event_type: "update_admin",
      target_type: "admin",
      target_id: adminId,
      details: JSON.stringify({
        before: {
          role: target.role,
          display_name: target.display_name,
          is_active: target.is_active,
        },
        after: {
          role: updated.role,
          display_name: updated.display_name,
          is_active: updated.is_active,
        },
      }),
      created_at: now,
      updated_at: now,
    },
  });

  // Map database record to API DTO, converting Date -> ISO strings
  return {
    id: updated.id as string & tags.Format<"uuid">,
    email: updated.email as string & tags.Format<"email">,
    display_name:
      updated.display_name === null
        ? null
        : (updated.display_name ?? undefined),
    role: updated.role as ITodoAppAdminRole,
    is_active: updated.is_active,
    createdAt: toISOStringSafe(updated.created_at),
    updatedAt: toISOStringSafe(updated.updated_at),
    deletedAt: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteTodoAppAdminAdminsAdminId(props: {
  admin: AdminPayload;
  adminId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, adminId } = props;

  // Verify caller exists and is active
  const caller = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
  });

  if (!caller) throw new HttpException("Unauthorized: admin not found", 403);
  if (caller.deleted_at !== null || caller.is_active !== true)
    throw new HttpException("Unauthorized: inactive admin", 403);

  // Authorization: require superadmin role
  if (caller.role !== "superadmin")
    throw new HttpException("Forbidden: insufficient privileges", 403);

  // Load target admin
  const target = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: adminId },
  });

  if (!target) throw new HttpException("Not Found", 404);
  if (target.deleted_at !== null) throw new HttpException("Gone", 410);
  if (target.id === caller.id)
    throw new HttpException(
      "Forbidden: cannot delete your own admin account",
      403,
    );

  // Prepare timestamp once and reuse
  const now = toISOStringSafe(new Date());

  // Atomic operations: revoke sessions, soft-delete admin, record admin action and audit log
  await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.todo_app_admin_sessions.updateMany({
      where: {
        todo_app_admin_id: adminId,
        expired_at: null,
      },
      data: { expired_at: now },
    }),

    MyGlobal.prisma.todo_app_admin.update({
      where: { id: adminId },
      data: {
        deleted_at: now,
        is_active: false,
        updated_at: now,
      },
    }),

    MyGlobal.prisma.todo_app_admin_actions.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_admin_id: caller.id,
        todo_app_admin_session_id: admin.session_id,
        action: "soft_delete",
        target_type: "admin",
        target_id: adminId,
        details: `Admin ${caller.id} performed soft delete on admin ${adminId}`,
        created_at: now,
        updated_at: now,
      },
    }),

    MyGlobal.prisma.todo_app_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        todo_app_admin_id: caller.id,
        todo_app_admin_session_id: admin.session_id,
        event_type: "delete",
        target_type: "admin",
        target_id: adminId,
        details: `Admin ${caller.id} soft-deleted admin ${adminId}`,
        created_at: now,
        updated_at: now,
      },
    }),
  ]);

  return;
}

