import { ITodoAppList } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppList";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function getTodoAppTodoUserTasksTaskIdHistoryVersion(props: {
  todoUser: TodouserPayload;
  taskId: string & tags.Format<"uuid">;
  version: number & tags.Type<"int32">;
}): Promise<ITodoAppTaskSnapshot> {
  const { todoUser, taskId, version } = props;

  // Fetch the snapshot by composite key (todo_app_task_id + version)
  const snapshot = await MyGlobal.prisma.todo_app_task_snapshots.findFirst({
    where: {
      todo_app_task_id: taskId,
      version: version,
    },
  });

  if (!snapshot) {
    throw new HttpException("Not Found", 404);
  }

  // Fetch the current task to build the todo summary (and obtain list id)
  const task = await MyGlobal.prisma.todo_app_tasks.findUniqueOrThrow({
    where: { id: taskId },
  });

  // Fetch the list and include owner and membership for authorization
  const list = await MyGlobal.prisma.todo_app_lists.findUniqueOrThrow({
    where: { id: task.todo_app_list_id },
    include: {
      owner: true,
      todo_app_list_collaborators: {
        where: {
          todo_app_todouser_id: todoUser.id,
          deleted_at: null,
        },
      },
    },
  });

  // Authorization: owner OR collaborator (non-deleted)
  const isOwner = list.owner && list.owner.id === todoUser.id;
  const isCollaborator =
    Array.isArray(list.todo_app_list_collaborators) &&
    list.todo_app_list_collaborators.length > 0;

  if (!isOwner && !isCollaborator) {
    // Return 404 for unauthorized as per spec
    throw new HttpException("Not Found", 404);
  }

  // Conditionally fetch attributed user summary
  let attributedUser: ITodoAppTodoUser.ISummary | undefined = undefined;
  if (
    snapshot.todo_app_todouser_id !== null &&
    snapshot.todo_app_todouser_id !== undefined
  ) {
    const u = await MyGlobal.prisma.todo_app_todouser.findUnique({
      where: { id: snapshot.todo_app_todouser_id },
    });
    if (u) {
      attributedUser = {
        id: u.id,
        displayName: u.display_name ?? null,
        isVerified: u.is_verified,
        status: u.status ?? undefined,
        createdAt: toISOStringSafe(u.created_at),
        updatedAt: toISOStringSafe(u.updated_at),
      };
    }
  }

  // Conditionally fetch attributed session summary
  let attributedSession: ITodoAppTodouserSession.ISummary | undefined =
    undefined;
  if (
    snapshot.todo_app_todouser_session_id !== null &&
    snapshot.todo_app_todouser_session_id !== undefined
  ) {
    const s = await MyGlobal.prisma.todo_app_todouser_sessions.findUnique({
      where: { id: snapshot.todo_app_todouser_session_id },
      include: { todouser: true },
    });
    if (s) {
      const sessionUser = s.todouser
        ? {
            id: s.todouser.id,
            displayName: s.todouser.display_name ?? null,
            isVerified: s.todouser.is_verified,
            status: s.todouser.status ?? undefined,
            createdAt: toISOStringSafe(s.todouser.created_at),
            updatedAt: toISOStringSafe(s.todouser.updated_at),
          }
        : undefined;

      attributedSession = {
        id: s.id,
        user: sessionUser!,
        ip: s.ip,
        href: s.href ?? undefined,
        referrer: s.referrer ?? null,
        createdAt: toISOStringSafe(s.created_at),
        expiredAt: s.expired_at ? toISOStringSafe(s.expired_at) : null,
      };
    }
  }

  // Build the todo summary (current task state)
  const todoSummary: ITodoAppTask.ISummary = {
    id: task.id,
    title: task.title,
    isCompleted: task.is_completed,
    dueDate: task.due_date ? toISOStringSafe(task.due_date) : null,
    createdAt: toISOStringSafe(task.created_at),
    updatedAt: toISOStringSafe(task.updated_at),
    list: {
      id: list.id,
      title: list.title,
      visibility: list.visibility,
      owner: {
        id: list.owner.id,
        displayName: list.owner.display_name ?? null,
        isVerified: list.owner.is_verified,
        status: list.owner.status ?? undefined,
        createdAt: toISOStringSafe(list.owner.created_at),
        updatedAt: toISOStringSafe(list.owner.updated_at),
      },
      description: list.description ?? null,
      createdAt: toISOStringSafe(list.created_at),
      updatedAt: toISOStringSafe(list.updated_at),
      deletedAt: list.deleted_at ? toISOStringSafe(list.deleted_at) : undefined,
    },
  };

  // Construct the final snapshot DTO
  const result: ITodoAppTaskSnapshot = {
    id: snapshot.id,
    todo: todoSummary,
    user: attributedUser ?? undefined,
    userSession: attributedSession ?? undefined,
    title: snapshot.title,
    description: snapshot.description ?? null,
    isCompleted: snapshot.is_completed,
    completedAt: snapshot.completed_at
      ? toISOStringSafe(snapshot.completed_at)
      : null,
    dueDate: snapshot.due_date ? toISOStringSafe(snapshot.due_date) : null,
    originalCreatedAt: snapshot.original_created_at
      ? toISOStringSafe(snapshot.original_created_at)
      : null,
    snapshotCreatedAt: toISOStringSafe(snapshot.snapshot_created_at),
    version: snapshot.version,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPageITodoAppTaskCompletionByDay } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTaskCompletionByDay";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTaskCompletionByDay } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskCompletionByDay";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdminStatisticsTaskCompletionByDay(props: {
  admin: AdminPayload;
}): Promise<IPageITodoAppTaskCompletionByDay.ISummary> {
  const { admin } = props;

  // Authorization: ensure admin exists and is active
  const adminRecord = await MyGlobal.prisma.todo_app_admin.findUnique({
    where: { id: admin.id },
    select: { id: true, is_active: true, deleted_at: true },
  });

  if (
    !adminRecord ||
    adminRecord.deleted_at !== null ||
    adminRecord.is_active !== true
  ) {
    throw new HttpException("Unauthorized: admin not active or not found", 403);
  }

  try {
    // Fetch tasks with minimal fields and parent list's deleted_at to filter out inactive lists
    const tasks = await MyGlobal.prisma.todo_app_tasks.findMany({
      where: { deleted_at: null },
      select: {
        id: true,
        created_at: true,
        completed_at: true,
        is_completed: true,
        todo_app_list_id: true,
        list: { select: { deleted_at: true } },
      },
    });

    const createdCounts = new Map<string, number>();
    const completedCounts = new Map<string, number>();

    for (const t of tasks) {
      // Exclude tasks whose parent list is soft-deleted
      if (t.list && t.list.deleted_at !== null) continue;

      const createdIso = toISOStringSafe(t.created_at);
      const createdDay = createdIso.slice(0, 10); // YYYY-MM-DD UTC
      createdCounts.set(createdDay, (createdCounts.get(createdDay) ?? 0) + 1);

      if (t.completed_at) {
        const completedIso = toISOStringSafe(t.completed_at);
        const completedDay = completedIso.slice(0, 10);
        completedCounts.set(
          completedDay,
          (completedCounts.get(completedDay) ?? 0) + 1,
        );
      }
    }

    const allDates = Array.from(
      new Set([...createdCounts.keys(), ...completedCounts.keys()]),
    );
    allDates.sort();

    const data = allDates.map((date) => ({
      date,
      completedCount: Number(completedCounts.get(date) ?? 0),
    }));

    const pagination = {
      current: Number(1),
      limit: Number(data.length),
      records: Number(data.length),
      pages: Number(1),
    };

    return {
      pagination,
      data,
    };
  } catch (_err) {
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGlobalSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGlobalSearch";
import { IPageITodoAppSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSearchResult";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSearchResult";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function patchTodoAppTodoUserSearchGlobal(props: {
  todoUser: TodouserPayload;
  body: ITodoAppGlobalSearch.IRequest;
}): Promise<IPageITodoAppSearchResult.ISummary> {
  const { todoUser, body } = props;

  if (!todoUser || !todoUser.id) {
    throw new HttpException("Unauthorized", 401);
  }

  const query = body.query ?? undefined;
  const page = Number(body.page ?? 1);
  const limit = Number(body.pageSize ?? 25);
  const entityFilters = body.entityFilters ?? ["task", "list", "user", "tag"];

  const escapeRegExp = (s: string) =>
    s.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&");

  const scoreFor = (text: string | null | undefined, q: string | undefined) => {
    if (!q || !text) return 0;
    const low = text.toLowerCase();
    const qlow = q.toLowerCase();
    let score = 0;
    if (low.includes(qlow)) score += 10;
    const safe = escapeRegExp(qlow);
    const occurrences = (low.match(new RegExp(safe, "g")) || []).length;
    score += occurrences;
    return score;
  };

  try {
    const tasksPromise = entityFilters.includes("task")
      ? MyGlobal.prisma.todo_app_tasks.findMany({
          where: {
            deleted_at: null,
            ...(query !== undefined &&
              query !== null && {
                OR: [
                  { title: { contains: query } },
                  { description: { contains: query } },
                ],
              }),
            OR: [
              { list: { visibility: { not: "private" } } },
              { list: { todo_app_todouser_id: todoUser.id } },
              {
                list: {
                  todo_app_list_collaborators: {
                    some: {
                      todo_app_todouser_id: todoUser.id,
                      deleted_at: null,
                    },
                  },
                },
              },
            ],
          },
          select: {
            id: true,
            title: true,
            description: true,
            todo_app_list_id: true,
            created_at: true,
            updated_at: true,
          },
          take: limit * 5,
        })
      : Promise.resolve([]);

    const listsPromise = entityFilters.includes("list")
      ? MyGlobal.prisma.todo_app_lists.findMany({
          where: {
            deleted_at: null,
            ...(query !== undefined &&
              query !== null && {
                OR: [
                  { title: { contains: query } },
                  { description: { contains: query } },
                ],
              }),
            OR: [
              { visibility: { not: "private" } },
              { todo_app_todouser_id: todoUser.id },
              {
                todo_app_list_collaborators: {
                  some: { todo_app_todouser_id: todoUser.id, deleted_at: null },
                },
              },
            ],
          },
          select: {
            id: true,
            title: true,
            description: true,
            visibility: true,
            todo_app_todouser_id: true,
            created_at: true,
            updated_at: true,
          },
          take: limit * 5,
        })
      : Promise.resolve([]);

    const tagsPromise = entityFilters.includes("tag")
      ? MyGlobal.prisma.todo_app_task_tags.findMany({
          where: {
            deleted_at: null,
            ...(query !== undefined &&
              query !== null && { name: { contains: query } }),
          },
          select: { id: true, name: true, created_at: true, updated_at: true },
          take: limit * 5,
        })
      : Promise.resolve([]);

    const usersPromise = entityFilters.includes("user")
      ? MyGlobal.prisma.todo_app_todouser.findMany({
          where: {
            deleted_at: null,
            ...(query !== undefined &&
              query !== null && {
                OR: [
                  { display_name: { contains: query } },
                  { email: { contains: query } },
                ],
              }),
          },
          select: {
            id: true,
            display_name: true,
            email: true,
            created_at: true,
            updated_at: true,
          },
          take: limit * 5,
        })
      : Promise.resolve([]);

    const [tasks, lists, tags, users] = await Promise.all([
      tasksPromise,
      listsPromise,
      tagsPromise,
      usersPromise,
    ]);

    const results: Array<ITodoAppSearchResult.ISummary> = [];

    for (const t of tasks) {
      const s =
        scoreFor(t.title, query) + scoreFor(t.description ?? null, query);
      results.push({
        id: t.id,
        targetType: "task",
        targetId: t.id,
        title: t.title,
        snippet: body.includeSnippets
          ? (t.description ?? undefined)
          : undefined,
        href: `/lists/${t.todo_app_list_id}/tasks/${t.id}`,
        score: s > 0 ? s : undefined,
        createdAt: t.created_at ? toISOStringSafe(t.created_at) : undefined,
        updatedAt: t.updated_at ? toISOStringSafe(t.updated_at) : undefined,
      });
    }

    for (const l of lists) {
      const s =
        scoreFor(l.title, query) + scoreFor(l.description ?? null, query);
      results.push({
        id: l.id,
        targetType: "list",
        targetId: l.id,
        title: l.title,
        snippet: body.includeSnippets
          ? (l.description ?? undefined)
          : undefined,
        href: `/lists/${l.id}`,
        score: s > 0 ? s : undefined,
        createdAt: l.created_at ? toISOStringSafe(l.created_at) : undefined,
        updatedAt: l.updated_at ? toISOStringSafe(l.updated_at) : undefined,
      });
    }

    for (const tg of tags) {
      const s = scoreFor(tg.name, query);
      results.push({
        id: tg.id,
        targetType: "tag",
        targetId: tg.id,
        title: tg.name,
        snippet: undefined,
        href: `/tags/${tg.id}`,
        score: s > 0 ? s : undefined,
        createdAt: tg.created_at ? toISOStringSafe(tg.created_at) : undefined,
        updatedAt: tg.updated_at ? toISOStringSafe(tg.updated_at) : undefined,
      });
    }

    for (const u of users) {
      const allowed =
        body.restrictToAccessible === false || u.id === todoUser.id;
      if (!allowed) continue;
      const display = u.display_name ?? u.email;
      const s = scoreFor(display, query) + scoreFor(u.email ?? null, query);
      results.push({
        id: u.id,
        targetType: "user",
        targetId: u.id,
        title: display,
        snippet: undefined,
        href: `/users/${u.id}`,
        score: s > 0 ? s : undefined,
        createdAt: u.created_at ? toISOStringSafe(u.created_at) : undefined,
        updatedAt: u.updated_at ? toISOStringSafe(u.updated_at) : undefined,
      });
    }

    const sorted = results.sort((a, b) => {
      const sortBy = body.sortBy ?? "relevance";
      if (sortBy === "createdAt") {
        const ta = a.createdAt ?? "";
        const tb = b.createdAt ?? "";
        if (ta === tb) return 0;
        return (body.order === "asc" ? 1 : -1) * (ta < tb ? -1 : 1);
      }
      const sa = a.score ?? 0;
      const sb = b.score ?? 0;
      if (sb === sa) return 0;
      return sb - sa;
    });

    const total = sorted.length;
    const pages = Math.max(1, Math.ceil(total / limit));
    const start = (page - 1) * limit;
    const pageData = sorted.slice(start, start + limit);

    return {
      pagination: {
        current: Number(page),
        limit: Number(limit),
        records: total,
        pages: Number(pages),
      },
      data: pageData,
    };
  } catch (err) {
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
